_SR_V4_PRUNE_TRIAL_BRANCH_PREFIX = "sr_v4_prune_trial:"


def _sr_v4_prune_trial_branch_id(
    *,
    selector_step: int,
    candidate_index: int,
    candidate_label: str,
    parent_branch_id: str | None = None,
) -> str:
    """Return the deterministic estimator-consumer id for one exact prune trial."""

    identity = {
        "selector_step": int(selector_step),
        "candidate_index": int(candidate_index),
        "candidate_label": str(candidate_label),
    }
    if parent_branch_id not in {None, ""}:
        identity["parent_branch_id"] = str(parent_branch_id)
    digest = hashlib.sha256(
        json.dumps(
            identity,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
            allow_nan=False,
        ).encode("utf-8")
    ).hexdigest()
    return f"{_SR_V4_PRUNE_TRIAL_BRANCH_PREFIX}{digest}"


def _sr_v4_prune_trial_branch_partition(
    history_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Recover committed and discarded exact-prune estimator consumers.

    V4 executes at most one exact delete/refit trial per controller round.  Its
    estimator calls are recorded under a speculative consumer id until the
    measured acceptance decision is known.  This history-only reconstruction
    keeps accepted trial work on the surviving lineage and rejected trial work
    separately selectable without moving or duplicating primitives.
    """

    accepted: list[str] = []
    rejected: list[str] = []
    trial_rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for history_index, history_row in enumerate(history_rows):
        if not isinstance(history_row, Mapping):
            continue
        prune_raw = history_row.get("post_admission_prune")
        if not isinstance(prune_raw, Mapping):
            continue
        work_raw = prune_raw.get("phase1_prune_exact_refit_work_accounting")
        if work_raw is None:
            continue
        if not isinstance(work_raw, Mapping):
            raise RuntimeError(
                "SR-SNAKE v4 prune estimator accounting must be a mapping."
            )
        work = dict(work_raw)
        if work.get("schema") != "sr_v4_prune_exact_refit_work_accounting_v1":
            raise RuntimeError(
                "SR-SNAKE v4 prune estimator accounting schema is unsupported."
            )
        branch_id = str(work.get("estimator_trial_branch_id", "")).strip()
        if not branch_id.startswith(_SR_V4_PRUNE_TRIAL_BRANCH_PREFIX):
            raise RuntimeError(
                "SR-SNAKE v4 exact prune work is missing its speculative "
                "estimator consumer id."
            )
        if branch_id in seen:
            raise RuntimeError(
                "SR-SNAKE v4 exact prune estimator consumer id was reused."
            )
        seen.add(branch_id)
        classification = str(work.get("classification", "")).strip()
        accepted_count = int(prune_raw.get("accepted_count", 0) or 0)
        if classification == "committed_prune":
            if accepted_count != 1:
                raise RuntimeError(
                    "Committed SR-SNAKE v4 prune work disagrees with acceptance."
                )
            accepted.append(branch_id)
        elif classification == "discarded_prune":
            if accepted_count != 0:
                raise RuntimeError(
                    "Discarded SR-SNAKE v4 prune work disagrees with acceptance."
                )
            rejected.append(branch_id)
        else:
            raise RuntimeError(
                "SR-SNAKE v4 prune estimator classification is invalid."
            )
        trial_rows.append(
            {
                "history_index": int(history_index),
                "controller_round": int(history_row.get("depth", history_index + 1)),
                "classification": classification,
                "estimator_trial_branch_id": branch_id,
                "nfev": int(work.get("nfev", 0) or 0),
            }
        )
    if set(accepted).intersection(rejected):
        raise RuntimeError(
            "SR-SNAKE v4 accepted and rejected prune consumers overlap."
        )
    return {
        "schema": "sr_v4_prune_trial_branch_partition_v1",
        "accepted_trial_branch_ids": list(accepted),
        "rejected_trial_branch_ids": list(rejected),
        "trial_rows": trial_rows,
    }


def _normalize_sr_material_window_prune_source_geometry(
    *,
    selector_summary: Mapping[str, Any],
    post_admission_labels: Sequence[str],
    post_admission_theta: Sequence[float] | np.ndarray,
) -> dict[str, Any]:
    """Normalize the already measured Phase-III ``W+c`` workspace for prune.

    This helper is deliberately measurement-free.  The material-window scorer
    stores candidate gradients as *descent* gradients, while the affine-delete
    trust solver consumes the ordinary energy gradient.  The only numerical
    conversion performed here is therefore ``g_energy = -g_descent``.
    Missing blocks or identity receipts fail closed; callers must never repair
    the workspace by measuring a second full-logical geometry.
    """

    summary = dict(selector_summary)
    if str(summary.get("schema", "")) != (
        HISTORICAL_SINGLETON_COORDINATE_MODEL_SCHEMA
    ):
        raise RuntimeError(
            "Prune source reuse requires the authoritative historical "
            "singleton coordinate-model schema."
        )
    if str(summary.get("joint_batch_context_mode", "")) != (
        BATCH_JOINT_CONTEXT_ACTIVE_WINDOW_V1
    ):
        raise RuntimeError(
            "Prune source reuse requires the measured active W-plus-candidate "
            "context."
        )
    if str(summary.get("joint_linear_solve_policy_effective", "")) != (
        JOINT_LINEAR_SOLVE_SUPPORTED_METRIC_PROJECTED_GENERALIZED_TRUST_V1
    ):
        raise RuntimeError(
            "Prune source reuse requires support-projected non-whitened "
            "Phase III."
        )
    if not bool(summary.get("feasible", False)):
        raise RuntimeError(
            "Prune source reuse received an infeasible Phase-III workspace."
        )

    accounting = summary.get("material_window_estimator_accounting")
    if not isinstance(accounting, Mapping) or str(accounting.get("schema", "")) != (
        "phase3_material_window_estimator_accounting_v1"
    ):
        raise RuntimeError(
            "Prune source reuse is missing the material-window estimator "
            "identity receipt."
        )
    plan = accounting.get("source_plan")
    if not isinstance(plan, Mapping) or str(plan.get("schema", "")) != (
        "phase3_material_window_estimator_acquisition_plan_v1"
    ):
        raise RuntimeError(
            "Prune source reuse is missing the authoritative acquisition plan."
        )
    summary_plan = summary.get("estimator_acquisition_plan")
    if not isinstance(summary_plan, Mapping) or dict(summary_plan) != dict(plan):
        raise RuntimeError(
            "Prune source reuse acquisition-plan identity drifted between the "
            "coordinate model and estimator ledger."
        )

    primitive_ids = sorted(
        set(str(value) for value in accounting.get("primitive_ids", ()))
    )
    if not primitive_ids:
        raise RuntimeError(
            "Prune source reuse has no registered estimator primitive IDs."
        )
    if int(accounting.get("unique_primitive_id_count", -1)) != len(primitive_ids):
        raise RuntimeError(
            "Prune source reuse primitive-ID count does not reconcile."
        )

    full_active_indices = [int(value) for value in plan.get("active_indices", ())]
    if full_active_indices != list(range(len(full_active_indices))):
        raise RuntimeError(
            "Prune source reuse requires an ordered complete pre-admission "
            "coordinate registry."
        )
    pre_count = int(len(full_active_indices))
    labels = [str(value) for value in post_admission_labels]
    theta_post = np.asarray(post_admission_theta, dtype=float).reshape(-1)
    if len(labels) != pre_count + 1 or theta_post.shape != (pre_count + 1,):
        raise RuntimeError(
            "Prune source reuse expected one singleton admission between the "
            "measured source and post-refit ansatz."
        )
    if not np.all(np.isfinite(theta_post)):
        raise RuntimeError("Prune source reuse received nonfinite parameters.")

    receipt = summary.get("material_window_receipt")
    refresh = summary.get("material_window_refresh")
    if not isinstance(receipt, Mapping):
        raise RuntimeError("Prune source reuse lost its material-window receipt.")
    final_active_raw = (
        refresh.get("final_active_indices")
        if isinstance(refresh, Mapping)
        else None
    )
    if isinstance(final_active_raw, Sequence) and not isinstance(
        final_active_raw, (str, bytes, bytearray)
    ):
        active_pre_indices = [
            int(value) for value in final_active_raw
        ]
    else:
        active_pre_indices = [
            int(value) for value in receipt.get("retained_indices", ())
        ]
    if (
        len(set(active_pre_indices)) != len(active_pre_indices)
        or any(index < 0 or index >= pre_count for index in active_pre_indices)
    ):
        raise RuntimeError(
            "Prune source reuse contains an invalid retained-coordinate window."
        )
    active_labels = [
        str(value) for value in summary.get("active_coordinate_identities", ())
    ]
    if len(active_labels) != len(active_pre_indices):
        raise RuntimeError(
            "Prune source reuse active-coordinate identities do not match W."
        )

    candidate_identities = summary.get("batch_coordinate_identities")
    if not (
        isinstance(candidate_identities, Sequence)
        and not isinstance(candidate_identities, (str, bytes, bytearray))
        and len(candidate_identities) == 1
        and isinstance(candidate_identities[0], Mapping)
    ):
        raise RuntimeError(
            "Prune source reuse requires exactly one authoritative candidate "
            "identity."
        )
    candidate_identity = dict(candidate_identities[0])
    candidate_position = int(summary.get("position_id", -1))
    candidate_label = str(summary.get("candidate_label", ""))
    candidate_pool_index = int(summary.get("candidate_pool_index", -1))
    candidate_identity_label_before_binding = str(
        candidate_identity.get("candidate_label", "")
    )
    for field, expected_value in (
        ("candidate_position_id", candidate_position),
        ("candidate_pool_index", candidate_pool_index),
    ):
        if int(plan.get(field, -2)) != int(expected_value) or int(
            accounting.get(field, -3)
        ) != int(expected_value):
            raise RuntimeError(
                f"Prune source reuse candidate {field} identity drifted."
            )
    candidate_identity_label_placeholder_bound = bool(
        not candidate_identity_label_before_binding
    )
    if candidate_identity_label_placeholder_bound:
        candidate_identity["candidate_label"] = candidate_label
    if (
        str(plan.get("candidate_label", "")) != candidate_label
        or str(accounting.get("candidate_label", "")) != candidate_label
        or str(candidate_identity.get("candidate_label", "")) != candidate_label
        or int(candidate_identity.get("candidate_pool_index", -2))
        != candidate_pool_index
        or int(candidate_identity.get("position_id", -2)) != candidate_position
    ):
        raise RuntimeError("Prune source reuse candidate identity drifted.")
    if candidate_position < 0 or candidate_position > pre_count:
        raise RuntimeError("Prune source reuse candidate position is out of range.")

    active_post_indices = [
        int(index if index < candidate_position else index + 1)
        for index in active_pre_indices
    ]
    if [labels[index] for index in active_post_indices] != active_labels:
        raise RuntimeError(
            "Prune source reuse active-coordinate labels drifted after admission."
        )
    if labels[candidate_position] != candidate_label:
        raise RuntimeError(
            "Prune source reuse candidate label drifted after admission."
        )
    model_post_indices = [*active_post_indices, int(candidate_position)]

    window_count = int(len(active_pre_indices))

    def _matrix(name: str, shape: tuple[int, ...]) -> np.ndarray:
        value = np.asarray(summary.get(name), dtype=float)
        if value.shape != shape or not np.all(np.isfinite(value)):
            raise RuntimeError(
                f"Prune source reuse {name} is missing, nonfinite, or has "
                f"shape {value.shape!r}; expected {shape!r}."
            )
        return value

    G_AA = _matrix("G_AA_raw", (window_count, window_count))
    G_AB = _matrix("G_AB_raw", (window_count, 1))
    G_BB = _matrix("G_BB_raw", (1, 1))
    H_AA = _matrix("H_AA_raw", (window_count, window_count))
    H_AB = _matrix("H_AB_raw", (window_count, 1))
    H_BB = _matrix("H_BB_raw", (1, 1))
    g_A_descent = _matrix("g_A", (window_count,))
    g_B_descent = _matrix("g_B", (1,))
    for name, value in (("G_AA_raw", G_AA), ("H_AA_raw", H_AA)):
        if not np.allclose(value, value.T, rtol=1.0e-8, atol=1.0e-10):
            raise RuntimeError(f"Prune source reuse {name} is not symmetric.")

    metric_pairs = {
        tuple(sorted((int(pair[0]), int(pair[1]))))
        for pair in plan.get("old_old_metric_pairs_acquired", ())
        if isinstance(pair, Sequence)
        and not isinstance(pair, (str, bytes, bytearray))
        and len(pair) == 2
    }
    hessian_pairs = {
        tuple(sorted((int(pair[0]), int(pair[1]))))
        for pair in plan.get("old_old_hessian_pairs_acquired", ())
        if isinstance(pair, Sequence)
        and not isinstance(pair, (str, bytes, bytearray))
        and len(pair) == 2
    }
    screen_diagonals = {
        (int(index), int(index))
        for index in plan.get("screen_gram_diagonal_indices", ())
    }
    required_pairs = {
        (int(left), int(right))
        for row, left in enumerate(active_pre_indices)
        for right in active_pre_indices[row:]
    }
    if not required_pairs.issubset(metric_pairs.union(screen_diagonals)):
        raise RuntimeError(
            "Prune source reuse lacks a measured retained Gram entry."
        )
    if not required_pairs.issubset(hessian_pairs):
        raise RuntimeError(
            "Prune source reuse lacks a measured retained Hessian entry."
        )
    if not set(active_pre_indices).issubset(
        set(int(value) for value in plan.get("active_gradient_indices_acquired", ()))
    ):
        raise RuntimeError(
            "Prune source reuse lacks a measured retained gradient entry."
        )
    for field in (
        "candidate_cross_gram_active_indices",
        "candidate_cross_hessian_active_indices",
    ):
        if not set(active_pre_indices).issubset(
            set(int(value) for value in plan.get(field, ()))
        ):
            raise RuntimeError(
                f"Prune source reuse lacks a measured {field} entry."
            )
    if not all(
        bool(plan.get(field, False))
        for field in (
            "candidate_self_gram_acquired",
            "candidate_self_hessian_acquired",
            "candidate_gradient_acquired",
        )
    ):
        raise RuntimeError(
            "Prune source reuse lacks candidate self geometry or gradient."
        )

    gram = np.block([[G_AA, G_AB], [G_AB.T, G_BB]])
    hessian = np.block([[H_AA, H_AB], [H_AB.T, H_BB]])
    gram = 0.5 * (gram + gram.T)
    hessian = 0.5 * (hessian + hessian.T)
    descent_gradient = np.concatenate([g_A_descent, g_B_descent])
    energy_gradient = -np.asarray(descent_gradient, dtype=float)
    theta_model = np.asarray(theta_post[model_post_indices], dtype=float)
    return {
        "theta": theta_model,
        "gradient": energy_gradient,
        "hessian": hessian,
        "metric": gram,
        "model_post_indices": list(model_post_indices),
        "receipt": {
            "schema": "sr_material_window_prune_source_geometry_reuse_v1",
            "source_coordinate_context": "pre_admission_material_window_W_plus_candidate_v1",
            "prune_coordinate_context": "post_admission_logical_indices_v1",
            "pre_admission_parameter_count": int(pre_count),
            "post_admission_parameter_count": int(pre_count + 1),
            "active_pre_indices": list(active_pre_indices),
            "active_post_indices": list(active_post_indices),
            "active_coordinate_identities": [
                {
                    "pre_admission_index": int(pre_index),
                    "post_admission_index": int(post_index),
                    "label": str(label),
                }
                for pre_index, post_index, label in zip(
                    active_pre_indices,
                    active_post_indices,
                    active_labels,
                    strict=True,
                )
            ],
            "candidate_post_index": int(candidate_position),
            "model_post_indices": list(model_post_indices),
            "model_post_labels": [labels[index] for index in model_post_indices],
            "candidate_identity": dict(candidate_identity),
            "candidate_identity_binding": {
                "schema": "sr_material_window_prune_candidate_identity_binding_v1",
                "source": (
                    "authoritative_plan_and_estimator_accounting_v1"
                    if candidate_identity_label_placeholder_bound
                    else "coordinate_identity_already_complete_v1"
                ),
                "candidate_label_before_binding": str(
                    candidate_identity_label_before_binding
                ),
                "candidate_label_after_binding": str(
                    candidate_identity["candidate_label"]
                ),
                "placeholder_filled": bool(
                    candidate_identity_label_placeholder_bound
                ),
                "pool_index_and_position_crosschecked": True,
                "numeric_geometry_modified": False,
                "incremental_quantum_query_charge": 0,
            },
            "state_fingerprint": str(plan.get("state_fingerprint", "")),
            "ordered_scaffold_fingerprint": str(
                plan.get("ordered_scaffold_fingerprint", "")
            ),
            "theta_fingerprint": str(plan.get("theta_fingerprint", "")),
            "hamiltonian_fingerprint": str(
                plan.get("hamiltonian_fingerprint", "")
            ),
            "candidate_coordinate_fingerprint": str(
                plan.get("candidate_coordinate_fingerprint", "")
            ),
            "source_gradient_convention": "sr_descent_gradient_v1",
            "prune_gradient_convention": "energy_gradient_v1",
            "gradient_conversion": "negate_source_descent_gradient_v1",
            "primitive_ids": list(primitive_ids),
            "incremental_quantum_query_charge": 0,
            "duplicate_measurement_performed": False,
            "unsupported_logical_coordinates_nominated": False,
        },
    }


def _sr_material_window_prune_deletion_coordinates(
    *,
    model_post_indices: Sequence[int],
    source_geometry_reuse_receipt: Mapping[str, Any],
) -> list[tuple[int, int]]:
    """Map only retained pre-admission coordinates into the prune model.

    The material-window source model is ordered as ``W`` followed by the newly
    admitted singleton.  That singleton is required to complete the measured
    response model, but it is not an old coordinate eligible for deletion in
    the same post-admission prune transaction.  An empty ``W`` is therefore a
    valid zero-candidate prune model rather than permission to delete the
    admitted singleton or fall back to historical ranking.
    """

    model_indices = [int(value) for value in model_post_indices]
    active_post_indices = [
        int(value)
        for value in source_geometry_reuse_receipt.get(
            "active_post_indices", ()
        )
    ]
    try:
        candidate_post_index = int(
            source_geometry_reuse_receipt["candidate_post_index"]
        )
    except (KeyError, TypeError, ValueError) as exc:
        raise RuntimeError(
            "Material-window prune source reuse lost the admitted singleton "
            "identity."
        ) from exc
    expected_model_indices = [
        *active_post_indices,
        int(candidate_post_index),
    ]
    if model_indices != expected_model_indices:
        raise RuntimeError(
            "Material-window prune source model order drifted from W plus the "
            "admitted singleton."
        )
    if (
        len(set(active_post_indices)) != len(active_post_indices)
        or int(candidate_post_index) in set(active_post_indices)
    ):
        raise RuntimeError(
            "Material-window prune deletion identities are not unique or "
            "include the admitted singleton."
        )
    return [
        (int(model_index), int(post_index))
        for model_index, post_index in enumerate(active_post_indices)
    ]


def _sr_v4_prune_estimator_accounting_views(
    *,
    ledger: EstimatorCallLedger,
    history_rows: Sequence[Mapping[str, Any]],
    base_winning_branch_ids: Sequence[str] = (),
) -> dict[str, Any]:
    """Build a disjoint unique-call partition plus raw rejected-trial work."""

    partition = _sr_v4_prune_trial_branch_partition(history_rows)
    source_reuse_receipts: list[dict[str, Any]] = []
    explicit_shared_source_ids: set[str] = set()
    for history_index, history_row in enumerate(history_rows):
        prune_payload = history_row.get("post_admission_prune")
        if not isinstance(prune_payload, Mapping):
            continue
        reuse_receipt = prune_payload.get(
            "phase1_prune_source_geometry_reuse"
        )
        if reuse_receipt is None:
            continue
        if not isinstance(reuse_receipt, Mapping) or str(
            reuse_receipt.get("schema", "")
        ) != "sr_material_window_prune_source_geometry_reuse_v1":
            raise RuntimeError(
                "SR-SNAKE prune source geometry reuse receipt is malformed."
            )
        if (
            int(reuse_receipt.get("incremental_quantum_query_charge", -1)) != 0
            or bool(reuse_receipt.get("duplicate_measurement_performed", True))
        ):
            raise RuntimeError(
                "SR-SNAKE prune source geometry reuse must be zero-query and "
                "measurement-free."
            )
        receipt_ids = sorted(
            set(str(value) for value in reuse_receipt.get("primitive_ids", ()))
        )
        if not receipt_ids:
            raise RuntimeError(
                "SR-SNAKE prune source geometry reuse lost its primitive IDs."
            )
        explicit_shared_source_ids.update(receipt_ids)
        source_reuse_receipts.append(
            {
                "history_index": int(history_index),
                "controller_round": int(
                    history_row.get("depth", history_index + 1)
                ),
                "primitive_ids": list(receipt_ids),
            }
        )
    accepted_ids = [
        str(value) for value in partition["accepted_trial_branch_ids"]
    ]
    rejected_ids = [
        str(value) for value in partition["rejected_trial_branch_ids"]
    ]
    winning_branch_ids = sorted(
        set(str(value) for value in base_winning_branch_ids).union(accepted_ids)
    )
    all_summary = ledger.summary()
    winning_summary = ledger.summary(
        branch_ids=winning_branch_ids,
        include_unbranched=True,
    )
    rejected_consumer_summary = ledger.summary(
        branch_ids=rejected_ids,
        include_unbranched=False,
    )
    rejected_execution = ledger.occurrence_summary(
        branch_ids=rejected_ids,
        include_unbranched=False,
    )
    all_ids = set(str(value) for value in all_summary.get("primitive_ids", []))
    winning_ids = set(
        str(value) for value in winning_summary.get("primitive_ids", [])
    )
    rejected_consumer_ids = set(
        str(value)
        for value in rejected_consumer_summary.get("primitive_ids", [])
    )
    if not winning_ids.issubset(all_ids) or not rejected_consumer_ids.issubset(
        all_ids
    ):
        raise RuntimeError(
            "SR-SNAKE v4 prune estimator consumers escaped the total ledger."
        )
    if not explicit_shared_source_ids.issubset(all_ids):
        raise RuntimeError(
            "SR-SNAKE prune shared source geometry references primitives "
            "absent from the total ledger."
        )
    if not explicit_shared_source_ids.issubset(winning_ids):
        raise RuntimeError(
            "SR-SNAKE prune shared source geometry escaped the winning "
            "lineage's unbranched source work."
        )
    rejected_shared_with_winner_ids = rejected_consumer_ids.intersection(
        winning_ids
    )
    winning_excluding_shared_ids = winning_ids.difference(
        explicit_shared_source_ids
    )
    discarded_only_ids = all_ids.difference(winning_ids)
    disjoint_union = (
        explicit_shared_source_ids
        .union(winning_excluding_shared_ids)
        .union(discarded_only_ids)
    )
    if (
        explicit_shared_source_ids.intersection(winning_excluding_shared_ids)
        or explicit_shared_source_ids.intersection(discarded_only_ids)
        or winning_excluding_shared_ids.intersection(discarded_only_ids)
        or disjoint_union != all_ids
    ):
        raise RuntimeError(
            "SR-SNAKE v4 prune estimator unique-call partition does not close."
        )
    shared_source_summary = ledger.summary_for_primitive_ids(
        explicit_shared_source_ids
    )
    winning_excluding_shared_summary = ledger.summary_for_primitive_ids(
        winning_excluding_shared_ids
    )
    discarded_only_summary = ledger.summary_for_primitive_ids(
        discarded_only_ids
    )
    partition_s_unique = int(
        shared_source_summary["S_unique"]
        + winning_excluding_shared_summary["S_unique"]
        + discarded_only_summary["S_unique"]
    )
    if partition_s_unique != int(all_summary.get("S_unique", -1)):
        raise RuntimeError(
            "SR-SNAKE prune shared/winning/discarded S_unique partition does "
            "not reconcile with the unique-primitive diagnostic."
        )
    return {
        **{
            key: value
            for key, value in partition.items()
            if key != "schema"
        },
        "schema": "sr_v4_prune_estimator_accounting_views_v1",
        "all_work": dict(all_summary),
        "winning_branch_ids": list(winning_branch_ids),
        "winning_lineage": dict(winning_summary),
        "rejected_prune_consumer_unique": dict(rejected_consumer_summary),
        "rejected_prune_execution": dict(rejected_execution),
        "rejected_prune_shared_with_winner_ids": sorted(
            rejected_shared_with_winner_ids
        ),
        "shared_source_state": dict(shared_source_summary),
        "shared_source_state_reuse_receipts": source_reuse_receipts,
        "winning_lineage_excluding_shared_source": dict(
            winning_excluding_shared_summary
        ),
        "discarded_prune_only_by_unique_set_difference": dict(
            discarded_only_summary
        ),
        "primitive_set_reconciliation": {
            "partition": (
                "shared_source_plus_winning_excluding_shared_plus_"
                "discarded_only_v1"
            ),
            "pairwise_disjoint": True,
            "union_equals_all_work": True,
            "all_work_S_unique": int(all_summary.get("S_unique", 0)),
            "partition_S_unique": int(partition_s_unique),
            "shared_source_count": int(len(explicit_shared_source_ids)),
            "winning_excluding_shared_count": int(
                len(winning_excluding_shared_ids)
            ),
            "discarded_count": int(len(discarded_only_ids)),
            "all_work_count": int(len(all_ids)),
        },
    }


def _executed_s_alg_work_from_occurrence_summary(
    summary: Mapping[str, Any],
    *,
    scope: str,
) -> dict[str, Any]:
    """Normalize one executed-occurrence view into the Paper-I S_alg contract."""

    components = {
        component: int(summary.get(component, 0))
        for component in ("N_H_outer", "N_H_refit", "N_grad", "N_metric")
    }
    if any(value < 0 for value in components.values()):
        raise RuntimeError("Executed estimator component counts must be nonnegative.")
    s_alg = int(summary.get("total_call_occurrences", -1))
    if s_alg < 0 or s_alg != int(sum(components.values())):
        raise RuntimeError(
            "Executed estimator occurrences do not close to their components."
        )
    s_unique = int(summary.get("unique_primitive_count", -1))
    if s_unique < 0 or s_unique > s_alg:
        raise RuntimeError(
            "Executed estimator unique-primitive diagnostic is inconsistent."
        )
    return {
        "schema": "paper_i_executed_logical_scalar_estimator_work_v2",
        "contract": "required_executed_logical_scalar_estimator_invocations_v1",
        "scope": str(scope),
        "unit": "logical_scalar_estimator_invocation",
        "components": dict(components),
        **components,
        "S_alg": int(s_alg),
        "S_unique": int(s_unique),
        "identity_repeat_occurrence_count": int(s_alg - s_unique),
        "includes_rejected_evaluated_candidates": True,
        "persistent_or_prior_run_cache_reductions_allowed": False,
    }

EXACT_LABEL = "Exact_Hardcode"
