_ZERO_NOISE_ORACLE_INNER_EXACT_GUARD_REASON = "zero_noise_noisy_v1_exact_equivalent_guard_v1"
_ZERO_NOISE_ORACLE_GRADIENT_EXACT_GUARD_REASON = "zero_noise_oracle_gradient_exact_equivalent_guard_v1"
_SOURCE_LOCK_PREFERRED_SEQUENCE_REASON = "source_lock_preferred_sequence_v1"
_VALUE_NOISE_ORACLE_INNER_EXACT_STRUCTURE_REASON = "value_noise_noisy_v1_exact_structure_scalar_guard_v1"
_VALUE_NOISE_ORACLE_INNER_EXACT_STRUCTURE_MODE = "exact_structure_plus_value_noise_v1"


def _phase1_repeated_family_flat(
    *,
    history: list[dict[str, Any]],
    candidate_family: str,
    patience: int,
    weak_drop_threshold: float,
) -> bool:
    if str(candidate_family).strip() == "":
        return False
    tail = [row for row in history if isinstance(row, dict) and row.get("candidate_family") is not None]
    need = max(0, int(patience) - 1)
    if need <= 0:
        return False
    if len(tail) < need:
        return False
    recent = tail[-need:]
    for row in recent:
        if str(row.get("candidate_family")) != str(candidate_family):
            return False
        drop = float(row.get("delta_abs_drop_from_prev", float("inf")))
        if not math.isfinite(drop) or drop > float(weak_drop_threshold):
            return False
    return True


_VALID_INSERTION_MODES = frozenset(
    {
        "append_only",
        "append_commutation_reduced",
        "adaptive",
        "full_commutation_reduced",
        "insertion_commutation_plateau_v1",
        "insertion_commutation_plateau_v2",
    }
)
_VALID_BATCH_ORDER_SELECTION_MODES = frozenset({"finite_step_v1", "score_sorted"})


def _finite_float_or(value: Any, default: float) -> float:
    try:
        out = float(value)
    except (TypeError, ValueError):
        return float(default)
    return out if math.isfinite(out) else float(default)


def _insertion_commutation_plateau_round_policy(
    *,
    history: Sequence[Mapping[str, Any]],
    policy: str = "insertion_commutation_plateau_v2",
    controller_noise_energy_source: bool = False,
) -> dict[str, Any]:
    """Resolve insertion from marginal progress over prior mean progress."""

    policy_key = str(policy).strip().lower()
    if policy_key == "insertion_commutation_plateau_v1":
        threshold = float(
            INSERTION_COMMUTATION_PLATEAU_CUMULATIVE_DECREASE_RATIO_THRESHOLD
        )
    elif policy_key == "insertion_commutation_plateau_v2":
        threshold = float(
            INSERTION_COMMUTATION_PLATEAU_PRIOR_MEAN_DECREASE_RATIO_THRESHOLD
        )
    else:
        raise ValueError(f"Unsupported plateau insertion policy: {policy!r}")
    trigger_before: float | None = None
    trigger_after: float | None = None
    trigger_decrease: float | None = None
    cumulative_decrease_before: float | None = None
    prior_accepted_transition_count = 0
    prior_mean_decrease: float | None = None
    marginal_to_cumulative_ratio: float | None = None
    marginal_to_prior_mean_ratio: float | None = None
    trigger_source = "first_round_no_preceding_accepted_transition"

    def accepted_decrease(
        row: Mapping[str, Any],
    ) -> tuple[float | None, float | None, float | None, str]:
        if controller_noise_energy_source:
            controller_noise = row.get("controller_noise")
            if not isinstance(controller_noise, Mapping):
                return (
                    None,
                    None,
                    None,
                    "persisted_noisy_controller_energy_unavailable",
                )
            before = _finite_float_or(
                controller_noise.get("controller_energy_before"),
                float("nan"),
            )
            after = _finite_float_or(
                controller_noise.get("controller_energy_after"),
                float("nan"),
            )
            if math.isfinite(before) and math.isfinite(after):
                return (
                    float(before),
                    float(after),
                    float(before - after),
                    "persisted_noisy_controller_energy_before_after_v1",
                )
            return (
                None,
                None,
                None,
                "persisted_noisy_controller_energy_unavailable",
            )
        before = _finite_float_or(
            row.get("energy_before_opt"),
            float("nan"),
        )
        after = _finite_float_or(
            row.get("energy_after_opt"),
            float("nan"),
        )
        if math.isfinite(before) and math.isfinite(after):
            return (
                float(before),
                float(after),
                float(before - after),
                "accepted_refit_energy_before_after_v1",
            )
        delta_energy = _finite_float_or(
            row.get("delta_energy"),
            float("nan"),
        )
        if math.isfinite(delta_energy):
            return (
                None,
                None,
                float(-delta_energy),
                "accepted_refit_delta_energy_v1",
            )
        return (
            None,
            None,
            None,
            "accepted_transition_energy_unavailable",
        )

    last_row = history[-1] if history else None
    if isinstance(last_row, Mapping):
        (
            trigger_before,
            trigger_after,
            trigger_decrease,
            trigger_source,
        ) = accepted_decrease(last_row)

        prior_decreases: list[float] = []
        prior_history_complete = True
        for row in history[:-1]:
            if not isinstance(row, Mapping):
                prior_history_complete = False
                break
            _before, _after, decrease, _source = accepted_decrease(row)
            if decrease is None:
                prior_history_complete = False
                break
            prior_decreases.append(float(decrease))
        if prior_history_complete and prior_decreases:
            cumulative = float(sum(prior_decreases))
            if math.isfinite(cumulative) and cumulative > 0.0:
                cumulative_decrease_before = cumulative
                prior_accepted_transition_count = len(prior_decreases)
                mean_decrease = cumulative / float(
                    prior_accepted_transition_count
                )
                if math.isfinite(mean_decrease) and mean_decrease > 0.0:
                    prior_mean_decrease = mean_decrease
        if (
            trigger_decrease is not None
            and cumulative_decrease_before is not None
        ):
            cumulative_ratio = float(trigger_decrease) / float(
                cumulative_decrease_before
            )
            if math.isfinite(cumulative_ratio):
                marginal_to_cumulative_ratio = cumulative_ratio
        if trigger_decrease is not None and prior_mean_decrease is not None:
            mean_ratio = float(trigger_decrease) / float(prior_mean_decrease)
            if math.isfinite(mean_ratio):
                marginal_to_prior_mean_ratio = mean_ratio
    decision_ratio = (
        marginal_to_cumulative_ratio
        if policy_key == "insertion_commutation_plateau_v1"
        else marginal_to_prior_mean_ratio
    )
    domain_open = bool(
        decision_ratio is not None
        and float(decision_ratio) < float(threshold)
    )
    receipt = {
        "schema": (
            "insertion_commutation_plateau_round_policy_v1"
            if policy_key == "insertion_commutation_plateau_v1"
            else "insertion_commutation_plateau_round_policy_v2"
        ),
        "policy": policy_key,
        "domain_state": "open" if domain_open else "closed",
        "domain_open": bool(domain_open),
        "effective_insertion_mode": (
            "full_commutation_reduced" if domain_open else "append_only"
        ),
        "trigger_energy_before": trigger_before,
        "trigger_energy_after": trigger_after,
        "trigger_energy_decrease": trigger_decrease,
        "prior_cumulative_energy_decrease": cumulative_decrease_before,
        "trigger_source": str(trigger_source),
        "patience": 1,
        "hysteresis_active": False,
        "exact_reference_used": False,
        "energy_track": (
            "noisy_controller"
            if controller_noise_energy_source
            else "exact_accepted_diagnostic"
        ),
    }
    if policy_key == "insertion_commutation_plateau_v1":
        receipt.update(
            {
                "marginal_to_prior_cumulative_decrease_ratio": (
                    marginal_to_cumulative_ratio
                ),
                "cumulative_decrease_ratio_threshold": float(threshold),
                "threshold_comparison": (
                    "marginal_to_prior_cumulative_strictly_below"
                ),
                "calibration_status": str(
                    INSERTION_COMMUTATION_PLATEAU_CALIBRATION_STATUS
                ),
            }
        )
    else:
        receipt.update(
            {
                "prior_accepted_transition_count": int(
                    prior_accepted_transition_count
                ),
                "prior_mean_energy_decrease": prior_mean_decrease,
                "marginal_to_prior_mean_decrease_ratio": (
                    marginal_to_prior_mean_ratio
                ),
                "prior_mean_decrease_ratio_threshold": float(threshold),
                "threshold_comparison": (
                    "marginal_to_prior_mean_strictly_below_v2"
                ),
                "calibration_status": str(
                    INSERTION_COMMUTATION_PLATEAU_PRIOR_MEAN_CALIBRATION_STATUS
                ),
            }
        )
    return receipt


def _ra_latched_phase3_history_state(
    history: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Reconstruct the monotone Phase-III latch from accepted receipts."""

    from pipelines.static_adapt.ra_adapt.contracts import (
        RA_ADAPT_PHASE3_POPULATION_LATCHED_ON_PROGRESS_PLATEAU,
    )

    latched = False
    first_open_round: int | None = None
    last_round_live = False
    for ordinal, row in enumerate(history, start=1):
        activation = row.get("phase3_population_activation")
        if (
            not isinstance(activation, Mapping)
            or activation.get("schema")
            != "ra_phase3_population_activation_receipt_v2"
            or activation.get("policy")
            != RA_ADAPT_PHASE3_POPULATION_LATCHED_ON_PROGRESS_PLATEAU
        ):
            raise RuntimeError(
                "Latched Phase-III history lost its activation receipt."
            )
        entry_open = activation.get("entry_plateau_domain_open")
        before = activation.get("phase3_latched_before_round")
        after = activation.get("phase3_latched_after_round")
        opened = activation.get("phase3_latch_opened_this_round")
        competitive_live = activation.get("competitive_population_live")
        if not all(
            isinstance(value, bool)
            for value in (
                entry_open,
                before,
                after,
                opened,
                competitive_live,
            )
        ):
            raise RuntimeError(
                "Latched Phase-III history carries a non-Boolean state."
            )
        expected_after = bool(latched or entry_open)
        expected_opened = bool(not latched and entry_open)
        if (
            before is not latched
            or after is not expected_after
            or opened is not expected_opened
            or competitive_live is not expected_after
            or activation.get("independent_latch_active") is not True
            or activation.get("deactivation_allowed") is not False
            or activation.get("hysteresis_active") is not False
        ):
            raise RuntimeError(
                "Latched Phase-III history is not a monotone first-open latch."
            )
        if expected_opened:
            if first_open_round is not None:
                raise RuntimeError("Phase III latched open more than once.")
            first_open_round = ordinal
        if activation.get("first_latch_accepted_round") != first_open_round:
            raise RuntimeError(
                "Latched Phase-III history changed its first-open round."
            )
        latched = expected_after
        last_round_live = bool(competitive_live)
    return {
        "latched": bool(latched),
        "first_open_round": first_open_round,
        "last_round_live": bool(last_round_live),
    }


def _ra_post_latch_insertion_round_policy(
    *,
    history: Sequence[Mapping[str, Any]],
    raw_round_policy: Mapping[str, Any],
) -> dict[str, Any]:
    """Gate the unchanged plateau statistic behind a prior full Phase III."""

    from pipelines.static_adapt.ra_adapt.contracts import (
        RA_ADAPT_POST_LATCH_INSERTION_TRIGGER_SCOPE,
    )

    state = _ra_latched_phase3_history_state(history)
    raw_open = bool(raw_round_policy.get("domain_open", False))
    trigger_eligible = bool(
        state["latched"] and state["last_round_live"] and history
    )
    domain_open = bool(trigger_eligible and raw_open)
    receipt = copy.deepcopy(dict(raw_round_policy))
    receipt.update(
        {
            "domain_state": "open" if domain_open else "closed",
            "domain_open": domain_open,
            "effective_insertion_mode": (
                "full_commutation_reduced" if domain_open else "append_only"
            ),
            "raw_progress_plateau_domain_open": raw_open,
            "insertion_trigger_scope": (
                RA_ADAPT_POST_LATCH_INSERTION_TRIGGER_SCOPE
            ),
            "phase3_latched_before_round": bool(state["latched"]),
            "preceding_full_phase3_transition_eligible": trigger_eligible,
            "preceding_accepted_round": (
                len(history) if trigger_eligible else None
            ),
            "insertion_latch_active": False,
        }
    )
    return receipt


def _ra_phase3_population_activation_receipt(
    *,
    route_contract: Mapping[str, Any],
    history: Sequence[Mapping[str, Any]] = (),
    entry_round_policy: Mapping[str, Any] | None = None,
    insertion_round_policy: Mapping[str, Any] | None,
    candidate_adapter: Any | None,
    admission_policy: Any,
) -> dict[str, Any]:
    """Resolve singleton Phase-III activation from authenticated receipts.

    The historical same-round route remains a pure projection of the current
    insertion receipt.  The latched route instead reconstructs its monotone
    first-open state from accepted history, without introducing mutable latch
    state into the controller cursor.
    """

    from pipelines.static_adapt.ra_adapt.adapters import (
        SINGLE_PAULI_ADAPTER_ID,
    )
    from pipelines.static_adapt.ra_adapt.contracts import (
        CANDIDATE_REPRESENTATION_SINGLE_PAULI,
        RA_ADAPT_POST_LATCH_INSERTION_TRIGGER_SCOPE,
        RA_ADAPT_PHASE3_POPULATION_ALL_ROUNDS,
        RA_ADAPT_PHASE3_POPULATION_LATCHED_ON_PROGRESS_PLATEAU,
        RA_ADAPT_PHASE3_POPULATION_ON_INSERTION_PLATEAU,
        RA_ADAPT_PHASE3_PREPLATEAU_WINNER_MATERIALIZATION,
    )

    execution = route_contract.get("execution_settings")
    invariants = route_contract.get("semantic_invariants")
    if not isinstance(execution, Mapping) or not isinstance(
        invariants, Mapping
    ):
        raise RuntimeError(
            "RA Phase-III activation requires a complete route contract."
        )
    activation_policy = str(
        execution.get(
            "ra_phase3_population_activation_policy",
            RA_ADAPT_PHASE3_POPULATION_ALL_ROUNDS,
        )
    )
    if activation_policy == RA_ADAPT_PHASE3_POPULATION_ALL_ROUNDS:
        return {
            "schema": "ra_phase3_population_activation_receipt_v1",
            "policy": RA_ADAPT_PHASE3_POPULATION_ALL_ROUNDS,
            "competitive_population_live": True,
            "activation_source": "route_default_all_rounds_v1",
            "preplateau_admission_authority": None,
            "winner_materialization_policy": None,
            "insertion_plateau_domain_open": None,
            "independent_latch_active": False,
            "hysteresis_active": False,
        }
    if activation_policy not in {
        RA_ADAPT_PHASE3_POPULATION_ON_INSERTION_PLATEAU,
        RA_ADAPT_PHASE3_POPULATION_LATCHED_ON_PROGRESS_PLATEAU,
    }:
        raise RuntimeError(
            "RA route declared an unknown Phase-III population activation "
            f"policy: {activation_policy!r}."
        )
    expected_materialization = (
        RA_ADAPT_PHASE3_PREPLATEAU_WINNER_MATERIALIZATION
    )
    common_contract_drift = bool(
        not isinstance(admission_policy, SingletonAdmission)
        or str(getattr(candidate_adapter, "adapter_id", ""))
        != SINGLE_PAULI_ADAPTER_ID
        or invariants.get("candidate_representation")
        != CANDIDATE_REPRESENTATION_SINGLE_PAULI
        or execution.get("adapt_insertion_mode")
        != "insertion_commutation_plateau_v2"
        or execution.get("ra_phase3_preplateau_materialization_policy")
        != expected_materialization
        or invariants.get("phase3_activation_hysteresis_active") is not False
    )
    if common_contract_drift:
        raise RuntimeError(
            "The singleton Phase-III-on-plateau activation contract drifted."
        )
    if activation_policy == (
        RA_ADAPT_PHASE3_POPULATION_LATCHED_ON_PROGRESS_PLATEAU
    ):
        if (
            invariants.get("phase3_activation_source")
            != "first_authenticated_progress_plateau_domain_open_latched_v1"
            or invariants.get("phase3_activation_independent_latch") is not True
            or invariants.get("phase3_latch_retirement_policy")
            != "never_close_v1"
            or invariants.get("insertion_plateau_history_scope")
            != RA_ADAPT_POST_LATCH_INSERTION_TRIGGER_SCOPE
            or invariants.get("insertion_activation_requires_prior_phase3_latch")
            is not True
            or invariants.get("insertion_activation_changes_phase3_latch")
            is not False
            or execution.get("ra_insertion_plateau_history_scope")
            != RA_ADAPT_POST_LATCH_INSERTION_TRIGGER_SCOPE
            or not isinstance(entry_round_policy, Mapping)
            or entry_round_policy.get("policy")
            != "insertion_commutation_plateau_v2"
            or not isinstance(insertion_round_policy, Mapping)
            or insertion_round_policy.get("policy")
            != "insertion_commutation_plateau_v2"
            or insertion_round_policy.get("insertion_trigger_scope")
            != RA_ADAPT_POST_LATCH_INSERTION_TRIGGER_SCOPE
        ):
            raise RuntimeError(
                "The latched Phase-III/separate-insertion contract drifted."
            )
        state = _ra_latched_phase3_history_state(history)
        entry_open = bool(entry_round_policy.get("domain_open", False))
        live = bool(state["latched"] or entry_open)
        opened = bool(not state["latched"] and entry_open)
        first_open_round = state["first_open_round"]
        if opened:
            first_open_round = len(history) + 1
        return {
            "schema": "ra_phase3_population_activation_receipt_v2",
            "policy": RA_ADAPT_PHASE3_POPULATION_LATCHED_ON_PROGRESS_PLATEAU,
            "competitive_population_live": live,
            "activation_source": (
                "first_authenticated_progress_plateau_domain_open_latched_v1"
            ),
            "preplateau_admission_authority": (
                None if live else "phase2_raw_score_top_rank_v1"
            ),
            "winner_materialization_policy": (
                None if live else expected_materialization
            ),
            "entry_plateau_domain_open": entry_open,
            "entry_plateau_receipt": copy.deepcopy(dict(entry_round_policy)),
            "phase3_latched_before_round": bool(state["latched"]),
            "phase3_latched_after_round": live,
            "phase3_latch_opened_this_round": opened,
            "first_latch_accepted_round": first_open_round,
            "independent_latch_active": True,
            "deactivation_allowed": False,
            "hysteresis_active": False,
            "insertion_plateau_domain_open": bool(
                insertion_round_policy.get("domain_open", False)
            ),
            "insertion_trigger_eligible": bool(
                insertion_round_policy.get(
                    "preceding_full_phase3_transition_eligible", False
                )
            ),
        }
    if (
        invariants.get("phase3_activation_source")
        != "same_round_authenticated_insertion_plateau_domain_open_v1"
        or invariants.get("phase3_activation_independent_latch") is not False
        or not isinstance(insertion_round_policy, Mapping)
        or insertion_round_policy.get("policy")
        != "insertion_commutation_plateau_v2"
        or insertion_round_policy.get("patience") != 1
        or insertion_round_policy.get("hysteresis_active") is not False
    ):
        raise RuntimeError(
            "The singleton Phase-III-on-plateau activation contract drifted."
        )
    domain_open = bool(insertion_round_policy.get("domain_open", False))
    return {
        "schema": "ra_phase3_population_activation_receipt_v1",
        "policy": RA_ADAPT_PHASE3_POPULATION_ON_INSERTION_PLATEAU,
        "competitive_population_live": domain_open,
        "activation_source": (
            "same_round_authenticated_insertion_plateau_domain_open_v1"
        ),
        "preplateau_admission_authority": (
            None if domain_open else "phase2_raw_score_top_rank_v1"
        ),
        "winner_materialization_policy": (
            None if domain_open else expected_materialization
        ),
        "insertion_plateau_domain_open": domain_open,
        "independent_latch_active": False,
        "hysteresis_active": False,
    }


def _phase1_position_probe_plan(
    *,
    insertion_mode: str,
    append_eval: Mapping[str, Any],
    append_position: int,
    n_params: int,
    active_window_indices: Sequence[int],
    stage_name: str,
    drop_plateau_hits: int,
    max_grad: float,
    eps_grad: float,
    finite_angle_fallback: bool,
    repeated_family_flat: bool,
    cfg: StageControllerConfig,
) -> tuple[list[int], bool, str]:
    """Resolve which logical insertion positions Phase-1 should score."""

    mode = str(insertion_mode).strip().lower()
    if mode == "full":
        raise ValueError(
            "The raw full insertion mode is retired; use "
            "'full_commutation_reduced'."
        )
    if mode == "always":
        raise ValueError(
            "The ambiguous capped-domain 'always' insertion mode is retired; "
            "use 'full_commutation_reduced' for always-open insertion."
        )
    append_pos = int(append_position)
    if mode in {
        "append_only",
        "insertion_commutation_plateau_v1",
        "insertion_commutation_plateau_v2",
    }:
        reason = (
            "append_only"
            if mode == "append_only"
            else "plateau_profile_state_unavailable_append_only"
        )
        return [append_pos], False, reason
    if mode == "full_commutation_reduced":
        return list(range(append_pos + 1)), append_pos > 0, str(mode)

    positions = allowed_positions(
        n_params=int(n_params),
        append_position=append_pos,
        active_window_indices=[int(i) for i in active_window_indices],
        max_positions=int(max(1, cfg.max_probe_positions)),
    )
    if len(positions) <= 1:
        return [append_pos], False, "append_only_no_extra_positions"

    should_probe, reason = should_probe_positions(
        stage_name=str(stage_name),
        drop_plateau_hits=int(drop_plateau_hits),
        max_grad=float(max_grad),
        eps_grad=float(eps_grad),
        append_score=_finite_float_or(append_eval.get("append_best_score"), float("-inf")),
        finite_angle_flat=bool(finite_angle_fallback) and float(max_grad) < float(eps_grad),
        repeated_family_flat=bool(repeated_family_flat),
        cfg=cfg,
    )
    if bool(should_probe):
        return positions, True, str(reason)
    return [append_pos], False, str(reason)


def _termwise_generators_commute_for_insertion(
    candidate_term: AnsatzTerm,
    ansatz_term: AnsatzTerm,
    *,
    coefficient_tolerance: float = 1.0e-12,
) -> bool:
    """Certify that two implemented generator blocks can be interchanged.

    Static ADAPT executes macro generators as ordered products of Pauli
    rotations.  Commutation of every nonzero Pauli component across the two
    blocks is therefore a sufficient exact certificate that swapping the
    blocks leaves the implemented unitary unchanged.
    """

    try:
        candidate = expansion_from_ansatz_term(candidate_term, key="candidate")
        existing = expansion_from_ansatz_term(ansatz_term, key="ansatz")
    except AlgebraicMetadataError:
        return False
    candidate_terms = [
        term
        for term in candidate.terms
        if abs(complex(term.coeff)) > float(coefficient_tolerance)
    ]
    existing_terms = [
        term
        for term in existing.terms
        if abs(complex(term.coeff)) > float(coefficient_tolerance)
    ]
    if not candidate_terms or not existing_terms:
        return False
    try:
        return all(
            pauli_words_commute(lhs.pauli_exyz, rhs.pauli_exyz)
            for lhs in candidate_terms
            for rhs in existing_terms
        )
    except AlgebraicMetadataError:
        return False


def _commutation_reduced_insertion_position_plan(
    *,
    candidate_term: AnsatzTerm,
    selected_ops: Sequence[AnsatzTerm],
    positions: Sequence[int],
) -> dict[str, Any]:
    """Collapse insertion positions connected by certified commuting swaps."""

    n_ops = int(len(selected_ops))
    requested = sorted({int(position) for position in positions})
    invalid = [position for position in requested if position < 0 or position > n_ops]
    if invalid:
        raise ValueError(
            f"Insertion positions must lie in [0, {n_ops}], got {invalid}."
        )

    class_start_by_position: dict[int, int] = {0: 0}
    class_start = 0
    commuting_crossings: list[bool] = []
    for index, existing_term in enumerate(selected_ops):
        commutes = _termwise_generators_commute_for_insertion(
            candidate_term,
            existing_term,
        )
        commuting_crossings.append(bool(commutes))
        if not bool(commutes):
            class_start = int(index + 1)
        class_start_by_position[int(index + 1)] = int(class_start)

    requested_by_class: dict[int, list[int]] = {}
    for position in requested:
        requested_by_class.setdefault(
            int(class_start_by_position[int(position)]),
            [],
        ).append(int(position))
    members_by_representative: dict[int, list[int]] = {}
    representative_by_position: dict[int, int] = {}
    for members in requested_by_class.values():
        representative = int(min(members))
        members_by_representative[representative] = [int(x) for x in members]
        for position in members:
            representative_by_position[int(position)] = int(representative)
    representatives = sorted(int(x) for x in members_by_representative)
    return {
        "schema": "commutation_reduced_insertion_positions_v1",
        "requested_positions": [int(x) for x in requested],
        "representative_positions": [int(x) for x in representatives],
        "representative_by_position": {
            int(key): int(value)
            for key, value in representative_by_position.items()
        },
        "members_by_representative": {
            int(key): [int(x) for x in value]
            for key, value in members_by_representative.items()
        },
        "commuting_crossings": [bool(x) for x in commuting_crossings],
        "collapsed_position_count": int(len(requested) - len(representatives)),
    }


def _candidate_insertion_position_plans(
    *,
    pool: Sequence[AnsatzTerm],
    candidate_indices: Sequence[int],
    selected_ops: Sequence[AnsatzTerm],
    positions: Sequence[int],
) -> dict[int, dict[str, Any]]:
    """Return candidate-specific insertion representatives and class members."""

    requested = sorted({int(position) for position in positions})
    plans: dict[int, dict[str, Any]] = {}
    for idx_raw in candidate_indices:
        idx = int(idx_raw)
        plans[idx] = _commutation_reduced_insertion_position_plan(
            candidate_term=pool[idx],
            selected_ops=selected_ops,
            positions=requested,
        )
    return plans


def _commutation_reduced_insertion_domain_receipt(
    *,
    round_policy: Mapping[str, Any],
    candidate_position_plans: Mapping[int, Mapping[str, Any]],
    pool: Sequence[AnsatzTerm],
) -> dict[str, Any]:
    """Serialize the requested domain and retained representatives."""

    plan_rows: list[dict[str, Any]] = []
    requested_positions: set[int] = set()
    retained_representatives: list[dict[str, Any]] = []
    for candidate_pool_index in sorted(
        int(index) for index in candidate_position_plans
    ):
        plan = dict(candidate_position_plans[int(candidate_pool_index)])
        requested = [
            int(position)
            for position in plan.get("requested_positions", [])
        ]
        representatives = [
            int(position)
            for position in plan.get("representative_positions", [])
        ]
        requested_positions.update(requested)
        candidate_label = (
            str(pool[int(candidate_pool_index)].label)
            if 0 <= int(candidate_pool_index) < len(pool)
            else ""
        )
        plan_rows.append(
            {
                "candidate_pool_index": int(candidate_pool_index),
                "candidate_label": str(candidate_label),
                **copy.deepcopy(plan),
            }
        )
        retained_representatives.append(
            {
                "candidate_pool_index": int(candidate_pool_index),
                "candidate_label": str(candidate_label),
                "positions": representatives,
            }
        )
    return {
        **dict(round_policy),
        "requested_positions": sorted(int(x) for x in requested_positions),
        "retained_representatives": retained_representatives,
        "candidate_position_plans": plan_rows,
        "candidate_count": int(len(plan_rows)),
        "requested_position_count": int(len(requested_positions)),
        "retained_representative_count": int(
            sum(
                len(row["positions"])
                for row in retained_representatives
            )
        ),
        "collapsed_position_count": int(
            sum(
                int(row.get("collapsed_position_count", 0))
                for row in plan_rows
            )
        ),
    }


def _insertion_commutation_plateau_domain_receipt(
    *,
    round_policy: Mapping[str, Any],
    candidate_position_plans: Mapping[int, Mapping[str, Any]],
    pool: Sequence[AnsatzTerm],
) -> dict[str, Any]:
    """Project an opened or closed plateau round through the shared reducer."""

    return _commutation_reduced_insertion_domain_receipt(
        round_policy=round_policy,
        candidate_position_plans=candidate_position_plans,
        pool=pool,
    )


def _always_commutation_reduced_domain_receipt(
    *,
    candidate_position_plans: Mapping[int, Mapping[str, Any]],
    pool: Sequence[AnsatzTerm],
) -> dict[str, Any]:
    """Project the always-open full requested domain and its class members."""

    return _commutation_reduced_insertion_domain_receipt(
        round_policy={
            "schema": "commutation_reduced_insertion_domain_receipt_v1",
            "policy": "always_commutation_reduced",
            "domain_state": "open",
            "domain_open": True,
            "effective_insertion_mode": "full_commutation_reduced",
        },
        candidate_position_plans=candidate_position_plans,
        pool=pool,
    )


def _append_commutation_reduced_domain_receipt(
    *,
    append_position: int,
    candidate_position_plans: Mapping[int, Mapping[str, Any]],
    pool: Sequence[AnsatzTerm],
) -> dict[str, Any]:
    """Project the endpoint through the same exact commutation reducer."""

    from pipelines.static_adapt.ra_adapt.insertion_geometry import (
        append_commutation_reduced_receipt_header,
    )

    return _commutation_reduced_insertion_domain_receipt(
        round_policy=append_commutation_reduced_receipt_header(
            append_position=int(append_position)
        ),
        candidate_position_plans=candidate_position_plans,
        pool=pool,
    )


def _phase1_detect_position_trough(
    *,
    append_eval: Mapping[str, Any],
    scored_eval: Mapping[str, Any],
    cfg: StageControllerConfig,
) -> bool:
    return bool(
        detect_trough(
            append_score=_finite_float_or(append_eval.get("append_best_score"), float("-inf")),
            best_non_append_score=_finite_float_or(scored_eval.get("best_non_append_score"), float("-inf")),
            best_non_append_g_lcb=_finite_float_or(scored_eval.get("best_non_append_g_lcb"), 0.0),
            margin_ratio=float(cfg.probe_margin_ratio),
            append_admit_threshold=float(cfg.append_admit_threshold),
        )
    )


def _splice_candidate_at_position(
    *,
    ops: list[AnsatzTerm],
    theta: np.ndarray,
    op: AnsatzTerm,
    position_id: int,
    init_theta: float = 0.0,
) -> tuple[list[AnsatzTerm], np.ndarray]:
    current_layout = build_parameter_layout(
        ops,
        ignore_identity=True,
        coefficient_tolerance=1e-12,
        sort_terms=True,
    )
    op_layout = build_parameter_layout(
        [op],
        ignore_identity=True,
        coefficient_tolerance=1e-12,
        sort_terms=True,
    )
    pos_logical = max(0, min(int(current_layout.logical_parameter_count), int(position_id)))
    pos_runtime = int(runtime_insert_position(current_layout, pos_logical))
    new_ops = list(ops)
    new_ops.insert(pos_logical, op)
    theta_arr = np.asarray(theta, dtype=float).reshape(-1)
    insert_block = np.full(int(op_layout.runtime_parameter_count), float(init_theta), dtype=float)
    new_theta = np.insert(theta_arr, pos_runtime, insert_block)
    return new_ops, np.asarray(new_theta, dtype=float)


def _resolve_admitted_growth_init_theta(
    proposed_init_theta: float,
    *,
    exact_zero_growth_required: bool,
) -> float:
    """Return the coordinate actually inserted at an accepted growth event.

    Response selectors may expose a finite-angle proposal as selection
    telemetry.  Accepted growth is instead an exact embedding of the
    accepted ansatz and therefore must insert every newly admitted coordinate
    at zero.  Keeping this resolution at the materialization boundary prevents
    a selector proposal from changing the state before the transactional
    manifold reoptimization begins.
    """

    proposed = float(proposed_init_theta)
    return 0.0 if bool(exact_zero_growth_required) else proposed


def _assert_ansatz_term_sector_safe(
    candidate_term: AnsatzTerm,
    *,
    resolved_problem: Any,
    source: str,
) -> dict[str, Any]:
    """Fail closed when a candidate's algebra or execution can leave its sector.

    Dynamic children are created after the initial pool preflight, so their
    grouped generator and their declared runtime execution must both be
    checked before either scoring or admission.
    """

    if not isinstance(candidate_term, AnsatzTerm):
        raise TypeError(
            "Dynamic candidate sector validation requires an AnsatzTerm at "
            f"{source}; received {type(candidate_term).__name__}."
        )
    audit = audit_candidate_pool_sector_contract(
        [candidate_term],
        resolved_problem=resolved_problem,
    )
    grouped_passed = bool(audit.get("passed", False))
    execution_passed = bool(audit.get("execution_passed", False))
    if not grouped_passed or not execution_passed:
        raise RuntimeError(
            "ADAPT candidate violated the declared fixed-count sector contract "
            f"at {source}: label={candidate_term.label!r}, "
            f"grouped_passed={grouped_passed}, "
            f"execution_passed={execution_passed}, audit={audit!r}"
        )
    return audit


def _splice_logical_candidate_at_position(
    *,
    ops: list[AnsatzTerm],
    theta: np.ndarray,
    candidate: _ADAPTLogicalCandidate,
    pool: Sequence[AnsatzTerm],
    position_id: int,
    init_theta_values: Sequence[float] | None = None,
) -> tuple[list[AnsatzTerm], np.ndarray]:
    theta_arr = np.asarray(theta, dtype=float).reshape(-1)
    append_position = int(theta_arr.size)
    pos = max(0, min(int(append_position), int(position_id)))
    theta_values = (
        [0.0] * int(len(candidate.pool_indices))
        if init_theta_values is None
        else [float(x) for x in init_theta_values]
    )
    if len(theta_values) != int(len(candidate.pool_indices)):
        raise ValueError("Logical candidate insertion requires one init theta per emitted term.")

    new_ops = list(ops)
    new_theta = np.asarray(theta_arr, dtype=float)
    for offset, (pool_idx, theta_val) in enumerate(zip(candidate.pool_indices, theta_values)):
        insert_at = int(pos + offset)
        new_ops.insert(insert_at, pool[int(pool_idx)])
        new_theta = np.insert(new_theta, insert_at, float(theta_val))
    return new_ops, np.asarray(new_theta, dtype=float)


def _predict_nested_refit_window_for_position(
    *,
    theta: np.ndarray,
    position_id: int,
    policy: str,
    window_size: int,
    window_topk: int,
    periodic_full_refit_triggered: bool,
) -> NestedRefitWindow:
    theta_arr = np.asarray(theta, dtype=float).reshape(-1)
    pre_n = int(theta_arr.size)
    pos = max(0, min(pre_n, int(position_id)))
    policy_key = str(policy).strip().lower()
    window_new_pre_indices: list[int] = []
    window_age_pre_indices: list[int] = []
    if policy_key == "windowed" and not bool(periodic_full_refit_triggered):
        old_budget = max(0, int(window_size) - 1)
        age_budget = min(max(0, int(window_topk)), int(old_budget))
        new_budget = max(0, int(old_budget) - int(age_budget))
        if new_budget > 0:
            start_new = max(0, pre_n - int(new_budget))
            window_new_pre_indices = list(range(start_new, pre_n))
            window_age_pre_indices = list(range(0, start_new))
        elif age_budget > 0:
            window_age_pre_indices = list(range(0, pre_n))
    return predict_nested_refit_window(
        pre_parameter_count=pre_n,
        theta_pre=np.asarray(theta_arr, dtype=float),
        position_id=int(pos),
        policy=str(policy_key),
        window_size=int(window_size),
        window_topk=int(window_topk),
        window_new_pre_indices=window_new_pre_indices,
        window_age_pre_indices=window_age_pre_indices,
        periodic_full_refit_triggered=bool(periodic_full_refit_triggered),
        allowed_old_pre_indices=list(range(pre_n)),
    )


def _predict_phase3_geometry_window_for_position(
    *,
    theta: np.ndarray,
    position_id: int,
    geometry_window_size: int,
) -> NestedRefitWindow:
    """Predict the old-pre geometry window for Phase-II/Phase-III scoring.

    ``geometry_window_size`` counts the inserted candidate in post-coordinate
    space.  A size of one therefore means candidate-only geometry, i.e. an empty
    old-pre Schur/novelty window.
    """

    theta_arr = np.asarray(theta, dtype=float).reshape(-1)
    pre_n = int(theta_arr.size)
    pos = max(0, min(pre_n, int(position_id)))
    size = int(max(1, geometry_window_size))
    old_budget = max(0, int(size) - 1)
    nearest_old_pre = sorted(
        range(pre_n),
        key=lambda idx: (
            abs(int(map_pre_to_post_index(int(idx), int(pos))) - int(pos)),
            int(map_pre_to_post_index(int(idx), int(pos))),
            int(idx),
        ),
    )[:old_budget]
    return predict_nested_refit_window(
        pre_parameter_count=int(pre_n),
        theta_pre=np.asarray(theta_arr, dtype=float),
        position_id=int(pos),
        policy="windowed",
        window_size=int(size),
        window_topk=0,
        window_new_pre_indices=[int(i) for i in nearest_old_pre],
        window_age_pre_indices=[],
        periodic_full_refit_triggered=False,
        allowed_old_pre_indices=list(range(pre_n)),
    )


def _resolve_phase3_response_window_for_position(
    *,
    theta: np.ndarray,
    position_id: int,
    scope: str,
    geometry_window_size: int,
    nested_window: NestedRefitWindow,
) -> NestedRefitWindow:
    """Resolve Phase-III response coordinates independently of Powell refits."""

    scope_key = str(scope).strip().lower()
    if scope_key == PHASE3_RESPONSE_COORDINATE_SCOPE_FULL_ACTIVE_PLUS_SINGLETON_V1:
        response_window = _predict_nested_refit_window_for_position(
            theta=np.asarray(theta, dtype=float),
            position_id=int(position_id),
            policy="full",
            window_size=max(1, int(np.asarray(theta).size) + 1),
            window_topk=0,
            periodic_full_refit_triggered=False,
        )
    elif scope_key == PHASE3_RESPONSE_COORDINATE_SCOPE_FIXED_LOCAL_WINDOW_V1:
        if int(geometry_window_size) < 1:
            raise ValueError(
                "fixed_local_window_v1 requires phase3_geometry_window_size >= 1."
            )
        response_window = _predict_phase3_geometry_window_for_position(
            theta=np.asarray(theta, dtype=float),
            position_id=int(position_id),
            geometry_window_size=int(geometry_window_size),
        )
    elif scope_key == (
        PHASE3_RESPONSE_COORDINATE_SCOPE_CANDIDATE_MATERIAL_COUPLING_WINDOW_V1
    ):
        # Phase-II acquires only the candidate screen.  The independent
        # material H/G window is selected later from the full authoritative
        # candidate population and must never inherit the Powell refit window.
        response_window = _predict_phase3_geometry_window_for_position(
            theta=np.asarray(theta, dtype=float),
            position_id=int(position_id),
            geometry_window_size=1,
        )
    elif scope_key == PHASE3_RESPONSE_COORDINATE_SCOPE_LEGACY_REOPT_COUPLED_V1:
        response_window = nested_window
    else:
        raise ValueError(
            "Unknown phase3_response_coordinate_scope: " f"{scope!r}."
        )

    if scope_key == PHASE3_RESPONSE_COORDINATE_SCOPE_FULL_ACTIVE_PLUS_SINGLETON_V1:
        active_count = int(response_window.pre_parameter_count)
        response_indices = tuple(int(i) for i in response_window.active_post_indices)
        expected_indices = tuple(range(active_count + 1))
        if (
            int(len(response_indices)) != int(active_count + 1)
            or response_indices != expected_indices
        ):
            raise RuntimeError(
                "Canonical SR-SNAKE Phase-III response-scope invariant failed "
                "before Gram support reduction: "
                "phase3_response_coordinate_count must equal "
                "active_logical_coordinate_count + 1 and contain every post-"
                "insertion logical coordinate."
            )
    elif scope_key == (
        PHASE3_RESPONSE_COORDINATE_SCOPE_CANDIDATE_MATERIAL_COUPLING_WINDOW_V1
    ):
        response_indices = tuple(
            int(i) for i in response_window.active_post_indices
        )
        expected_candidate_index = int(
            max(
                0,
                min(
                    int(response_window.pre_parameter_count),
                    int(position_id),
                ),
            )
        )
        if response_indices != (expected_candidate_index,):
            raise RuntimeError(
                "Material-window Phase-III screen must contain exactly the "
                "inserted candidate before the independent coupling window "
                "is selected."
            )
    return response_window


def _assert_full_phase3_response_records(
    records: Sequence[Mapping[str, Any]],
    *,
    active_logical_coordinate_count: int,
) -> None:
    """Fail closed before any canonical v3 Gram support reduction."""

    expected_count = int(active_logical_coordinate_count) + 1
    expected_indices = list(range(expected_count))
    for record in records:
        feature = record.get("feature")
        if not isinstance(feature, CandidateFeatures):
            raise RuntimeError(
                "Canonical SR-SNAKE Phase-III response record is missing "
                "CandidateFeatures before Gram support reduction."
            )
        if str(feature.phase3_response_coordinate_scope) != (
            PHASE3_RESPONSE_COORDINATE_SCOPE_FULL_ACTIVE_PLUS_SINGLETON_V1
        ):
            raise RuntimeError(
                "Canonical SR-SNAKE Phase-III response record carries a "
                "contradictory coordinate-scope policy."
            )
        response_indices = [
            int(i) for i in feature.phase3_response_coordinate_indices
        ]
        if (
            int(feature.phase3_active_logical_coordinate_count)
            != int(active_logical_coordinate_count)
            or int(feature.phase3_response_pre_support_count) != expected_count
            or response_indices != expected_indices
        ):
            raise RuntimeError(
                "Canonical SR-SNAKE Phase-III response-scope invariant failed "
                "before Gram support reduction: "
                "phase3_response_coordinate_count = "
                "active_logical_coordinate_count + 1."
            )



def _predict_reopt_window_for_position(
    *,
    theta: np.ndarray,
    position_id: int,
    policy: str,
    window_size: int,
    window_topk: int,
    periodic_full_refit_triggered: bool,
) -> list[int]:
    window = _predict_nested_refit_window_for_position(
        theta=np.asarray(theta, dtype=float),
        position_id=int(position_id),
        policy=str(policy),
        window_size=int(window_size),
        window_topk=int(window_topk),
        periodic_full_refit_triggered=bool(periodic_full_refit_triggered),
    )
    return [int(i) for i in window.active_post_indices]


def _window_terms_for_position(
    *,
    selected_ops: list[AnsatzTerm],
    refit_window_indices: list[int],
    position_id: int,
) -> tuple[list[AnsatzTerm], list[str]]:
    window_terms: list[AnsatzTerm] = []
    window_labels: list[str] = []
    pos = int(position_id)
    for idx in refit_window_indices:
        j = int(idx)
        if j == pos:
            continue
        mapped = j if j < pos else j - 1
        if 0 <= int(mapped) < len(selected_ops):
            term = selected_ops[int(mapped)]
            window_terms.append(term)
            window_labels.append(str(term.label))
    return window_terms, window_labels


def _window_terms_for_pre_indices(
    *,
    selected_ops: list[AnsatzTerm],
    old_pre_indices: Sequence[int],
) -> tuple[list[AnsatzTerm], list[str]]:
    window_terms: list[AnsatzTerm] = []
    window_labels: list[str] = []
    seen: set[int] = set()
    for idx in old_pre_indices:
        j = int(idx)
        if j in seen:
            continue
        seen.add(j)
        if 0 <= j < len(selected_ops):
            term = selected_ops[j]
            window_terms.append(term)
            window_labels.append(str(term.label))
    return window_terms, window_labels


def _phase2_record_sort_key(record: Mapping[str, Any]) -> tuple[float, float, int, int]:
    raw_score = record.get("phase2_raw_score", float("-inf"))
    if raw_score is None:
        raw_score = float("-inf")
    simple_score = record.get("simple_score", float("-inf"))
    if simple_score is None:
        simple_score = float("-inf")
    return (
        -float(raw_score),
        -float(simple_score),
        int(record.get("candidate_pool_index", -1)),
        int(record.get("position_id", -1)),
    )


def _hh_termwise_component_risk_gate(
    *,
    term: Any,
    num_sites: int,
    ordering: str,
    tol: float = 1e-10,
) -> tuple[bool, dict[str, Any] | None]:
    execution_mode = str(getattr(term, "execution_mode", "termwise_product") or "termwise_product")
    if execution_mode == "grouped_exact":
        return False, None
    polynomial = getattr(term, "polynomial")
    guard_spec = {
        "particle_number_mode": "preserving",
        "spin_sector_mode": "preserving",
        "hard_guard": True,
        "source": "hh_component_risk_execution_mode_guard",
    }
    polynomial_gate = _operator_symmetry_gate(
        polynomial=polynomial,
        num_sites=int(num_sites),
        ordering=str(ordering),
        symmetry_spec=guard_spec,
        tol=float(tol),
    )
    if not bool(polynomial_gate.get("passed", True)):
        return False, dict(polynomial_gate)
    for component_idx, component in enumerate(polynomial.return_polynomial()):
        component_gate = _operator_symmetry_gate(
            polynomial=PauliPolynomial("JW", [component]),
            num_sites=int(num_sites),
            ordering=str(ordering),
            symmetry_spec=guard_spec,
            tol=float(tol),
        )
        if bool(component_gate.get("passed", True)):
            continue
        out = dict(component_gate)
        out["component_index"] = int(component_idx)
        return True, out
    return False, None


def _enforce_hh_component_risk_grouped_execution(
    *,
    pool: Sequence[Any],
    pool_generator_registry: Mapping[str, Mapping[str, Any]],
    num_sites: int,
    ordering: str,
    tol: float = 1e-10,
) -> tuple[list[Any], dict[str, dict[str, Any]], dict[str, Any]]:
    repaired_pool: list[Any] = []
    repaired_registry = {str(k): dict(v) for k, v in pool_generator_registry.items()}
    converted_labels: list[str] = []
    component_checked_count = 0
    for idx, term in enumerate(pool):
        label = str(getattr(term, "label", f"pool[{idx}]"))
        requires_grouped, gate = _hh_termwise_component_risk_gate(
            term=term,
            num_sites=int(num_sites),
            ordering=str(ordering),
            tol=float(tol),
        )
        if gate is not None:
            component_checked_count += 1
        if not requires_grouped:
            repaired_pool.append(term)
            continue
        repaired_pool.append(
            AnsatzTerm(
                label=label,
                polynomial=getattr(term, "polynomial"),
                execution_mode="grouped_exact",
            )
        )
        converted_labels.append(label)
        meta = dict(repaired_registry.get(label, {}))
        compile_meta = dict(meta.get("compile_metadata", {})) if isinstance(meta.get("compile_metadata"), Mapping) else {}
        compile_meta["hh_component_risk_execution_mode_repair"] = {
            "schema": "hh_component_risk_execution_mode_repair_v1",
            "reason": "termwise_component_sector_violation",
            "from_execution_mode": str(getattr(term, "execution_mode", "termwise_product") or "termwise_product"),
            "to_execution_mode": "grouped_exact",
            "component_index": int(gate.get("component_index")) if isinstance(gate, Mapping) and gate.get("component_index") is not None else None,
            "commutator_l1_total": float(gate.get("commutator_l1_total", 0.0)) if isinstance(gate, Mapping) else None,
            "commutator_l1_up": float(gate.get("commutator_l1_up", 0.0)) if isinstance(gate, Mapping) else None,
            "commutator_l1_dn": float(gate.get("commutator_l1_dn", 0.0)) if isinstance(gate, Mapping) else None,
        }
        meta["compile_metadata"] = compile_meta
        meta["execution_mode"] = "grouped_exact"
        repaired_registry[label] = meta
    summary = {
        "active": True,
        "converted_count": int(len(converted_labels)),
        "converted_labels_sample": [str(x) for x in converted_labels[:20]],
        "component_checked_count": int(component_checked_count),
        "tol": float(tol),
    }
    return repaired_pool, repaired_registry, summary


def _verify_hh_expanded_pool_fermion_symmetry(
    *,
    pool: Sequence[Any],
    pool_family_ids: Sequence[str],
    pool_generator_registry: Mapping[str, Mapping[str, Any]],
    num_sites: int,
    ordering: str,
    tol: float = 1e-10,
) -> dict[str, Any]:
    guard_spec = {
        "particle_number_mode": "preserving",
        "spin_sector_mode": "preserving",
        "hard_guard": True,
        "source": "post_global_child_pool_expansion_guard",
    }
    offenders: list[dict[str, Any]] = []
    checked_count = 0
    termwise_component_checked_count = 0
    for idx, term in enumerate(pool):
        label = str(getattr(term, "label", f"pool[{idx}]"))
        polynomial = getattr(term, "polynomial")
        gate = _operator_symmetry_gate(
            polynomial=polynomial,
            num_sites=int(num_sites),
            ordering=str(ordering),
            symmetry_spec=guard_spec,
            tol=float(tol),
        )
        checked_count += 1
        metadata = pool_generator_registry.get(label, {})
        compile_meta = metadata.get("compile_metadata", {}) if isinstance(metadata, Mapping) else {}
        runtime_split = compile_meta.get("runtime_split", {}) if isinstance(compile_meta, Mapping) else {}
        prior_gate = runtime_split.get("symmetry_gate", {}) if isinstance(runtime_split, Mapping) else {}
        execution_mode = str(getattr(term, "execution_mode", "termwise_product") or "termwise_product")
        offender_reason: str | None = None
        offender_gate = dict(gate)
        if not bool(gate.get("passed", True)):
            offender_reason = "polynomial_sector_violation"
        elif execution_mode != "grouped_exact":
            for component_idx, component in enumerate(polynomial.return_polynomial()):
                component_gate = _operator_symmetry_gate(
                    polynomial=PauliPolynomial("JW", [component]),
                    num_sites=int(num_sites),
                    ordering=str(ordering),
                    symmetry_spec=guard_spec,
                    tol=float(tol),
                )
                termwise_component_checked_count += 1
                if bool(component_gate.get("passed", True)):
                    continue
                offender_reason = "termwise_component_sector_violation"
                offender_gate = dict(component_gate)
                offender_gate["component_index"] = int(component_idx)
                break
        if offender_reason is None:
            continue
        offenders.append(
            {
                "index": int(idx),
                "label": label,
                "family_id": str(pool_family_ids[int(idx)] if int(idx) < len(pool_family_ids) else "unknown"),
                "reason": str(offender_reason),
                "execution_mode": str(execution_mode),
                "commutator_l1_total": float(offender_gate.get("commutator_l1_total", 0.0)),
                "commutator_l1_up": float(offender_gate.get("commutator_l1_up", 0.0)),
                "commutator_l1_dn": float(offender_gate.get("commutator_l1_dn", 0.0)),
                "component_index": (
                    int(offender_gate.get("component_index"))
                    if offender_gate.get("component_index") is not None
                    else None
                ),
                "runtime_split": bool(isinstance(runtime_split, Mapping) and bool(runtime_split)),
                "runtime_split_prior_checked": (
                    bool(prior_gate.get("checked", False)) if isinstance(prior_gate, Mapping) else None
                ),
                "runtime_split_prior_skipped_reason": (
                    str(prior_gate.get("skipped_reason"))
                    if isinstance(prior_gate, Mapping) and prior_gate.get("skipped_reason") is not None
                    else None
                ),
            }
        )
        if len(offenders) >= 20:
            break
    summary = {
        "active": True,
        "checked_count": int(checked_count),
        "termwise_component_checked_count": int(termwise_component_checked_count),
        "passed": bool(not offenders),
        "tol": float(tol),
    }
    if offenders:
        summary["offender_sample"] = [dict(row) for row in offenders]
        first = offenders[0]
        raise ValueError(
            "HH expanded child pool contains sector-violating generator(s); "
            f"first_label={first['label']!r}, "
            f"reason={first['reason']}, "
            f"execution_mode={first['execution_mode']}, "
            f"commutator_l1_total={first['commutator_l1_total']}, "
            f"commutator_l1_up={first['commutator_l1_up']}, "
            f"commutator_l1_dn={first['commutator_l1_dn']}."
        )
    return summary



def _parse_source_lock_preferred_sequence(raw: Any) -> tuple[str, ...]:
    if raw is None or raw == "":
        return ()
    if isinstance(raw, str):
        text = raw.strip()
        if not text or text.lower() in {"off", "none", "null"}:
            return ()
        try:
            decoded = json.loads(text)
        except json.JSONDecodeError:
            tokens = [tok.strip() for tok in re.split(r"[|,\n]", text) if tok.strip()]
        else:
            if isinstance(decoded, str):
                tokens = [decoded]
            elif isinstance(decoded, Sequence) and not isinstance(decoded, (str, bytes)):
                tokens = [str(tok) for tok in decoded]
            else:
                raise ValueError("phase3_source_lock_preferred_sequence must be a JSON string/list or delimited string.")
    elif isinstance(raw, Sequence) and not isinstance(raw, (str, bytes)):
        tokens = [str(tok) for tok in raw]
    else:
        raise ValueError("phase3_source_lock_preferred_sequence must be a sequence or string.")
    sequence = tuple(str(tok).strip() for tok in tokens if str(tok).strip())
    return sequence


def _find_record_by_candidate_label(
    records: Sequence[Mapping[str, Any]],
    label: str | None,
) -> dict[str, Any] | None:
    if label in {None, ""}:
        return None
    label_key = str(label)
    for record in records:
        if _record_candidate_label(record) == label_key:
            return dict(record)
    return None


def _record_like_mapping(record: Mapping[str, Any] | Any) -> dict[str, Any]:
    """Return a shallow mapping view for candidate records, features, or history rows."""

    if isinstance(record, CandidateFeatures):
        return dict(record.__dict__)
    if isinstance(record, Mapping):
        if isinstance(record.get("feature"), CandidateFeatures):
            merged = dict(record["feature"].__dict__)
            merged.update({str(k): v for k, v in record.items() if str(k) != "feature"})
            return merged
        selected_rows = record.get("selected_feature_rows")
        if (
            isinstance(selected_rows, Sequence)
            and not isinstance(selected_rows, (str, bytes, bytearray))
            and selected_rows
            and isinstance(selected_rows[0], Mapping)
        ):
            merged = dict(selected_rows[0])
            merged.update({str(k): v for k, v in record.items() if str(k) != "selected_feature_rows"})
            return merged
        return dict(record)
    return {}


def _ranked_admission_records(
    records: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Keep ranked records without imposing an absolute score threshold."""

    return [dict(record) for record in records]


def _filter_sector_safe_admission_records(
    records: Sequence[Mapping[str, Any]],
    *,
    assert_safe: Callable[[Mapping[str, Any]], None],
) -> tuple[list[dict[str, Any]], list[str]]:
    """Remove records rejected by the runtime admission-sector guard.

    Candidate scoring may retain a parent template whose executed
    termwise-product representation is unsafe because a later runtime split can
    still expose legal projected children.  Such a template is never itself an
    admissible operator.  Selectors that consume a pre-split Phase-II population
    must therefore apply the authoritative runtime guard before ranking, rather
    than discovering the violation only after choosing the winning record.
    """

    retained: list[dict[str, Any]] = []
    rejected_labels: list[str] = []
    for record in records:
        row = dict(record)
        try:
            assert_safe(row)
        except RuntimeError:
            rejected_labels.append(str(_record_candidate_label(row)))
            continue
        retained.append(row)
    return retained, rejected_labels


def _final_full_refit_policy_supported(policy: str) -> bool:
    return str(policy).strip().lower() in {"windowed", "full"}


def _history_row_was_full_prefix_reopt(
    row: Mapping[str, Any] | None,
    *,
    selected_operator_count: int,
) -> bool:
    if not isinstance(row, Mapping):
        return False
    effective = str(row.get("reopt_policy_effective", ""))
    if not (
        effective == "full"
        or effective.startswith("full+")
        or effective.startswith("windowed_periodic_full")
    ):
        return False
    try:
        active_count = int(row.get("reopt_active_count", 0))
    except (TypeError, ValueError):
        return False
    return bool(int(active_count) == int(selected_operator_count))


def _accepted_live_prune_labels_from_history(
    history_rows: Sequence[Mapping[str, Any]] | None,
) -> list[str]:
    """Return labels already removed by accepted live post-admission pruning."""
    labels: list[str] = []
    seen: set[str] = set()
    if not isinstance(history_rows, Sequence):
        return labels
    for row in history_rows:
        if not isinstance(row, Mapping):
            continue
        prune_payload = row.get("post_admission_prune")
        if not isinstance(prune_payload, Mapping):
            continue
        if int(prune_payload.get("accepted_count", 0) or 0) <= 0:
            continue
        decisions_raw = prune_payload.get("decisions", [])
        if not isinstance(decisions_raw, Sequence) or isinstance(decisions_raw, (str, bytes)):
            continue
        for decision in decisions_raw:
            if not isinstance(decision, Mapping):
                continue
            if not bool(decision.get("accepted", False)):
                continue
            label = str(decision.get("label", ""))
            if not label or label in seen:
                continue
            seen.add(label)
            labels.append(label)
    return labels


def _route_c_sp_qngd_unaccounted_geometry_probe_count(
    history_rows: Sequence[Mapping[str, Any]] | None,
) -> int:
    """Count SP-QNGD geometry probes absent from the shared estimator ledger.

    Route-C SP-QNGD Hamiltonian evaluations are recorded in the canonical
    ledger. Its finite-difference tangent-state probes and derived metric
    evaluations do not yet have physical primitive identities, so a positive
    count must keep exact cross-route ``S_alg`` accounting fail closed.
    """

    if not isinstance(history_rows, Sequence):
        return 0
    probe_count = 0
    for row in history_rows:
        if not isinstance(row, Mapping):
            continue
        plateau_event = row.get("route_c_plateau_acquisition")
        if not isinstance(plateau_event, Mapping):
            continue
        trial_optimizer_info = plateau_event.get("trial_optimizer_info")
        if not isinstance(trial_optimizer_info, Mapping):
            continue
        if (
            str(trial_optimizer_info.get("optimizer", ""))
            != "route_c_sp_qngd_v1"
        ):
            continue
        probe_count += int(
            trial_optimizer_info.get("qngd_state_probe_count", 0) or 0
        )
        probe_count += int(
            trial_optimizer_info.get("qngd_metric_eval_count", 0) or 0
        )
    return int(probe_count)


def _filter_repeat_live_prune_candidates(
    candidate_indices: Sequence[int],
    labels_now: Sequence[str],
    blocked_labels: Sequence[str],
) -> tuple[list[int], list[dict[str, Any]]]:
    """Drop live-prune candidates whose label was already accepted for removal."""
    blocked = {str(label) for label in blocked_labels if str(label)}
    kept: list[int] = []
    blocked_rows: list[dict[str, Any]] = []
    for idx_raw in candidate_indices:
        idx = int(idx_raw)
        label = str(labels_now[idx]) if 0 <= idx < len(labels_now) else ""
        if label in blocked:
            blocked_rows.append(
                {
                    "index": int(idx),
                    "label": str(label),
                    "reason": "previous_live_prune_acceptance_same_label",
                }
            )
            continue
        kept.append(int(idx))
    return kept, blocked_rows


def _apply_repeat_live_prune_guard(
    *,
    candidate_indices: Sequence[int],
    labels_now: Sequence[str],
    blocked_labels: Sequence[str],
    bypass_for_model_nominated_single_trial: bool,
) -> tuple[list[int], list[dict[str, Any]], dict[str, Any]]:
    """Apply the historical repeat-label guard unless v4 owns nomination.

    The v4 affine-deletion model nominates exactly one deletion for exactly one
    measured trial.  A historical cooldown must not silently veto that model
    output.  Older routes retain the existing guard unchanged.
    """

    candidates = [int(index) for index in candidate_indices]
    blocked = [str(label) for label in blocked_labels if str(label)]
    if bool(bypass_for_model_nominated_single_trial):
        return candidates, [], {
            "active": False,
            "bypassed": True,
            "bypass_reason": "v4_model_nominated_single_exact_trial_v1",
            "blocked_labels": blocked,
            "blocked_rows": [],
            "blocked_count": 0,
            "pre_guard_candidate_count": int(len(candidates)),
            "post_guard_candidate_count": int(len(candidates)),
        }
    kept, blocked_rows = _filter_repeat_live_prune_candidates(
        candidate_indices=candidates,
        labels_now=labels_now,
        blocked_labels=blocked,
    )
    return kept, blocked_rows, {
        "active": bool(blocked),
        "bypassed": False,
        "bypass_reason": None,
        "blocked_labels": blocked,
        "blocked_rows": [dict(row) for row in blocked_rows],
        "blocked_count": int(len(blocked_rows)),
        "pre_guard_candidate_count": int(len(candidates)),
        "post_guard_candidate_count": int(len(kept)),
    }


def _sr_v4_all_infeasible_prune_hold_receipt(
    *,
    route_active: bool,
    nomination_payload: Mapping[str, Any],
    trust_state: AffineDeletionFSTrustState | None,
) -> dict[str, Any] | None:
    """Return the v4 no-feasible-model hold receipt before any legacy ranking.

    An empty affine score map is not permission to rank by an unmodeled
    fallback proxy.  When the solver evaluated every deletion and certified
    none feasible, v4 skips the prune trial and preserves its branch-local
    radius, damping, and update counter exactly.
    """

    if not bool(route_active):
        return None
    if trust_state is None:
        raise RuntimeError(
            "SR-SNAKE v4 cannot resolve an infeasible prune round without its "
            "branch-local trust state."
        )
    payload = dict(nomination_payload)
    rows_raw = payload.get("affine_deletion_models")
    if not isinstance(rows_raw, Sequence) or isinstance(
        rows_raw, (str, bytes, bytearray)
    ):
        raise RuntimeError(
            "SR-SNAKE v4 affine-deletion nomination lacks its model rows."
        )
    rows = [dict(row) for row in rows_raw if isinstance(row, Mapping)]
    try:
        declared_count = int(payload["affine_deletion_model_count"])
        declared_feasible_count = int(payload["affine_deletion_feasible_count"])
    except (KeyError, TypeError, ValueError) as exc:
        raise RuntimeError(
            "SR-SNAKE v4 affine-deletion feasibility counts are missing."
        ) from exc
    observed_feasible_count = int(
        sum(1 for row in rows if bool(row.get("feasible", False)))
    )
    if (
        declared_count < 0
        or declared_feasible_count < 0
        or declared_count != len(rows)
        or declared_feasible_count != observed_feasible_count
    ):
        raise RuntimeError(
            "SR-SNAKE v4 affine-deletion feasibility telemetry is inconsistent."
        )
    if declared_count == 0 or declared_feasible_count > 0:
        return None

    reason_counts: dict[str, int] = {}
    for row in rows:
        reason = str(row.get("reason", "unspecified_infeasible_model"))
        reason_counts[reason] = int(reason_counts.get(reason, 0) + 1)
    state_payload = {
        "schema": "affine_deletion_fs_trust_state_v1",
        "radius": float(trust_state.radius),
        "metric_damping": float(trust_state.metric_damping),
        "update_count": int(trust_state.update_count),
    }
    return {
        "schema": "sr_v4_no_feasible_affine_deletion_models_v1",
        "status": "skipped_no_feasible_affine_deletion_models",
        "reason": "all_affine_deletion_models_infeasible",
        "model_count": int(declared_count),
        "feasible_model_count": 0,
        "infeasible_reason_counts": dict(sorted(reason_counts.items())),
        "legacy_nomination_fallback_used": False,
        "exact_delete_refit_trial_count": 0,
        "trust_state_action": "hold_exactly",
        "trust_state_before": dict(state_payload),
        "trust_state_after": dict(state_payload),
        "trust_update": {
            "schema": "affine_deletion_fs_trust_state_update_v1",
            "status": "held",
            "reason": "all_affine_deletion_models_infeasible",
            "radius_before": float(trust_state.radius),
            "radius_after": float(trust_state.radius),
            "radius_action": "hold_no_feasible_model",
            "metric_damping_before": float(trust_state.metric_damping),
            "metric_damping_after": float(trust_state.metric_damping),
            "metric_damping_action": "hold_no_feasible_model",
            "update_count_before": int(trust_state.update_count),
            "update_count_after": int(trust_state.update_count),
            "classical_quantum_query_charge": 0,
        },
        "classical_quantum_query_charge": 0,
    }


def _sr_v4_no_eligible_material_window_prune_hold_receipt(
    *,
    route_active: bool,
    nomination_payload: Mapping[str, Any],
    trust_state: AffineDeletionFSTrustState | None,
) -> dict[str, Any] | None:
    """Hold v4 when measured ``W`` contains no old deletion coordinate."""

    if not bool(route_active):
        return None
    payload = dict(nomination_payload)
    if str(payload.get("reason", "")) != (
        "no_eligible_old_coordinates_in_material_window"
    ):
        return None
    if trust_state is None:
        raise RuntimeError(
            "SR-SNAKE v4 cannot hold an empty material-window prune round "
            "without its branch-local trust state."
        )
    rows_raw = payload.get("affine_deletion_models")
    if not isinstance(rows_raw, Sequence) or isinstance(
        rows_raw, (str, bytes, bytearray)
    ):
        raise RuntimeError(
            "Empty material-window prune nomination lacks its model rows."
        )
    if (
        len(list(rows_raw)) != 0
        or int(payload.get("affine_deletion_model_count", -1)) != 0
        or int(payload.get("affine_deletion_feasible_count", -1)) != 0
        or int(payload.get("score_count", -1)) != 0
    ):
        raise RuntimeError(
            "Empty material-window prune nomination has inconsistent counts."
        )
    state_payload = {
        "schema": "affine_deletion_fs_trust_state_v1",
        "radius": float(trust_state.radius),
        "metric_damping": float(trust_state.metric_damping),
        "update_count": int(trust_state.update_count),
    }
    return {
        "schema": "sr_v4_no_eligible_material_window_prune_model_v1",
        "status": "skipped_no_eligible_old_coordinates",
        "reason": "no_eligible_old_coordinates_in_material_window",
        "model_count": 0,
        "feasible_model_count": 0,
        "legacy_nomination_fallback_used": False,
        "admitted_singleton_nominated": False,
        "exact_delete_refit_trial_count": 0,
        "trust_state_action": "hold_exactly",
        "trust_state_before": dict(state_payload),
        "trust_state_after": dict(state_payload),
        "trust_update": {
            "schema": "affine_deletion_fs_trust_state_update_v1",
            "status": "held",
            "reason": "no_eligible_old_coordinates_in_material_window",
            "radius_before": float(trust_state.radius),
            "radius_after": float(trust_state.radius),
            "radius_action": "hold_no_eligible_old_coordinate",
            "metric_damping_before": float(trust_state.metric_damping),
            "metric_damping_after": float(trust_state.metric_damping),
            "metric_damping_action": "hold_no_eligible_old_coordinate",
            "update_count_before": int(trust_state.update_count),
            "update_count_after": int(trust_state.update_count),
            "classical_quantum_query_charge": 0,
        },
        "classical_quantum_query_charge": 0,
    }


def _phase3_shadow_recommended_mu_from_history(
    history_rows: Sequence[Mapping[str, Any]] | None,
) -> tuple[float, str]:
    """Restore the last serialized zero-query shadow recommendation."""

    for row in reversed(list(history_rows or ())):
        if not isinstance(row, Mapping):
            continue
        receipt = row.get("phase3_shadow_damping_receipt")
        if receipt is None:
            continue
        if not isinstance(receipt, Mapping):
            raise RuntimeError(
                "Phase-III shadow damping history receipt is malformed."
            )
        if str(receipt.get("schema", "")) != (
            "route_a_phase3_shadow_damping_receipt_v1"
        ):
            raise RuntimeError(
                "Phase-III shadow damping history receipt schema is unsupported."
            )
        try:
            recommended_mu = float(receipt["recommended_mu"])
            applied_mu = float(receipt.get("applied_mu", 0.0))
            added_query_count = int(receipt.get("added_query_count", 0))
        except (KeyError, TypeError, ValueError) as exc:
            raise RuntimeError(
                "Phase-III shadow damping history state cannot be reconstructed."
            ) from exc
        if (
            not math.isfinite(recommended_mu)
            or recommended_mu < 0.0
            or applied_mu != 0.0
            or added_query_count != 0
        ):
            raise RuntimeError(
                "Phase-III shadow damping history violates the zero-query "
                "diagnostic contract."
            )
        return float(recommended_mu), "previous_history_receipt"
    return 0.0, "initialized_zero"




def _projective_state_overlap_estimator_call_key(
    state_before: Sequence[complex] | np.ndarray,
    state_after: Sequence[complex] | np.ndarray,
    *,
    hamiltonian_fingerprint: str,
    backend_fingerprint: str,
    precision_contract: str,
) -> EstimatorCallKey:
    """Identify one decision-authoritative endpoint-overlap primitive.

    The measured magnitude is symmetric in its two prepared states.  The
    canonical lexical endpoint anchors the otherwise single-state key field,
    while the v2 symmetric operand pair preserves both physical preparations.
    Reversing the trust-update endpoints therefore cannot create a second
    logical oracle charge.
    """

    endpoint_fingerprints = tuple(
        sorted(
            (
                estimator_projective_state_fingerprint(
                    np.asarray(state_before, dtype=complex).reshape(-1)
                ),
                estimator_projective_state_fingerprint(
                    np.asarray(state_after, dtype=complex).reshape(-1)
                ),
            )
        )
    )
    endpoint_operands = tuple(
        f"projective_state_operand_v1:{fingerprint}"
        for fingerprint in endpoint_fingerprints
    )
    return EstimatorCallKey(
        projective_state_fingerprint=str(endpoint_fingerprints[0]),
        hamiltonian_fingerprint=str(hamiltonian_fingerprint),
        backend_fingerprint=str(backend_fingerprint),
        precision_contract=str(precision_contract),
        primitive_kind="state_overlap",
        observable_or_formula_identity=(
            "projective_endpoint_overlap_magnitude_v1"
        ),
        symmetric_pair=(endpoint_operands[0], endpoint_operands[1]),
        schema=CALL_KEY_SCHEMA_V2,
    )


def _restored_estimator_prefix_checkpoint_state(
    ledger: EstimatorCallLedger,
    *,
    prior_receipts: Sequence[Mapping[str, Any]] | None,
    source_outer_iteration: int,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Restore receipt deltas without restarting cumulative accounting at zero.

    Modern result artifacts carry every prefix receipt and are preserved after
    strict reconciliation.  Older authenticated checkpoints may carry only the
    cumulative ledger.  For those, one explicit synthetic prefix receipt
    represents the whole restored segment so later per-round deltas and the
    terminal closure remain exact rather than double counting the prefix.
    """

    components = ("N_H_outer", "N_H_refit", "N_grad", "N_metric")
    unique_summary = ledger.summary()
    occurrence_summary = ledger.occurrence_summary()
    unique_components = {
        component: int(unique_summary.get(component, 0))
        for component in components
    }
    occurrence_components = {
        component: int(occurrence_summary.get(component, 0))
        for component in components
    }
    unique_total = int(unique_summary.get("unique_primitive_count", 0))
    raw_total = int(occurrence_summary.get("total_call_occurrences", 0))
    preserved = [
        copy.deepcopy(dict(receipt))
        for receipt in list(prior_receipts or ())
        if isinstance(receipt, Mapping)
    ]
    if prior_receipts is not None and len(preserved) != len(prior_receipts):
        raise ValueError(
            "Restored estimator prefix receipts must all be mappings."
        )

    if preserved:
        enabled = [
            receipt
            for receipt in preserved
            if bool(receipt.get("enabled", False))
        ]
        if not enabled:
            raise ValueError(
                "Restored estimator prefix receipts contain no enabled receipt."
            )
        sequences = [
            int(receipt.get("checkpoint_sequence", -1))
            for receipt in enabled
        ]
        if sequences != list(range(1, len(sequences) + 1)):
            raise ValueError(
                "Restored estimator prefix receipt sequences are not contiguous."
            )
        summed_raw_components = {
            component: sum(
                int(
                    dict(receipt.get("raw_occurrence_delta", {}))
                    .get("components", {})
                    .get(component, 0)
                )
                for receipt in enabled
            )
            for component in components
        }
        summed_unique_components = {
            component: sum(
                int(
                    dict(receipt.get("unique_primitive_delta", {}))
                    .get("components", {})
                    .get(component, 0)
                )
                for receipt in enabled
            )
            for component in components
        }
        last = enabled[-1]
        last_raw = dict(last.get("cumulative_raw_occurrences", {}))
        last_unique = dict(last.get("cumulative_unique_primitives", {}))
        last_unique_total = int(
            last_unique.get(
                "S_unique",
                # Compatibility with authenticated pre-v2 checkpoints.
                last_unique.get("S_alg", -1),
            )
        )
        if (
            summed_raw_components != occurrence_components
            or summed_unique_components != unique_components
            or int(last_raw.get("total", -1)) != raw_total
            or last_unique_total != unique_total
        ):
            raise ValueError(
                "Restored estimator prefix receipts do not reconcile with "
                "the authenticated cumulative ledger."
            )
        checkpoint_sequence = int(sequences[-1])
    else:
        checkpoint_sequence = 1
        preserved = [
            {
                "schema": "paper_i_active_prefix_estimator_ledger_receipt_v2",
                "enabled": True,
                "status": "complete",
                "checkpoint_sequence": 1,
                "occurrence_sequence_start_exclusive": 0,
                "occurrence_sequence_end_inclusive": int(raw_total),
                "raw_occurrence_delta": {
                    "components": dict(occurrence_components),
                    "total": int(raw_total),
                },
                "executed_query_delta": {
                    "components": dict(occurrence_components),
                    "S_alg": int(raw_total),
                },
                "unique_primitive_delta": {
                    "components": dict(unique_components),
                    "S_unique": int(unique_total),
                },
                "cumulative_raw_occurrences": {
                    "components": dict(occurrence_components),
                    "total": int(raw_total),
                },
                "cumulative_executed_queries": {
                    "components": dict(occurrence_components),
                    "S_alg": int(raw_total),
                    "unit": (
                        "executed_logical_scalar_estimator_invocation"
                    ),
                },
                "cumulative_unique_primitives": {
                    "components": dict(unique_components),
                    "S_unique": int(unique_total),
                },
                "outer_iteration": int(source_outer_iteration),
                "checkpoint_kind": (
                    "restored_authenticated_completed_round_prefix"
                ),
                "branch_id": None,
                "parent_branch_id": None,
                "physical_identity_collapse_is_diagnostic_only": True,
                "raw_occurrences_preserved": True,
                "runtime_estimator_occurrence_contract": (
                    "all_instrumented_logical_scalar_estimator_calls_v1"
                ),
                "restored_prefix_compaction": True,
            }
        ]

    cursor = {
        "checkpoint_sequence": int(checkpoint_sequence),
        "raw_occurrence_count": int(raw_total),
        "unique_primitive_count": int(unique_total),
        "unique_components": dict(unique_components),
        "occurrence_components": dict(occurrence_components),
    }
    return cursor, preserved


def _initial_outer_measurement_state_matches(
    current_state: Sequence[complex] | np.ndarray,
    cached_state: Sequence[complex] | np.ndarray,
) -> bool:
    """Require exact deterministic state identity before reusing cached H|psi>."""

    current = np.asarray(current_state, dtype=complex)
    cached = np.asarray(cached_state, dtype=complex)
    return bool(
        current.shape == cached.shape
        and np.array_equal(current, cached)
    )


