        phase2_lane_rel_threshold=float(
            physical_phase2_lane_rel_threshold_val
        ),
        shortlist_lane_route=str(static_lane_route_key),
        shortlist_lane_key=str(shortlist_lane_spec.lane_key),
        shortlist_lanes=tuple(str(lane) for lane in shortlist_lane_spec.lanes),
        shortlist_fallback_lane=str(shortlist_lane_spec.fallback_lane),
