        phase3_selector_debug_topk_val=int(phase3_selector_debug_topk_val),
        phase3_selector_debug_max_depth_val=int(phase3_selector_debug_max_depth_val),
        phase3_selector_geometry_mode_key=str(phase3_selector_geometry_mode_key),
