    def _apply_prune_prefilter(
        *,
        candidate_indices: Sequence[int],
        labels_now: Sequence[str],
        summary: dict[str, Any],
    ) -> list[int]:
        ranked_indices = [int(x) for x in candidate_indices]
        candidate_features: dict[int, dict[str, Any]] = {}
        for pos, raw in enumerate(summary.get("metadata", []) or []):
            if not isinstance(raw, Mapping):
                continue
            candidate_features.setdefault(int(pos), {}).update(
                {
                    "label": str(raw.get("candidate_label", "")),
                    "selector_score": float(raw.get("selector_score", 0.0) or 0.0),
                    "selector_burden": float(raw.get("selector_burden", 0.0) or 0.0),
                    "cooldown_remaining": int(raw.get("cooldown_remaining", 0) or 0),
                    "selector_value_per_burden": float(raw.get("selector_score", 0.0) or 0.0)
                    / float(1.0 + max(0.0, float(raw.get("selector_burden", 0.0) or 0.0))),
                }
            )
        for raw in summary.get("gate_rows", []) or []:
            if not isinstance(raw, Mapping):
                continue
            idx = int(raw.get("index", -1) or -1)
            if idx < 0:
                continue
            candidate_features.setdefault(idx, {}).update(
                {
                    "first_seen_age": int(raw.get("first_seen_age", 0) or 0),
                    "admission_age": int(raw.get("admission_age", 0) or 0),
                    "selector_burden": float(
                        raw.get(
                            "selector_burden",
                            candidate_features.get(idx, {}).get("selector_burden", 0.0),
                        )
                        or 0.0
                    ),
                    "protected": bool(raw.get("protected", False)),
                    "cooldown_blocked": bool(raw.get("cooldown_blocked", False)),
                    "recoverability_eligible": bool(raw.get("recoverability_eligible", False)),
                }
            )
        schur_payload_for_features = summary.get("schur_surrogate_nomination", {})
        if isinstance(schur_payload_for_features, Mapping):
            for raw in schur_payload_for_features.get("rows", []) or []:
                if not isinstance(raw, Mapping):
                    continue
                idx = int(raw.get("index", -1) or -1)
                if idx < 0:
                    continue
                candidate_features.setdefault(idx, {}).update(
                    {
                        "schur_score": float(raw.get("score", raw.get("schur_min", float("inf")))),
                        "schur_min": float(raw.get("schur_min", raw.get("score", float("inf")))),
                        "schur_used_for_nomination": bool(
                            schur_payload_for_features.get("used_for_nomination", False)
                        ),
                    }
                )
        if phase1_prune_prefilter_policy_key == PRUNE_PREFILTER_OFF:
            summary.update(
                {
                    "prune_prefilter_input_count": int(len(ranked_indices)),
                    "prune_prefilter_allowed_count": int(len(ranked_indices)),
                    "prune_prefilter_blocked_count": 0,
                    "prune_prefilter_rows": [],
                    "prune_prefilter_blocked_indices": [],
                    "prune_prefilter_blocked_labels": [],
                }
            )
            return ranked_indices
        if phase1_prune_prefilter_policy_key != PRUNE_PREFILTER_MOTIF_RISK_V1:
            raise ValueError(
                f"Unsupported phase1 prune prefilter policy: {phase1_prune_prefilter_policy_key}"
            )
        if phase1_prune_prefilter_profile is None:
            raise ValueError("motif_risk_v1 prune prefilter has no loaded profile.")
        allowed_indices, telemetry = filter_prune_candidates_by_motif_risk(
            candidate_indices=ranked_indices,
            labels=[str(x) for x in labels_now],
            profile=phase1_prune_prefilter_profile,
            risk_threshold=float(phase1_prune_risk_threshold),
            max_candidates=int(phase1_prune_prefilter_max_candidates),
            candidate_features=candidate_features,
        )
        summary.update(
            {
                "prune_prefilter_input_count": int(telemetry.get("input_count", len(ranked_indices))),
                "prune_prefilter_allowed_count": int(telemetry.get("allowed_count", len(allowed_indices))),
                "prune_prefilter_blocked_count": int(telemetry.get("blocked_count", 0)),
                "prune_prefilter_rows": [dict(x) for x in telemetry.get("rows", [])],
                "prune_prefilter_blocked_indices": [
                    int(x) for x in telemetry.get("blocked_indices", [])
                ],
                "prune_prefilter_blocked_labels": [
                    str(x) for x in telemetry.get("blocked_labels", [])
                ],
            }
        )
        return [int(x) for x in allowed_indices]

    def _evaluate_prune_tolerance(
        *,
        sigma_e: float | None,
        delta_scr: float | None,
        current_energy: float | None,
    ) -> dict[str, Any]:
        return compute_prune_regression_tolerance(
            delta_num=float(phase1_prune_cfg.max_regression),
            mode=str(phase1_prune_cfg.tolerance_mode),
            sigma_e=sigma_e,
            delta_scr=delta_scr,
            delta_chem=float(phase1_prune_cfg.tolerance_chem),
            current_energy=current_energy,
            target_energy=phase1_prune_cfg.tolerance_target_energy,
            c_shot=float(phase1_prune_cfg.tolerance_shot_coeff),
            c_scr=float(phase1_prune_cfg.tolerance_screen_coeff),
            c_rel=float(phase1_prune_cfg.tolerance_rel_coeff),
        )

    def _attach_prune_tolerance(
        summary: dict[str, Any],
        *,
        sigma_e: float | None,
        delta_scr: float | None,
        current_energy: float | None,
    ) -> tuple[float, dict[str, Any]]:
        tolerance = _evaluate_prune_tolerance(
            sigma_e=sigma_e,
            delta_scr=delta_scr,
            current_energy=current_energy,
        )
        effective = float(tolerance.get("effective_tolerance", phase1_prune_cfg.max_regression))
        summary["max_regression_effective"] = float(effective)
        summary["prune_tolerance"] = dict(tolerance)
        return float(effective), dict(tolerance)

    def _affine_prune_state_payload(
        state: AffineDeletionFSTrustState,
        *,
        source: str,
    ) -> dict[str, Any]:
        return {
            "schema": "affine_deletion_fs_trust_state_v1",
            "radius": float(state.radius),
            "metric_damping": float(state.metric_damping),
            "update_count": int(state.update_count),
            "source": str(source),
        }

    def _resolve_affine_prune_state(
        history_rows: Sequence[Mapping[str, Any]] | None,
    ) -> tuple[AffineDeletionFSTrustState, str]:
        history_list = list(history_rows or ())
        # Live pruning runs after the current admission row has been appended
        # but before its post-admission-prune payload exists.  That open row is
        # not resume state; consume only the latest completed prior row.
        if history_list:
            current_or_latest = history_list[-1]
            if not isinstance(current_or_latest, Mapping):
                raise RuntimeError(
                    "SR-SNAKE v4 latest history row is malformed; refusing to "
                    "reinitialize prune trust state."
                )
            if not isinstance(
                current_or_latest.get("post_admission_prune"), Mapping
            ):
                history_list = history_list[:-1]
        if not history_list:
            if bool(structural_resume_loaded):
                raise RuntimeError(
                    "SR-SNAKE v4 structural resume lacks a completed prior "
                    "prune trust state; refusing profile reinitialization."
                )
            return (
                initialize_affine_deletion_fs_trust_state(
                    radius=float(
                        phase1_prune_cfg.surrogate_recovery_trust_radius
                    )
                ),
                "initialized_from_profile_radius",
            )

        latest_history_row = history_list[-1]
        prune_payload = latest_history_row.get("post_admission_prune")
        if not isinstance(prune_payload, Mapping):
            raise RuntimeError(
                "SR-SNAKE v4 latest history row lacks post-admission prune "
                "state; refusing to reinitialize from the profile."
            )
        raw_state = prune_payload.get("phase1_prune_trust_state_after")
        if not isinstance(raw_state, Mapping):
            raise RuntimeError(
                "SR-SNAKE v4 latest prune radius/mu/update_count state is "
                "missing or malformed; refusing to search older history."
            )
        try:
            state = AffineDeletionFSTrustState(
                radius=float(raw_state["radius"]),
                metric_damping=float(raw_state["metric_damping"]),
                update_count=int(raw_state["update_count"]),
            )
        except (KeyError, TypeError, ValueError) as exc:
            raise RuntimeError(
                "SR-SNAKE v4 latest prune trust state cannot be reconstructed."
            ) from exc
        return state, "latest_history_state"

    def _build_prune_schur_nomination_scores(
        *,
        ops_now: Sequence[AnsatzTerm],
        theta_now: np.ndarray,
        layout_now: AnsatzParameterLayout,
        executor_now: CompiledAnsatzExecutor | None,
        labels_now: Sequence[str],
        stage: str,
        affine_trust_state: AffineDeletionFSTrustState | None = None,
        source_geometry_workspace: Mapping[str, Any] | None = None,
        source_geometry_unavailable_reason: str | None = None,
    ) -> tuple[dict[int, dict[str, Any]], dict[str, Any]]:
        labels_list = [str(x) for x in labels_now]
        logical_count = int(len(labels_list))
        runtime_count = int(getattr(layout_now, "runtime_parameter_count", logical_count))
        inactive_base = {
            "logical_parameter_count": int(logical_count),
            "runtime_parameter_count": int(runtime_count),
        }
        metric_route_active = bool(
            str(phase1_prune_cfg.schur_nomination_route)
            == PRUNE_SCHUR_ROUTE_METRIC_REGULARIZED_V1
        )
        affine_trust_route_active = bool(
            str(phase1_prune_cfg.schur_nomination_route)
            == PRUNE_SCHUR_ROUTE_FULL_LOGICAL_FS_TRUST_DELETE_REFIT_V1
        )
        geometry_metric_required = bool(
            metric_route_active or affine_trust_route_active
        )
        affine_solver_rows: list[dict[str, Any]] = []
        source_geometry_reuse_receipt: dict[str, Any] | None = None

        def _ansatz_entry_cost_payload() -> dict[str, Any]:
            rows: list[dict[str, Any]] = []
            for entry_idx, op in enumerate(list(ops_now)):
                try:
                    term_count = int(len(list(op.polynomial.return_polynomial())))
                except Exception:
                    term_count = 1
                try:
                    compile_est = phase1_compile_oracle.estimate(
                        candidate_term_count=int(max(1, term_count)),
                        position_id=int(entry_idx),
                        append_position=int(entry_idx),
                        refit_active_count=int(max(0, logical_count - 1)),
                        candidate_term=op,
                    )
                    rows.append(
                        {
                            "index": int(entry_idx),
                            "label": str(labels_list[int(entry_idx)])
                            if int(entry_idx) < len(labels_list)
                            else str(getattr(op, "label", entry_idx)),
                            "c_hat_2q": float(compile_est.c_hat_2q),
                            "c_hat_d": float(compile_est.c_hat_d),
                            "c_hat_1q": float(compile_est.c_hat_1q),
                            "c_hat_theta": float(compile_est.c_hat_theta),
                            "c_hat_shot": float(term_count),
                            "hardware_cost_source": str(compile_est.hardware_cost_source),
                        }
                    )
                except Exception:
                    rows.append(
                        {
                            "index": int(entry_idx),
                            "label": str(labels_list[int(entry_idx)])
                            if int(entry_idx) < len(labels_list)
                            else str(getattr(op, "label", entry_idx)),
                            "c_hat_2q": 1.0,
                            "c_hat_d": 1.0,
                            "c_hat_1q": 1.0,
                            "c_hat_theta": 1.0,
                            "c_hat_shot": float(max(1, term_count)),
                            "hardware_cost_source": "fallback_term_count_v1",
                        }
                    )
            payload = hardware_cost_ansatz_entry_denominators(rows, phase1_score_cfg)
            if (
                str(phase1_prune_cfg.metric_schur_cost_weighting)
                == PRUNE_METRIC_COST_WEIGHT_OFF
            ):
                payload = dict(payload)
                payload["denominators"] = [1.0 for _ in range(int(logical_count))]
                payload["cost_weighting_disabled"] = True
            return dict(payload)

        if not bool(phase1_prune_cfg.surrogate_enabled):
            return {}, _inactive_prune_schur_nomination_payload(
                prune_cfg=phase1_prune_cfg,
                selected_parameterization_mode=selected_parameterization_mode,
                reason="surrogate_disabled",
                **inactive_base,
            )
        if str(phase1_prune_cfg.policy) != PRUNE_POLICY_RECOVERABILITY_LADDER_V1:
            return {}, _inactive_prune_schur_nomination_payload(
                prune_cfg=phase1_prune_cfg,
                selected_parameterization_mode=selected_parameterization_mode,
                reason="requires_recoverability_ladder_policy",
                **inactive_base,
            )
        if int(logical_count) <= 1:
            return {}, _inactive_prune_schur_nomination_payload(
                prune_cfg=phase1_prune_cfg,
                selected_parameterization_mode=selected_parameterization_mode,
                reason="not_enough_coordinates",
                **inactive_base,
            )
        try:
            theta_runtime = np.asarray(theta_now, dtype=float).reshape(-1)
            theta_logical = np.asarray(_logical_theta_alias(theta_runtime, layout_now), dtype=float).reshape(-1)
            ansatz_entry_cost_payload: dict[str, Any] | None = None
            metric_matrix_for_payload: np.ndarray | None = None
            if int(theta_logical.size) != int(logical_count):
                return {}, _inactive_prune_schur_nomination_payload(
                    prune_cfg=phase1_prune_cfg,
                    selected_parameterization_mode=selected_parameterization_mode,
                    reason="theta_label_count_mismatch",
                    logical_parameter_count=int(theta_logical.size),
                    runtime_parameter_count=int(runtime_count),
                )
            mode_key = str(selected_parameterization_mode).strip().lower()
            coordinate_mode = "logical_shared"
            if mode_key == "logical_shared":
                model_post_indices = list(range(int(logical_count)))
                theta_model = np.asarray(theta_logical, dtype=float)
                gradient_model: np.ndarray
                if bool(phase1_prune_material_window_source_reuse_active):
                    if not bool(affine_trust_route_active):
                        raise RuntimeError(
                            "Material-window prune source reuse requires the "
                            "affine-deletion FS-trust nomination route."
                        )
                    unavailable_reason = str(
                        source_geometry_unavailable_reason or ""
                    ).strip()
                    if unavailable_reason:
                        if unavailable_reason != (
                            "geometry_expansion_no_coordinate_prediction"
                        ):
                            raise RuntimeError(
                                "Material-window prune nomination received an "
                                "unknown source-geometry unavailability reason."
                            )
                        if source_geometry_workspace is not None:
                            raise RuntimeError(
                                "Geometry-expansion prune hold cannot carry a "
                                "measured W-plus-candidate source workspace."
                            )
                        if affine_trust_state is None:
                            raise RuntimeError(
                                "Geometry-expansion prune hold requires the "
                                "branch-local affine trust state."
                            )
                        payload = {
                            **_inactive_prune_schur_nomination_payload(
                                prune_cfg=phase1_prune_cfg,
                                selected_parameterization_mode=(
                                    selected_parameterization_mode
                                ),
                                reason=(
                                    "no_eligible_old_coordinates_in_material_window"
                                ),
                                **inactive_base,
                            ),
                            "active": False,
                            "reason": (
                                "no_eligible_old_coordinates_in_material_window"
                            ),
                            "used_for_nomination": False,
                            "score_count": 0,
                            "stage": str(stage),
                            "coordinate_mode": (
                                "logical_material_window_geometry_expansion_hold"
                            ),
                            "source_geometry_unavailable_reason": (
                                unavailable_reason
                            ),
                            "affine_deletion_fs_trust_active": True,
                            "affine_deletion_fs_trust_state": (
                                _affine_prune_state_payload(
                                    affine_trust_state,
                                    source="geometry_expansion_hold",
                                )
                            ),
                            "affine_deletion_models": [],
                            "affine_deletion_model_count": 0,
                            "affine_deletion_feasible_count": 0,
                            "phase1_prune_source_geometry_reuse": None,
                            "cached_post_admission_geometry": {
                                "G": False,
                                "g": False,
                                "H": False,
                                "fixed_branch": (
                                    "geometry_expansion_no_coordinate_prediction"
                                ),
                                "reuse_policy": (
                                    "ineligible_hold_without_remeasurement_v1"
                                ),
                                "duplicate_measurement_performed": False,
                            },
                        }
                        return {}, payload
                    if not isinstance(source_geometry_workspace, Mapping):
                        raise RuntimeError(
                            "Material-window prune nomination lost the "
                            "authoritative Phase-III source workspace."
                        )
                    source_model = (
                        _normalize_sr_material_window_prune_source_geometry(
                            selector_summary=source_geometry_workspace,
                            post_admission_labels=labels_list,
                            post_admission_theta=theta_logical,
                        )
                    )
                    theta_model = np.asarray(source_model["theta"], dtype=float)
                    gradient_model = np.asarray(
                        source_model["gradient"], dtype=float
                    )
                    hessian = np.asarray(source_model["hessian"], dtype=float)
                    metric_matrix = np.asarray(
                        source_model["metric"], dtype=float
                    )
                    metric_matrix_for_payload = np.asarray(
                        metric_matrix, dtype=float
                    )
                    model_post_indices = [
                        int(value)
                        for value in source_model["model_post_indices"]
                    ]
                    source_geometry_reuse_receipt = dict(
                        source_model["receipt"]
                    )
                    coordinate_mode = "logical_material_window_source_reuse"
                else:
                    executor_use = (
                        executor_now
                        if executor_now is not None
                        else _build_compiled_executor(list(ops_now))
                    )
                    psi_current = _prepare_selected_state(
                        ops_now=list(ops_now),
                        theta_now=theta_runtime,
                        executor_now=executor_use,
                        parameter_layout_now=layout_now,
                    )
                    _energy_current, hpsi_current = energy_via_one_apply(
                        psi_current, h_compiled
                    )
                    _record_estimator_primitive(
                        state=np.asarray(psi_current, dtype=complex),
                        component="N_H_refit",
                        consumer_scope="prune_surrogate_anchor_energy",
                        primitive_kind="hamiltonian_expectation",
                        observable_or_formula_identity=(
                            "hamiltonian_expectation_v1"
                        ),
                    )
                    scaffold_context = (
                        phase2_novelty_oracle.prepare_scaffold_context(
                            selected_ops=list(ops_now),
                            theta=np.asarray(theta_logical, dtype=float),
                            psi_ref=psi_ref,
                            psi_state=np.asarray(psi_current, dtype=complex),
                            h_compiled=h_compiled,
                            hpsi_state=np.asarray(hpsi_current, dtype=complex),
                            refit_window_indices=list(
                                range(int(logical_count))
                            ),
                            pauli_action_cache=pauli_action_cache,
                            align_reconstructed_global_phase=bool(
                                not historical_paper_i_route_compat
                            ),
                        )
                    )
                    _record_scaffold_geometry_primitives(
                        state=np.asarray(psi_current, dtype=complex),
                        selected_ops_now=list(ops_now),
                        logical_theta_now=theta_logical,
                        refit_window_indices=list(range(int(logical_count))),
                        consumer_scope="prune_surrogate_scaffold_geometry",
                    )
                    for logical_index in range(int(logical_count)):
                        active_coordinate = _active_physical_tangent(
                            list(ops_now),
                            theta_logical,
                            logical_index,
                        )
                        _record_estimator_primitive(
                            state=np.asarray(psi_current, dtype=complex),
                            component="N_grad",
                            consumer_scope="prune_surrogate_active_gradient",
                            primitive_kind="coordinate_gradient",
                            observable_or_formula_identity=(
                                "coordinate_energy_gradient_v2"
                            ),
                            operand_identity=active_coordinate,
                        )
                    hessian = np.asarray(
                        scaffold_context.H_window_hessian, dtype=float
                    )
                    if hessian.shape != (
                        int(logical_count),
                        int(logical_count),
                    ):
                        payload = _inactive_prune_schur_nomination_payload(
                            prune_cfg=phase1_prune_cfg,
                            selected_parameterization_mode=(
                                selected_parameterization_mode
                            ),
                            reason="hessian_shape_mismatch",
                            **inactive_base,
                        )
                        payload["hessian_shape"] = [
                            int(x) for x in hessian.shape
                        ]
                        return {}, payload
                    gradient_model = np.asarray(
                        [
                            2.0
                            * float(
                                np.real(
                                    np.vdot(
                                        np.asarray(
                                            dpsi_vec, dtype=complex
                                        ),
                                        np.asarray(
                                            hpsi_current, dtype=complex
                                        ),
                                    )
                                )
                            )
                            for dpsi_vec in scaffold_context.dpsi_window
                        ],
                        dtype=float,
                    )
                    if geometry_metric_required:
                        metric_matrix = np.asarray(
                            scaffold_context.Q_window, dtype=float
                        )
                        metric_matrix_for_payload = np.asarray(
                            metric_matrix, dtype=float
                        )
                gradient_logical = np.asarray(gradient_model, dtype=float)
                if affine_trust_route_active:
                    if affine_trust_state is None:
                        raise RuntimeError(
                            "Full-logical FS trust pruning requires an explicit "
                            "branch-local trust state."
                        )
                    surrogate_scores = {}
                    affine_deletion_coordinates = list(
                        enumerate(model_post_indices)
                    )
                    if source_geometry_reuse_receipt is not None:
                        affine_deletion_coordinates = (
                            _sr_material_window_prune_deletion_coordinates(
                                model_post_indices=model_post_indices,
                                source_geometry_reuse_receipt=(
                                    source_geometry_reuse_receipt
                                ),
                            )
                        )
                    for model_index, post_index in affine_deletion_coordinates:
                        solve_result = solve_full_logical_affine_deletion_fs_trust(
                            theta=np.asarray(theta_model, dtype=float),
                            gradient=np.asarray(gradient_logical, dtype=float),
                            hessian=np.asarray(hessian, dtype=float),
                            metric=np.asarray(metric_matrix, dtype=float),
                            deletion_index=int(model_index),
                            trust_radius=float(affine_trust_state.radius),
                            metric_damping=float(affine_trust_state.metric_damping),
                        )
                        solve_payload = solve_result.as_dict()
                        solve_payload["model_coordinate_index"] = int(
                            model_index
                        )
                        solve_payload["post_admission_logical_index"] = int(
                            post_index
                        )
                        affine_solver_rows.append(dict(solve_payload))
                        if not bool(solve_result.feasible):
                            continue
                        predicted_change = float(
                            solve_result.predicted_energy_change
                        )
                        surrogate_scores[int(post_index)] = {
                            "index": int(post_index),
                            "model_coordinate_index": int(model_index),
                            "label": str(labels_list[int(post_index)]),
                            "score": float(predicted_change),
                            "unweighted_score": float(predicted_change),
                            "schur_min": float(predicted_change),
                            "bounded_score": float(predicted_change),
                            "entry_cost_denominator": 1.0,
                            "cost_weighting": PRUNE_METRIC_COST_WEIGHT_OFF,
                            "bounded_recovery_active": True,
                            "recovery_trust_radius": float(
                                affine_trust_state.radius
                            ),
                            "metric_mu": float(
                                affine_trust_state.metric_damping
                            ),
                            "metric_schur_solve_mode": (
                                PRUNE_METRIC_SCHUR_SOLVE_AFFINE_DELETION_GLOBAL_TRUST_V1
                            ),
                            "schur_rows": [dict(solve_payload)],
                            "schur_health": "resolved",
                            "schur_monotone": True,
                            "block_runtime_indices": [int(post_index)],
                            "schur_model": (
                                PRUNE_SCHUR_ROUTE_FULL_LOGICAL_FS_TRUST_DELETE_REFIT_V1
                            ),
                            "surrogate_authority": "nomination_only",
                            "used_for_acceptance": False,
                            "affine_deletion_model": dict(solve_payload),
                            "joint_step": [
                                float(value)
                                for value in solve_result.joint_step.tolist()
                            ],
                            "predicted_energy_change": float(
                                solve_result.predicted_energy_change
                            ),
                            "predicted_reduction": float(
                                solve_result.predicted_reduction
                            ),
                            "fubini_study_displacement_sq": float(
                                solve_result.fubini_study_displacement_sq
                            ),
                        }
                elif metric_route_active:
                    ansatz_entry_cost_payload = _ansatz_entry_cost_payload()
                    surrogate_scores = build_metric_regularized_prune_surrogate_scores(
                        theta=np.asarray(theta_logical, dtype=float),
                        labels=list(labels_list),
                        hessian=np.asarray(hessian, dtype=float),
                        metric=np.asarray(metric_matrix, dtype=float),
                        gradient=np.asarray(gradient_logical, dtype=float),
                        local_window_size=int(phase1_prune_cfg.local_window_size),
                        ridge=float(phase1_prune_cfg.surrogate_ridge),
                        metric_mu=float(phase1_prune_cfg.metric_schur_mu),
                        solve_mode=str(phase1_prune_cfg.metric_schur_solve_mode),
                        monotonicity_tol=float(phase1_prune_cfg.surrogate_monotonicity_tol),
                        recovery_trust_radius=float(
                            phase1_prune_cfg.surrogate_recovery_trust_radius
                        ),
                        entry_cost_denominators=ansatz_entry_cost_payload.get(
                            "denominators", []
                        ),
                    )
                else:
                    surrogate_scores = build_static_prune_surrogate_scores(
                        theta=np.asarray(theta_logical, dtype=float),
                        labels=list(labels_list),
                        hessian=np.asarray(hessian, dtype=float),
                        gradient=np.asarray(gradient_logical, dtype=float),
                        local_window_size=int(phase1_prune_cfg.local_window_size),
                        ridge=float(phase1_prune_cfg.surrogate_ridge),
                        monotonicity_tol=float(phase1_prune_cfg.surrogate_monotonicity_tol),
                        recovery_trust_radius=float(
                            phase1_prune_cfg.surrogate_recovery_trust_radius
                        ),
                    )
            elif mode_key == "per_pauli_term":
                if affine_trust_route_active:
                    raise RuntimeError(
                        "Full-logical FS trust pruning requires logical-shared "
                        "ansatz coordinates; runtime Pauli blocks are not a "
                        "permitted fallback."
                    )
                coordinate_mode = "runtime_block"
                executor_use = CompiledAnsatzExecutor(
                    list(ops_now),
                    coefficient_tolerance=1e-12,
                    ignore_identity=True,
                    sort_terms=True,
                    pauli_action_cache=pauli_action_cache,
                    parameterization_mode="per_pauli_term",
                    parameterization_layout=layout_now,
                )
                if int(theta_runtime.size) == int(runtime_count):
                    theta_exec = np.asarray(theta_runtime, dtype=float)
                elif int(theta_runtime.size) == int(logical_count):
                    theta_exec = np.asarray(
                        expand_legacy_logical_theta(theta_runtime, layout_now),
                        dtype=float,
                    )
                else:
                    return {}, _inactive_prune_schur_nomination_payload(
                        prune_cfg=phase1_prune_cfg,
                        selected_parameterization_mode=selected_parameterization_mode,
                        reason="runtime_theta_count_mismatch",
                        logical_parameter_count=int(logical_count),
                        runtime_parameter_count=int(runtime_count),
                    )
                psi_current, dpsi_window, d2psi_window = _propagate_runtime_prune_derivatives(
                    executor=executor_use,
                    theta=np.asarray(theta_exec, dtype=float),
                    psi_ref_state=np.asarray(psi_ref, dtype=complex),
                    active_indices=list(range(int(runtime_count))),
                )
                _energy_current, hpsi_current = energy_via_one_apply(psi_current, h_compiled)
                _record_estimator_primitive(
                    state=np.asarray(psi_current, dtype=complex),
                    component="N_H_refit",
                    consumer_scope="prune_surrogate_anchor_energy",
                    primitive_kind="hamiltonian_expectation",
                    observable_or_formula_identity="hamiltonian_expectation_v1",
                )
                hdpsi_window = [
                    apply_compiled_polynomial(np.asarray(dpsi_vec, dtype=complex), h_compiled)
                    for dpsi_vec in dpsi_window
                ]
                gradient_runtime = np.asarray(
                    [
                        2.0
                        * float(
                            np.real(
                                np.vdot(
                                    np.asarray(dpsi_vec, dtype=complex),
                                    np.asarray(hpsi_current, dtype=complex),
                                )
                            )
                        )
                        for dpsi_vec in dpsi_window
                    ],
                    dtype=float,
                )
                hessian = np.zeros((int(runtime_count), int(runtime_count)), dtype=float)
                for row_idx in range(int(runtime_count)):
                    for col_idx in range(int(runtime_count)):
                        hessian[row_idx, col_idx] = _energy_hessian_entry(
                            dpsi_left=dpsi_window[row_idx],
                            dpsi_right=dpsi_window[col_idx],
                            d2psi=d2psi_window[row_idx][col_idx],
                            hpsi_state=hpsi_current,
                            hdpsi_right=hdpsi_window[col_idx],
                        )
                hessian = 0.5 * (hessian + hessian.T)
                metric_runtime: np.ndarray | None = None
                if metric_route_active:
                    tangents_runtime = [
                        _horizontal_tangent(
                            np.asarray(psi_current, dtype=complex),
                            np.asarray(dpsi_vec, dtype=complex),
                        )
                        for dpsi_vec in dpsi_window
                    ]
                    metric_runtime = np.asarray(
                        _tangent_overlap_matrix(tangents_runtime),
                        dtype=float,
                    )
                    metric_matrix_for_payload = np.asarray(metric_runtime, dtype=float)
                    ansatz_entry_cost_payload = _ansatz_entry_cost_payload()
                all_runtime = list(range(int(runtime_count)))
                surrogate_scores = {}
                for idx, block in enumerate(layout_now.blocks):
                    block_indices = [
                        int(x)
                        for x in range(int(block.runtime_start), int(block.runtime_stop))
                    ]
                    if not block_indices:
                        continue
                    survivor_logical = [j for j in range(int(logical_count)) if int(j) != int(idx)]
                    local_window_raw = int(phase1_prune_cfg.local_window_size)
                    if local_window_raw <= 0:
                        local_logical = list(survivor_logical)
                    else:
                        omega = int(max(0, min(local_window_raw, len(survivor_logical))))
                        if omega <= 0:
                            local_logical = []
                        else:
                            start = max(
                                0,
                                min(int(idx) - (omega - 1) // 2, len(survivor_logical) - omega),
                            )
                            local_logical = survivor_logical[start : start + omega]
                    if not local_logical:
                        local_logical = []
                    local_runtime = runtime_indices_for_logical_indices(layout_now, local_logical)
                    survivor_runtime = [int(i) for i in all_runtime if int(i) not in set(block_indices)]
                    if metric_route_active and metric_runtime is not None:
                        ladder = metric_regularized_prune_schur_surrogate_ladder(
                            theta=np.asarray(theta_exec, dtype=float),
                            hessian=np.asarray(hessian, dtype=float),
                            metric=np.asarray(metric_runtime, dtype=float),
                            block_indices=[int(x) for x in block_indices],
                            windows=[[], [int(x) for x in local_runtime], [int(x) for x in survivor_runtime]],
                            ridge=float(phase1_prune_cfg.surrogate_ridge),
                            metric_mu=float(phase1_prune_cfg.metric_schur_mu),
                            solve_mode=str(phase1_prune_cfg.metric_schur_solve_mode),
                            monotonicity_tol=float(phase1_prune_cfg.surrogate_monotonicity_tol),
                            recovery_trust_radius=float(
                                phase1_prune_cfg.surrogate_recovery_trust_radius
                            ),
                            gradient=np.asarray(gradient_runtime, dtype=float),
                        )
                    else:
                        ladder = static_prune_schur_surrogate_ladder(
                            theta=np.asarray(theta_exec, dtype=float),
                            hessian=np.asarray(hessian, dtype=float),
                            block_indices=[int(x) for x in block_indices],
                            windows=[[], [int(x) for x in local_runtime], [int(x) for x in survivor_runtime]],
                            ridge=float(phase1_prune_cfg.surrogate_ridge),
                            monotonicity_tol=float(phase1_prune_cfg.surrogate_monotonicity_tol),
                            recovery_trust_radius=float(
                                phase1_prune_cfg.surrogate_recovery_trust_radius
                            ),
                            gradient=np.asarray(gradient_runtime, dtype=float),
                        )
                    values = [float(x) for x in ladder.get("values", [])]
                    bounded_values = [
                        float(x) for x in ladder.get("bounded_values", [])
                    ]
                    bounded_active = bool(ladder.get("bounded_recovery_active", False))
                    schur_score = float(min(values)) if values else float("inf")
                    bounded_score = (
                        float(min(bounded_values))
                        if bounded_values
                        else float(schur_score)
                    )
                    score = float(bounded_score if bounded_active else schur_score)
                    denominator = 1.0
                    if metric_route_active and ansatz_entry_cost_payload is not None:
                        denominators = ansatz_entry_cost_payload.get("denominators", [])
                        if int(idx) < len(denominators):
                            try:
                                denominator = float(denominators[int(idx)])
                            except (TypeError, ValueError):
                                denominator = 1.0
                        if not math.isfinite(denominator) or denominator <= 0.0:
                            denominator = 1.0
                        score = float(score / max(1.0, denominator))
                    surrogate_scores[int(idx)] = {
                        "index": int(idx),
                        "label": str(labels_list[int(idx)]),
                        "score": float(score),
                        "unweighted_score": float(bounded_score if bounded_active else schur_score),
                        "schur_min": float(schur_score),
                        "bounded_score": float(bounded_score),
                        "entry_cost_denominator": float(max(1.0, denominator)),
                        "cost_weighting": str(phase1_prune_cfg.metric_schur_cost_weighting)
                        if metric_route_active
                        else "none",
                        "bounded_recovery_active": bool(bounded_active),
                        "recovery_trust_radius": float(
                            ladder.get("recovery_trust_radius", 0.0)
                        ),
                        "metric_mu": float(ladder.get("metric_mu", 0.0)),
                        "metric_schur_solve_mode": str(
                            ladder.get("metric_schur_solve_mode", "")
                        ),
                        "schur_rows": list(ladder.get("rows", [])),
                        "schur_health": str(ladder.get("health", "unavailable")),
                        "schur_monotone": bool(ladder.get("monotone", False)),
                        "block_runtime_indices": [int(x) for x in block_indices],
                        "schur_model": str(
                            ladder.get(
                                "schur_model",
                                PRUNE_SCHUR_ROUTE_HESSIAN_COUPLING_V1,
                            )
                        ),
                        "surrogate_authority": str(
                            ladder.get(
                                "surrogate_authority",
                                "rank_window_diag_only",
                            )
                        ),
                        "used_for_acceptance": False,
                    }
            else:
                return {}, _inactive_prune_schur_nomination_payload(
                    prune_cfg=phase1_prune_cfg,
                    selected_parameterization_mode=selected_parameterization_mode,
                    reason="unsupported_parameterization_mode",
                    **inactive_base,
                )
            eig_min: float | None
            eig_max: float | None
            try:
                eigvals = np.linalg.eigvalsh(0.5 * (hessian + hessian.T))
                eig_min = float(np.min(eigvals)) if eigvals.size else None
                eig_max = float(np.max(eigvals)) if eigvals.size else None
            except Exception:
                eig_min = None
                eig_max = None
            payload = {
                **_inactive_prune_schur_nomination_payload(
                    prune_cfg=phase1_prune_cfg,
                    selected_parameterization_mode=selected_parameterization_mode,
                    reason="active",
                    **inactive_base,
                ),
                "active": bool(len(surrogate_scores) > 0),
                "reason": (
                    "ok"
                    if surrogate_scores
                    else (
                        "no_eligible_old_coordinates_in_material_window"
                        if source_geometry_reuse_receipt is not None
                        and not affine_solver_rows
                        else "no_scores"
                    )
                ),
                "used_for_nomination": bool(len(surrogate_scores) > 0),
                "score_count": int(len(surrogate_scores)),
                "stage": str(stage),
                "coordinate_mode": str(coordinate_mode),
                "hessian_shape": [int(x) for x in hessian.shape],
                "hessian_fro_norm": float(np.linalg.norm(hessian)),
                "hessian_trace": float(np.trace(hessian)),
                "hessian_eig_min": eig_min,
                "hessian_eig_max": eig_max,
                "schur_nomination_route": str(phase1_prune_cfg.schur_nomination_route),
                "metric_regularized_active": bool(metric_route_active),
                "affine_deletion_fs_trust_active": bool(
                    affine_trust_route_active
                ),
                "affine_deletion_fs_trust_state": (
                    None
                    if affine_trust_state is None
                    else _affine_prune_state_payload(
                        affine_trust_state,
                        source="nomination_model",
                    )
                ),
                "affine_deletion_models": [
                    dict(row) for row in affine_solver_rows
                ],
                "affine_deletion_model_count": int(len(affine_solver_rows)),
                "affine_deletion_feasible_count": int(
                    sum(
                        1
                        for row in affine_solver_rows
                        if bool(row.get("feasible", False))
                    )
                ),
                "metric_schur_mu": float(phase1_prune_cfg.metric_schur_mu),
                "metric_schur_solve_mode": str(phase1_prune_cfg.metric_schur_solve_mode),
                "metric_schur_cost_weighting": str(
                    phase1_prune_cfg.metric_schur_cost_weighting
                ),
                "phase1_prune_source_geometry_reuse": (
                    None
                    if source_geometry_reuse_receipt is None
                    else dict(source_geometry_reuse_receipt)
                ),
                "cached_post_admission_geometry": {
                    "G": bool(metric_matrix_for_payload is not None),
                    "g": True,
                    "H": True,
                    "fixed_branch": (
                        "pre_admission_material_window_source"
                        if source_geometry_reuse_receipt is not None
                        else "post_admission_refit"
                    ),
                    "reuse_policy": (
                        "authoritative_measured_W_plus_candidate_zero_query_v1"
                        if source_geometry_reuse_receipt is not None
                        else "compute_once_then_slice_per_candidate"
                    ),
                    "duplicate_measurement_performed": (
                        False
                        if source_geometry_reuse_receipt is not None
                        else None
                    ),
                },
                "metric_shape": (
                    []
                    if metric_matrix_for_payload is None
                    else [int(x) for x in metric_matrix_for_payload.shape]
                ),
                "metric_fro_norm": (
                    None
                    if metric_matrix_for_payload is None
                    else float(np.linalg.norm(metric_matrix_for_payload))
                ),
                "ansatz_entry_cost_denominator": (
                    None
                    if ansatz_entry_cost_payload is None
                    else {
                        "schema": str(ansatz_entry_cost_payload.get("schema", "")),
                        "scope": str(ansatz_entry_cost_payload.get("scope", "")),
                        "lambda_source": str(
                            ansatz_entry_cost_payload.get("lambda_source", "")
                        ),
                        "denominators": [
                            float(x)
                            for x in ansatz_entry_cost_payload.get("denominators", [])
                        ],
                    }
                ),
                "local_window_size": int(phase1_prune_cfg.local_window_size),
                "recovery_trust_radius": float(
                    phase1_prune_cfg.surrogate_recovery_trust_radius
                ),
                "window_policy": (
                    "full_survivor"
                    if int(phase1_prune_cfg.local_window_size) <= 0
                    else "local_plus_old_tail"
                ),
                "rows": _compact_prune_schur_rows(
                    surrogate_scores,
                    max_rows=max(
                        int(phase1_prune_cfg.max_candidates),
                        int(phase1_prune_cfg.min_candidates),
                    ),
                ),
            }
            return {int(k): dict(v) for k, v in surrogate_scores.items()}, payload
        except Exception as exc:
            if bool(affine_trust_route_active):
                raise RuntimeError(
                    "SR-SNAKE v4 full-logical FS trust prune model failed; "
                    "refusing to fall back to a historical nomination route. "
                    f"Cause: {type(exc).__name__}: {exc}"
                ) from exc
            payload = _inactive_prune_schur_nomination_payload(
                prune_cfg=phase1_prune_cfg,
                selected_parameterization_mode=selected_parameterization_mode,
                reason="surrogate_build_failed",
                **inactive_base,
            )
            payload["error_type"] = type(exc).__name__
            payload["error_message"] = str(exc)
            payload["stage"] = str(stage)
            return {}, payload

