    def _fallback_prune_metadata(*, label: str) -> ScaffoldCoordinateMetadata:
        return ScaffoldCoordinateMetadata(
            candidate_label=str(label),
            generator_id=None,
            admission_step=0,
            first_seen_step=0,
            selector_score=0.0,
            selector_burden=0.0,
            cooldown_remaining=0,
        )

    def _reconstruct_prune_first_seen_steps(history_rows: Sequence[Mapping[str, Any]]) -> dict[str, int]:
        out: dict[str, int] = {}
        for step_idx, row in enumerate(history_rows, start=1):
            labels_raw = row.get("selected_ops")
            labels = (
                [str(x) for x in labels_raw]
                if isinstance(labels_raw, Sequence) and not isinstance(labels_raw, (str, bytes))
                else [str(row.get("selected_op", ""))]
            )
            for label in labels:
                out.setdefault(str(label), int(step_idx))
        return out

    def _initialize_prune_metadata_state(
        *,
        labels_now: list[str],
        theta_logical_now: np.ndarray,
    ) -> tuple[list[ScaffoldCoordinateMetadata], dict[str, int]]:
        del theta_logical_now
        entries: list[ScaffoldCoordinateMetadata] = []
        first_seen_by_label = _reconstruct_prune_first_seen_steps(history)
        for step_idx, row in enumerate(history, start=1):
            if not isinstance(row, Mapping):
                continue
            labels_step_raw = row.get("selected_ops")
            labels_step = (
                [str(x) for x in labels_step_raw]
                if isinstance(labels_step_raw, Sequence) and not isinstance(labels_step_raw, (str, bytes))
                else [str(row.get("selected_op", ""))]
            )
            positions_step_raw = row.get("selected_positions")
            positions_step = (
                [int(x) for x in positions_step_raw]
                if isinstance(positions_step_raw, Sequence) and not isinstance(positions_step_raw, (str, bytes))
                else [int(row.get("selected_position", len(entries)))]
            )
            feature_rows_raw = row.get("selected_feature_rows")
            feature_rows = (
                list(feature_rows_raw)
                if isinstance(feature_rows_raw, Sequence) and not isinstance(feature_rows_raw, (str, bytes))
                else []
            )
            original_positions_seen: list[int] = []
            for item_idx, label_step in enumerate(labels_step):
                pos_orig = int(positions_step[item_idx]) if item_idx < len(positions_step) else int(len(entries))
                pos_eff = int(pos_orig + sum(1 for prev in original_positions_seen if int(prev) <= int(pos_orig)))
                feature_row = feature_rows[item_idx] if item_idx < len(feature_rows) else row
                feature_mapping = feature_row if isinstance(feature_row, Mapping) else row
                meta = ScaffoldCoordinateMetadata(
                    candidate_label=str(label_step),
                    generator_id=(
                        str(feature_mapping.get("generator_id"))
                        if feature_mapping.get("generator_id") is not None
                        else None
                    ),
                    admission_step=int(step_idx),
                    first_seen_step=int(first_seen_by_label.setdefault(str(label_step), int(step_idx))),
                    selector_score=float(_selector_score_value(feature_mapping)),
                    selector_burden=float(_selector_burden_value(feature_mapping)),
                    cooldown_remaining=0,
                )
                entries.insert(max(0, min(int(pos_eff), len(entries))), meta)
                original_positions_seen.append(int(pos_orig))
        aligned: list[ScaffoldCoordinateMetadata] = []
        cursor = 0
        for idx_now, label_now in enumerate(labels_now):
            match_idx = None
            for entry_idx in range(cursor, len(entries)):
                if str(entries[entry_idx].candidate_label) == str(label_now):
                    match_idx = int(entry_idx)
                    break
            base_meta = (
                entries[int(match_idx)]
                if match_idx is not None
                else _fallback_prune_metadata(
                    label=str(label_now),
                )
            )
            if match_idx is not None:
                cursor = int(match_idx + 1)
            aligned.append(
                ScaffoldCoordinateMetadata(
                    **{
                        **base_meta.__dict__,
                        "first_seen_step": int(first_seen_by_label.setdefault(str(label_now), int(base_meta.first_seen_step))),
                    }
                )
            )
        return aligned, first_seen_by_label

    def _refresh_prune_metadata(
        metadata_rows: Sequence[ScaffoldCoordinateMetadata],
    ) -> list[ScaffoldCoordinateMetadata]:
        return [
            ScaffoldCoordinateMetadata(**dict(meta.__dict__))
            for meta in metadata_rows
        ]

    def _transport_prune_metadata_after_admission(
        *,
        metadata_rows: Sequence[ScaffoldCoordinateMetadata],
        labels_added: Sequence[str],
        positions_added: Sequence[int],
        feature_rows_added: Sequence[Mapping[str, Any]],
        selector_step: int,
        first_seen_steps: Mapping[str, int],
    ) -> tuple[list[ScaffoldCoordinateMetadata], dict[str, int]]:
        out = [
            ScaffoldCoordinateMetadata(
                **{**meta.__dict__, "cooldown_remaining": int(max(0, meta.cooldown_remaining - 1))}
            )
            for meta in metadata_rows
        ]
        first_seen = {str(k): int(v) for k, v in first_seen_steps.items()}
        original_positions_seen: list[int] = []
        for item_idx, label in enumerate(labels_added):
            pos_orig = int(positions_added[item_idx]) if item_idx < len(positions_added) else int(len(out))
            pos_eff = int(pos_orig + sum(1 for prev in original_positions_seen if int(prev) <= int(pos_orig)))
            feature_mapping = (
                feature_rows_added[item_idx]
                if item_idx < len(feature_rows_added) and isinstance(feature_rows_added[item_idx], Mapping)
                else {}
            )
            first_seen_step = int(first_seen.setdefault(str(label), int(selector_step)))
            out.insert(
                max(0, min(int(pos_eff), len(out))),
                ScaffoldCoordinateMetadata(
                    candidate_label=str(label),
                    generator_id=(
                        str(feature_mapping.get("generator_id"))
                        if feature_mapping.get("generator_id") is not None
                        else None
                    ),
                    admission_step=int(selector_step),
                    first_seen_step=int(first_seen_step),
                    selector_score=float(_selector_score_value(feature_mapping)),
                    selector_burden=float(_selector_burden_value(feature_mapping)),
                    cooldown_remaining=0,
                ),
            )
            original_positions_seen.append(int(pos_orig))
        return out, first_seen

    def _prune_refit_window_indices_live(
        *,
        removal_index: int,
        metadata_rows: Sequence[ScaffoldCoordinateMetadata],
        n_plus: int,
    ) -> list[int]:
        n_after = int(max(0, n_plus - 1))
        if n_after <= 0:
            return []
        local_window_raw = int(phase1_prune_cfg.local_window_size)
        if local_window_raw <= 0:
            return list(range(n_after))
        omega_eff = int(max(1, min(local_window_raw, n_after)))
        local_start = int(max(0, min(int(removal_index) - (omega_eff - 1) // 2, n_after - omega_eff)))
        local_window = list(range(int(local_start), int(local_start + omega_eff)))
        nonlocal_indices = [idx for idx in range(n_after) if idx not in set(local_window)]
        oldest_count = int(math.ceil(float(phase1_prune_cfg.old_fraction) * float(len(nonlocal_indices))))
        oldest_count = int(max(0, min(oldest_count, len(nonlocal_indices))))
        oldest_tail = (
            sorted(
                nonlocal_indices,
                key=lambda idx: (
                    int(metadata_rows[idx].admission_step),
                    int(metadata_rows[idx].first_seen_step),
                    str(metadata_rows[idx].candidate_label),
                ),
            )[:oldest_count]
            if oldest_count > 0
            else []
        )
        return sorted({int(x) for x in [*local_window, *oldest_tail]})

    def _post_delete_to_original_index(*, post_idx: int, removal_index: int) -> int:
        idx = int(post_idx)
        remove = int(removal_index)
        return int(idx if idx < remove else idx + 1)

    def _guarded_prune_schur_warm_start(
        *,
        objective: Callable[[np.ndarray], float],
        incumbent_x0: np.ndarray,
        surrogate_scores: Mapping[int, Mapping[str, Any]],
        candidate_index: int,
        active_post_logical_indices: Sequence[int],
        stage: str,
        parameterization_mode: str,
    ) -> tuple[np.ndarray, dict[str, Any], int]:
        incumbent = np.asarray(incumbent_x0, dtype=float).reshape(-1).copy()
        active_post = [int(x) for x in active_post_logical_indices]
        payload: dict[str, Any] = {
            "schema": "static_adapt_schur_warm_start_v1",
            "stage": str(stage),
            "enabled": True,
            "attempted": True,
            "candidate_index": int(candidate_index),
            "active_logical_indices": [int(x) for x in active_post],
            "parameterization_mode": str(parameterization_mode),
        }
        if str(parameterization_mode).strip().lower() != "logical_shared":
            payload.update(
                {
                    "status": "unsupported",
                    "reason": "unsupported_parameterization_basis",
                    "fallback_to_incumbent": True,
                    "guard_objective_evals": 0,
                }
            )
            return incumbent.copy(), payload, 0
        row = surrogate_scores.get(int(candidate_index))
        if not isinstance(row, Mapping):
            payload.update(
                {
                    "status": "unavailable",
                    "reason": "missing_geometry",
                    "fallback_to_incumbent": True,
                    "guard_objective_evals": 0,
                }
            )
            return incumbent.copy(), payload, 0
        matched_row: Mapping[str, Any] | None = None
        matched_post_window: list[int] = []
        for rung_row_raw in row.get("schur_rows", []):
            if not isinstance(rung_row_raw, Mapping):
                continue
            survivor_pre = [
                int(x)
                for x in rung_row_raw.get(
                    "survivor_window_indices",
                    rung_row_raw.get("window_indices", []),
                )
            ]
            survivor_post = [
                int(x if int(x) < int(candidate_index) else int(x) - 1)
                for x in survivor_pre
                if int(x) != int(candidate_index)
            ]
            if survivor_post == active_post:
                matched_row = rung_row_raw
                matched_post_window = [int(x) for x in survivor_post]
                break
        if matched_row is None:
            payload.update(
                {
                    "status": "unsupported",
                    "reason": "unsupported_partial_active_window",
                    "fallback_to_incumbent": True,
                    "guard_objective_evals": 0,
                }
            )
            return incumbent.copy(), payload, 0
        reduced_position = {int(idx): int(k) for k, idx in enumerate(active_post)}
        if any(int(idx) not in reduced_position for idx in matched_post_window):
            payload.update(
                {
                    "status": "unsupported",
                    "reason": "unsupported_partial_active_window",
                    "fallback_to_incumbent": True,
                    "guard_objective_evals": 0,
                }
            )
            return incumbent.copy(), payload, 0
        survivor_positions = [int(reduced_position[int(idx)]) for idx in matched_post_window]
        g_survivor = matched_row.get("g_survivor")
        compensation_solve = None
        solve_source_hint = "full_block_gradient"
        metric_compensation_row = bool(
            str(matched_row.get("schur_model", "")) == PRUNE_SCHUR_ROUTE_METRIC_REGULARIZED_V1
            or str(matched_row.get("compensation_semantics", ""))
            == "metric_regularized_added_survivor_delta"
        )
        if bool(metric_compensation_row):
            compensation_solve = matched_row.get(
                "warm_start_compensation_solve",
                matched_row.get("compensation_solve", None),
            )
            solve_source_hint = str(
                matched_row.get("compensation_semantics", "metric_regularized_stored_compensation")
            )
            g_survivor = None
        elif bool(matched_row.get("bounded_recovery_clipped", False)) or g_survivor is None:
            compensation_solve = matched_row.get(
                "warm_start_compensation_solve",
                (
                    [-float(x) for x in matched_row.get("compensation_solve", [])]
                    if isinstance(matched_row.get("compensation_solve"), Sequence)
                    and not isinstance(matched_row.get("compensation_solve"), (str, bytes))
                    else None
                ),
            )
            solve_source_hint = str(
                matched_row.get("compensation_semantics", "stored_surrogate_compensation")
            )
        proposal, proposal_telemetry = propose_prune_schur_seed(
            canonical_deleted_x0=np.asarray(incumbent, dtype=float),
            survivor_reduced_positions=survivor_positions,
            theta_removed=matched_row.get("theta_removed", []),
            g_survivor=g_survivor,
            H_survivor_survivor=matched_row.get("H_survivor_survivor", []),
            H_survivor_removed=matched_row.get("H_survivor_removed", []),
            ridge_used=matched_row.get("ridge_used", phase1_prune_cfg.surrogate_ridge),
            compensation_solve=compensation_solve,
        )
        payload.update(dict(proposal_telemetry))
        payload.update(
            {
                "solve_source_hint": str(solve_source_hint),
                "survivor_post_logical_indices": [int(x) for x in matched_post_window],
                "mapped_reduced_positions": [int(x) for x in survivor_positions],
            }
        )
        if proposal is None:
            payload.update(
                {
                    "fallback_to_incumbent": True,
                    "guard_objective_evals": 0,
                }
            )
            return incumbent.copy(), payload, 0
        guard_result = select_guarded_seed(
            objective=objective,
            incumbent_x0=np.asarray(incumbent, dtype=float),
            proposals=[proposal],
            guard_abs_tol=float(schur_warm_start_policy.guard_abs_tol),
            guard_rel_tol=float(schur_warm_start_policy.guard_rel_tol),
        )
        guard_evals = int(guard_result.telemetry.get("guard_objective_evals", 0))
        payload.update(
            {
                "status": str(guard_result.status),
                "reason": str(guard_result.reason),
                "chosen_source": str(guard_result.chosen_source),
                "guard_objective_evals": int(guard_evals),
                "fallback_to_incumbent": bool(guard_result.status != "accepted"),
                "guard": dict(guard_result.telemetry),
            }
        )
        return np.asarray(guard_result.x0, dtype=float).copy(), payload, int(guard_evals)

    def _prune_compensator_sources_live(
        *,
        removal_index: int,
        metadata_rows_after: Sequence[ScaffoldCoordinateMetadata],
        n_plus: int,
    ) -> dict[str, Any]:
        n_after = int(max(0, n_plus - 1))
        if n_after <= 0:
            return {
                "correlated_post_indices": [],
                "correlated_original_indices": [],
                "age_post_indices": [],
                "age_original_indices": [],
                "legacy_union_post_indices": [],
                "correlated_source": "legacy_local_window_proxy_v1",
                "age_source": "legacy_old_fraction_tail_v1",
            }
        local_window_raw = int(phase1_prune_cfg.local_window_size)
        if local_window_raw <= 0:
            full_window = list(range(n_after))
            return {
                "correlated_post_indices": [int(x) for x in full_window],
                "correlated_original_indices": [
                    _post_delete_to_original_index(post_idx=int(x), removal_index=int(removal_index))
                    for x in full_window
                ],
                "age_post_indices": [],
                "age_original_indices": [],
                "legacy_union_post_indices": [int(x) for x in full_window],
                "correlated_source": "full_survivor_window_v1",
                "age_source": "disabled_for_full_survivor_window_v1",
            }
        omega_eff = int(max(1, min(local_window_raw, n_after)))
        local_start = int(max(0, min(int(removal_index) - (omega_eff - 1) // 2, n_after - omega_eff)))
        local_window = list(range(int(local_start), int(local_start + omega_eff)))
        local_set = {int(x) for x in local_window}
        nonlocal_indices = [idx for idx in range(n_after) if int(idx) not in local_set]
        oldest_count = int(math.ceil(float(phase1_prune_cfg.old_fraction) * float(len(nonlocal_indices))))
        oldest_count = int(max(0, min(oldest_count, len(nonlocal_indices))))
        oldest_tail = (
            sorted(
                nonlocal_indices,
                key=lambda idx: (
                    int(metadata_rows_after[idx].admission_step),
                    int(metadata_rows_after[idx].first_seen_step),
                    str(metadata_rows_after[idx].candidate_label),
                ),
            )[:oldest_count]
            if oldest_count > 0
            else []
        )
        correlated_post = sorted({int(x) for x in local_window})
        age_post = sorted({int(x) for x in oldest_tail})
        legacy_union_post = sorted({int(x) for x in [*correlated_post, *age_post]})
        return {
            "correlated_post_indices": [int(x) for x in correlated_post],
            "correlated_original_indices": [
                _post_delete_to_original_index(post_idx=int(x), removal_index=int(removal_index))
                for x in correlated_post
            ],
            "age_post_indices": [int(x) for x in age_post],
            "age_original_indices": [
                _post_delete_to_original_index(post_idx=int(x), removal_index=int(removal_index))
                for x in age_post
            ],
            "legacy_union_post_indices": [int(x) for x in legacy_union_post],
            "correlated_source": "legacy_local_window_proxy_v1",
            "age_source": "legacy_old_fraction_tail_v1",
        }

    def _serialize_typed_live_prune_plan(
        *,
        plan: Any,
        source_payload: Mapping[str, Any],
    ) -> dict[str, Any]:
        pools = plan.pools
        return {
            "candidate_index": int(plan.candidate_index),
            "candidate_label": str(plan.candidate_label),
            "rho_schedule": [float(x) for x in _TYPED_ALGEBRAIC_LIVE_PRUNE_RHO_SCHEDULE],
            "terminal_full": False,
            "correlated_source": str(source_payload.get("correlated_source", "legacy_local_window_proxy_v1")),
            "age_source": str(source_payload.get("age_source", "legacy_old_fraction_tail_v1")),
            "source_windows": {
                "correlated_post_indices": [int(x) for x in source_payload.get("correlated_post_indices", [])],
                "correlated_original_indices": [int(x) for x in source_payload.get("correlated_original_indices", [])],
                "age_post_indices": [int(x) for x in source_payload.get("age_post_indices", [])],
                "age_original_indices": [int(x) for x in source_payload.get("age_original_indices", [])],
                "legacy_union_post_indices": [int(x) for x in source_payload.get("legacy_union_post_indices", [])],
            },
            "pools": {
                "comm_indices": [int(x) for x in pools.comm_indices],
                "corr_indices": [int(x) for x in pools.corr_indices],
                "nc_indices": [int(x) for x in pools.nc_indices],
                "age_indices": [int(x) for x in pools.age_indices],
                "term_indices": [int(x) for x in pools.term_indices],
                "relation_summary": {str(k): int(v) for k, v in dict(pools.relation_summary).items()},
            },
            "rungs": [
                {
                    "rung_index": int(rung.rung_index),
                    "rung_kind": str(rung.rung_kind),
                    "active_logical_indices": [int(x) for x in rung.active_logical_indices],
                    "opened_pool_kinds": [str(x) for x in rung.opened_pool_kinds],
                    "recovery_class_if_accepted": (
                        None
                        if rung.recovery_class_if_accepted is None
                        else str(rung.recovery_class_if_accepted)
                    ),
                }
                for rung in plan.rungs
            ],
        }

    def _build_typed_live_prune_plan(
        *,
        candidate_index: int,
        labels_now: list[str],
        ops_now: list[AnsatzTerm],
        metadata_after: Sequence[ScaffoldCoordinateMetadata],
    ) -> tuple[Any, dict[str, Any]]:
        nonlocal commutation_metadata_index
        try:
            if commutation_metadata_index is None:
                commutation_metadata_index = build_exact_expansion_index(
                    pool=ops_now,
                    registry_by_label=pool_generator_registry,
                    require_exact=True,
                    allow_polynomial_source=True,
                )
            for op_ref in ops_now:
                ensure_exact_expansion_in_index(
                    commutation_metadata_index,
                    op_ref,
                    pool_generator_registry,
                    allow_polynomial_source=True,
                )
            source_payload = _prune_compensator_sources_live(
                removal_index=int(candidate_index),
                metadata_rows_after=metadata_after,
                n_plus=int(len(ops_now)),
            )
            plan = build_prune_ladder_plan(
                removal_index=int(candidate_index),
                labels=list(labels_now),
                pair_metadata=lambda lhs, rhs: commutation_metadata_index.pair(
                    str(lhs),
                    str(rhs),
                ),
                correlated_indices=[int(x) for x in source_payload.get("correlated_original_indices", [])],
                age_indices=[int(x) for x in source_payload.get("age_original_indices", [])],
                terminal_indices=[],
                rho_schedule=_TYPED_ALGEBRAIC_LIVE_PRUNE_RHO_SCHEDULE,
                terminal_full=False,
            )
            return plan, _serialize_typed_live_prune_plan(
                plan=plan,
                source_payload=source_payload,
            )
        except (AlgebraicMetadataError, PruneLadderError) as exc:
            raise RuntimeError(
                "Failed to build typed commutation prune ladder for "
                f"candidate {labels_now[int(candidate_index)]!r} at index {int(candidate_index)}."
            ) from exc

    phase1_prune_metadata_state: list[ScaffoldCoordinateMetadata] = []
    phase1_prune_first_seen_steps: dict[str, int] = {}
    prune_summary = _default_prune_summary(reason="pre_energy_init", energy=0.0)

    def _execute_live_mature_prune_pass(
        *,
        ops_now: list[AnsatzTerm],
        theta_now: np.ndarray,
        energy_now: float,
        optimizer_memory_now: dict[str, Any],
        metadata_rows: Sequence[ScaffoldCoordinateMetadata],
        first_seen_steps: Mapping[str, int],
        controller_snapshot: Mapping[str, Any] | None,
        selector_step: int,
        admitted_gain: float,
        history_rows: Sequence[Mapping[str, Any]] | None = None,
        source_geometry_workspace: Mapping[str, Any] | None = None,
        source_geometry_unavailable_reason: str | None = None,
    ) -> tuple[list[AnsatzTerm], np.ndarray, float, dict[str, Any], list[ScaffoldCoordinateMetadata], dict[str, int], dict[str, Any]]:
        summary = _default_prune_summary(reason="live_after_admission", energy=float(energy_now))
        if phase1_prune_cfg is None:
            return (
                list(ops_now),
                np.asarray(theta_now, dtype=float),
                float(energy_now),
                dict(optimizer_memory_now),
                [
                    ScaffoldCoordinateMetadata(**dict(row.__dict__))
                    for row in metadata_rows
                ],
                {str(key): int(value) for key, value in first_seen_steps.items()},
                summary,
            )
        history_source = (
            list(history_rows) if history_rows is not None else list(history)
        )
        affine_trust_state: AffineDeletionFSTrustState | None = None
        affine_trust_state_source: str | None = None
        if bool(phase1_prune_affine_trust_route_active):
            affine_trust_state, affine_trust_state_source = (
                _resolve_affine_prune_state(history_source)
            )
            state_payload = _affine_prune_state_payload(
                affine_trust_state,
                source=str(affine_trust_state_source),
            )
            summary["phase1_prune_trust_state_before"] = dict(state_payload)
            summary["phase1_prune_trust_state_after"] = dict(state_payload)
            summary["phase1_prune_trust_update"] = {
                "schema": "affine_deletion_fs_trust_state_update_v1",
                "status": "not_evaluated",
                "reason": "prune_pass_not_executed",
                "classical_quantum_query_charge": 0,
            }
            summary["phase1_prune_trial_receipt"] = None
            summary["phase1_prune_affine_deletion_model"] = None
        typed_live_prune_active = bool(
            str(phase1_prune_cfg.policy) == PRUNE_POLICY_RECOVERABILITY_LADDER_V1
        )
        summary["typed_prune_ladder_active"] = bool(typed_live_prune_active)
        summary["typed_prune_ladder_status"] = (
            "awaiting_live_permission" if bool(typed_live_prune_active) else "policy_inactive"
        )
        summary["typed_prune_ladder_gate"] = {
            "phase3_selector_policy": str(phase3_selector_policy_key),
            "phase1_prune_policy": str(phase1_prune_cfg.policy),
            "recoverability_prune_policy_active": bool(
                str(phase1_prune_cfg.policy) == PRUNE_POLICY_RECOVERABILITY_LADDER_V1
            ),
            "live_mode_enabled": bool(phase1_prune_live_mode),
            "active": bool(typed_live_prune_active),
        }
        if (not phase1_prune_live_mode) or int(len(ops_now)) <= 1:
            summary.update(
                evaluate_prune_permission(
                    policy=str(phase1_prune_cfg.policy),
                    mode_enabled=bool(phase1_prune_live_mode),
                    has_min_scaffold=bool(int(len(ops_now)) > 1),
                    stable_refit=True,
                    mature_open=False,
                    accepted_admission=False,
                    plateau=False,
                    checkpoint_due=False,
                    terminal=False,
                    snr_low_enough=False,
                    snr_adm=None,
                )
            )
            if bool(typed_live_prune_active):
                summary["typed_prune_ladder_status"] = (
                    "live_mode_disabled" if not phase1_prune_live_mode else "not_enough_coordinates"
                )
            return list(ops_now), np.asarray(theta_now, dtype=float), float(energy_now), dict(optimizer_memory_now), [ScaffoldCoordinateMetadata(**dict(x.__dict__)) for x in metadata_rows], {str(k): int(v) for k, v in first_seen_steps.items()}, summary

        snapshot = dict(controller_snapshot) if isinstance(controller_snapshot, Mapping) else {}
        runway_ratio = float(max(0.0, min(1.0, snapshot.get("runway_ratio", 1.0))))
        u_sat = float(max(0.0, min(1.0, 1.0 - runway_ratio)))
        phase_uncertainty = snapshot.get("phase_uncertainty", {})
        sigma_phase3 = float(phase_uncertainty.get("phase3", 0.0)) if isinstance(phase_uncertainty, Mapping) else 0.0
        recent_gains = [
            max(0.0, float(row.get("energy_before_opt", 0.0)) - float(row.get("energy_after_opt", 0.0)))
            for row in history_source[-4:]
            if isinstance(row, Mapping)
        ]
        gain_ewma_recent = 0.0
        for gain_value in recent_gains:
            gain_ewma_recent = (
                float(gain_value)
                if not math.isfinite(float(gain_ewma_recent)) or float(gain_ewma_recent) <= 0.0
                else float(0.5 * float(gain_ewma_recent) + 0.5 * float(gain_value))
            )
        gain_floor = float(max(float(phase1_stage_cfg.weak_drop_threshold), float(gain_ewma_recent), 1e-12))
        noise_scale = float((1.0 + max(0.0, sigma_phase3)) * gain_floor)
        snr_adm = float(max(0.0, admitted_gain) / max(noise_scale, 1e-12))
        checkpoint_due = bool(int(selector_step) % int(max(1, phase1_prune_checkpoint_period)) == 0)
        mature_open = bool(float(u_sat) >= float(phase1_prune_maturity_threshold))
        live_depth = int(len(ops_now))
        live_depth_open = bool(int(live_depth) >= int(phase1_prune_live_min_depth))
        snr_low_enough = bool(float(snr_adm) <= float(phase1_prune_snr_threshold))
        permission_telemetry = evaluate_prune_permission(
            policy=str(phase1_prune_cfg.policy),
            mode_enabled=bool(phase1_prune_live_mode),
            has_min_scaffold=bool(int(len(ops_now)) > 1),
            stable_refit=True,
            mature_open=bool(mature_open),
            accepted_admission=True,
            plateau=False,
            checkpoint_due=bool(checkpoint_due),
            terminal=False,
            snr_low_enough=bool(snr_low_enough),
            snr_adm=float(snr_adm),
        )
        permission_open = bool(permission_telemetry.get("permission_open", False))
        summary["runway_ratio"] = float(runway_ratio)
        summary["u_sat"] = float(u_sat)
        summary["mature_open"] = bool(mature_open)
        summary["live_depth"] = int(live_depth)
        summary["live_min_depth"] = int(phase1_prune_live_min_depth)
        summary["live_depth_open"] = bool(live_depth_open)
        summary["checkpoint_due"] = bool(checkpoint_due)
        summary["sigma_phase3"] = float(sigma_phase3)
        summary["gain_floor"] = float(gain_floor)
        summary["gain_ewma_recent"] = float(gain_ewma_recent)
        summary["snr_adm"] = float(snr_adm)
        summary["snr_threshold"] = float(phase1_prune_snr_threshold)
        summary["snr_low_enough"] = bool(snr_low_enough)
        summary.update(dict(permission_telemetry))
        if not bool(live_depth_open):
            summary["permission_open"] = False
            summary["permission_reason"] = "live_min_depth_not_reached"
            if bool(typed_live_prune_active):
                summary["typed_prune_ladder_status"] = "live_min_depth_not_reached"
            return list(ops_now), np.asarray(theta_now, dtype=float), float(energy_now), dict(optimizer_memory_now), [ScaffoldCoordinateMetadata(**dict(x.__dict__)) for x in metadata_rows], {str(k): int(v) for k, v in first_seen_steps.items()}, summary

        labels_now = [str(op.label) for op in ops_now]
        layout_now = _build_selected_layout(ops_now)
        theta_runtime_now = np.asarray(theta_now, dtype=float)
        theta_logical_now = np.asarray(_logical_theta_alias(theta_runtime_now, layout_now), dtype=float)
        metadata_live = _refresh_prune_metadata(
            [ScaffoldCoordinateMetadata(**dict(x.__dict__)) for x in metadata_rows],
        )
        summary["metadata"] = [dict(x.__dict__) for x in metadata_live]
        protected_indices: list[int] = []
        cooldown_blocked_indices: list[int] = []
        recoverability_eligible_indices: list[int] = []
        gate_rows: list[dict[str, Any]] = []
        for idx_meta, meta in enumerate(metadata_live):
            first_seen_age = int(max(0, int(selector_step) - int(meta.first_seen_step)))
            admission_age = int(max(0, int(selector_step) - int(meta.admission_step)))
            protected = bool(admission_age < int(phase1_prune_cfg.protect_steps))
            cooldown_blocked = bool(int(meta.cooldown_remaining) > 0)
            recoverability_eligible = bool((not protected) and (not cooldown_blocked))
            if protected:
                protected_indices.append(int(idx_meta))
            if cooldown_blocked:
                cooldown_blocked_indices.append(int(idx_meta))
            if recoverability_eligible:
                recoverability_eligible_indices.append(int(idx_meta))
            gate_rows.append(
                {
                    "index": int(idx_meta),
                    "label": str(meta.candidate_label),
                    "first_seen_age": int(first_seen_age),
                    "admission_age": int(admission_age),
                    "cooldown_remaining": int(meta.cooldown_remaining),
                    "selector_burden": float(meta.selector_burden),
                    "protected": bool(protected),
                    "cooldown_blocked": bool(cooldown_blocked),
                    "recoverability_eligible": bool(recoverability_eligible),
                }
            )
        summary["protect_steps"] = int(phase1_prune_cfg.protect_steps)
        summary["cooldown_steps"] = int(phase1_prune_cfg.cooldown_steps)
        summary["gate_rows"] = [dict(x) for x in gate_rows]
        summary["protected_indices"] = [int(x) for x in protected_indices]
        summary["cooldown_blocked_indices"] = [int(x) for x in cooldown_blocked_indices]
        summary["recoverability_eligible_indices"] = [int(x) for x in recoverability_eligible_indices]
        if not permission_open:
            if bool(typed_live_prune_active):
                summary["typed_prune_ladder_status"] = "permission_closed"
            return list(ops_now), theta_runtime_now, float(energy_now), dict(optimizer_memory_now), metadata_live, {str(k): int(v) for k, v in first_seen_steps.items()}, summary

        prune_proxy_benefit = [
            float(meta.selector_score) / float(1.0 + max(0.0, meta.selector_burden))
            if math.isfinite(float(meta.selector_score))
            else float("inf")
            for meta in metadata_live
        ]
        retained_reference_energy = float(energy_now + max(0.0, admitted_gain))
        max_regression_effective, _prune_tolerance = _attach_prune_tolerance(
            summary,
            sigma_e=(float(sigma_phase3) if math.isfinite(float(sigma_phase3)) and float(sigma_phase3) > 0.0 else None),
            delta_scr=float(max(float(gain_floor), float(phase1_prune_cfg.max_regression))),
            current_energy=float(energy_now),
        )
        schur_gate_threshold = _prune_schur_nomination_gate_threshold(
            prune_cfg=phase1_prune_cfg,
            max_regression_effective=float(max_regression_effective),
        )
        prune_schur_scores, prune_schur_payload = _build_prune_schur_nomination_scores(
            ops_now=list(ops_now),
            theta_now=np.asarray(theta_runtime_now, dtype=float),
            layout_now=layout_now,
            executor_now=None,
            labels_now=list(labels_now),
            stage="live_after_admission",
            affine_trust_state=affine_trust_state,
            source_geometry_workspace=source_geometry_workspace,
            source_geometry_unavailable_reason=(
                source_geometry_unavailable_reason
            ),
        )
        summary["schur_surrogate_nomination"] = dict(prune_schur_payload)
        source_reuse_receipt = prune_schur_payload.get(
            "phase1_prune_source_geometry_reuse"
        )
        if source_reuse_receipt is not None:
            if not isinstance(source_reuse_receipt, Mapping):
                raise RuntimeError(
                    "Prune source geometry reuse payload is malformed."
                )
            if estimator_call_ledger is None:
                raise RuntimeError(
                    "Prune source geometry reuse requires the strict estimator "
                    "ledger."
                )
            registered_summary = estimator_call_ledger.summary_for_primitive_ids(
                source_reuse_receipt.get("primitive_ids", ())
            )
            enriched_source_reuse = {
                **dict(source_reuse_receipt),
                "registered_shared_source_work": dict(registered_summary),
                "incremental_quantum_query_charge": 0,
                "duplicate_measurement_performed": False,
            }
            summary["phase1_prune_source_geometry_reuse"] = dict(
                enriched_source_reuse
            )
            summary["schur_surrogate_nomination"] = {
                **dict(prune_schur_payload),
                "phase1_prune_source_geometry_reuse": dict(
                    enriched_source_reuse
                ),
            }
        no_eligible_hold = (
            _sr_v4_no_eligible_material_window_prune_hold_receipt(
                route_active=bool(phase1_prune_affine_trust_route_active),
                nomination_payload=prune_schur_payload,
                trust_state=affine_trust_state,
            )
        )
        if no_eligible_hold is not None:
            summary["phase1_prune_no_feasible_model"] = dict(
                no_eligible_hold
            )
            summary["phase1_prune_trust_update"] = dict(
                no_eligible_hold["trust_update"]
            )
            summary["permission_reason"] = (
                "no_eligible_old_coordinates_in_material_window"
            )
            summary["candidate_count"] = 0
            summary["probe_indices"] = []
            summary["probe_labels"] = []
            summary["frozen_scores"] = []
            summary["frozen_probe_policy"] = (
                "disabled_no_eligible_old_coordinate_v1"
            )
            summary["recoverability_ladder_active"] = False
            summary["recoverability_rung_policy"] = (
                "not_entered_no_eligible_old_coordinate_v1"
            )
            summary["recoverability_ladder_rows"] = []
            summary["typed_prune_ladder_status"] = (
                "no_eligible_old_coordinate"
            )
            return (
                list(ops_now),
                np.asarray(theta_runtime_now, dtype=float),
                float(energy_now),
                dict(optimizer_memory_now),
                metadata_live,
                {str(k): int(v) for k, v in first_seen_steps.items()},
                summary,
            )
        no_feasible_hold = _sr_v4_all_infeasible_prune_hold_receipt(
            route_active=bool(phase1_prune_affine_trust_route_active),
            nomination_payload=prune_schur_payload,
            trust_state=affine_trust_state,
        )
        if no_feasible_hold is not None:
            summary["phase1_prune_no_feasible_model"] = dict(
                no_feasible_hold
            )
            summary["phase1_prune_trust_update"] = dict(
                no_feasible_hold["trust_update"]
            )
            summary["permission_reason"] = (
                "all_affine_deletion_models_infeasible"
            )
            summary["candidate_count"] = 0
            summary["probe_indices"] = []
            summary["probe_labels"] = []
            summary["frozen_scores"] = []
            summary["frozen_probe_policy"] = (
                "disabled_no_feasible_affine_deletion_model_v1"
            )
            summary["recoverability_ladder_active"] = False
            summary["recoverability_rung_policy"] = (
                "not_entered_no_feasible_affine_deletion_model_v1"
            )
            summary["recoverability_ladder_rows"] = []
            summary["typed_prune_ladder_status"] = (
                "no_feasible_affine_deletion_model"
            )
            return (
                list(ops_now),
                np.asarray(theta_runtime_now, dtype=float),
                float(energy_now),
                dict(optimizer_memory_now),
                metadata_live,
                {str(k): int(v) for k, v in first_seen_steps.items()},
                summary,
            )
        candidate_indices_pre_schur_gate = rank_prune_candidates(
            theta=np.asarray(theta_logical_now, dtype=float),
            labels=list(labels_now),
            marginal_proxy_benefit=list(prune_proxy_benefit),
            max_candidates=int(phase1_prune_cfg.max_candidates),
            min_candidates=int(phase1_prune_cfg.min_candidates),
            fraction_candidates=float(phase1_prune_cfg.fraction_candidates),
            selector_burden=[float(meta.selector_burden) for meta in metadata_live],
            admission_steps=[int(meta.admission_step) for meta in metadata_live],
            cooldown_remaining=[int(meta.cooldown_remaining) for meta in metadata_live],
            current_step=int(selector_step),
            protect_steps=int(phase1_prune_cfg.protect_steps),
            policy=str(phase1_prune_cfg.policy),
            surrogate_scores=prune_schur_scores if prune_schur_scores else None,
            surrogate_score_primary_only=bool(phase1_prune_metric_route_active),
        )
        candidate_indices = rank_prune_candidates(
            theta=np.asarray(theta_logical_now, dtype=float),
            labels=list(labels_now),
            marginal_proxy_benefit=list(prune_proxy_benefit),
            max_candidates=int(phase1_prune_cfg.max_candidates),
            min_candidates=int(phase1_prune_cfg.min_candidates),
            fraction_candidates=float(phase1_prune_cfg.fraction_candidates),
            selector_burden=[float(meta.selector_burden) for meta in metadata_live],
            admission_steps=[int(meta.admission_step) for meta in metadata_live],
            cooldown_remaining=[int(meta.cooldown_remaining) for meta in metadata_live],
            current_step=int(selector_step),
            protect_steps=int(phase1_prune_cfg.protect_steps),
            policy=str(phase1_prune_cfg.policy),
            surrogate_scores=prune_schur_scores if prune_schur_scores else None,
            surrogate_score_threshold=schur_gate_threshold,
            surrogate_candidate_cap=(
                int(phase1_prune_cfg.surrogate_exact_trial_cap)
                if schur_gate_threshold is not None
                else None
            ),
            surrogate_score_primary_only=bool(phase1_prune_metric_route_active),
        )
        _update_prune_schur_gate_payload(
            summary,
            prune_cfg=phase1_prune_cfg,
            threshold=schur_gate_threshold,
            pre_gate_candidate_count=int(len(candidate_indices_pre_schur_gate)),
            post_gate_candidate_count=int(len(candidate_indices)),
        )
        candidate_indices = _apply_prune_prefilter(
            candidate_indices=[int(x) for x in candidate_indices],
            labels_now=list(labels_now),
            summary=summary,
        )
        pre_guard_candidate_indices = [int(x) for x in candidate_indices]
        repeat_guard_blocked_labels = _accepted_live_prune_labels_from_history(history_source)
        (
            candidate_indices,
            repeat_label_blocked_rows,
            repeat_label_guard_payload,
        ) = _apply_repeat_live_prune_guard(
            candidate_indices=pre_guard_candidate_indices,
            labels_now=list(labels_now),
            blocked_labels=list(repeat_guard_blocked_labels),
            bypass_for_model_nominated_single_trial=bool(
                phase1_prune_affine_trust_route_active
            ),
        )
        repeat_label_blocked_indices = {
            int(row["index"]) for row in repeat_label_blocked_rows
        }
        for row in gate_rows:
            idx_gate = int(row.get("index", -1))
            blocked_by_repeat = bool(idx_gate in repeat_label_blocked_indices)
            row["repeat_label_blocked"] = bool(blocked_by_repeat)
            if blocked_by_repeat:
                row["repeat_label_guard_reason"] = "previous_live_prune_acceptance_same_label"
        summary["gate_rows"] = [dict(x) for x in gate_rows]
        summary["repeat_label_guard"] = dict(repeat_label_guard_payload)
        summary["candidate_count"] = int(len(candidate_indices))
        summary["probe_indices"] = [int(x) for x in candidate_indices]
        summary["probe_labels"] = [str(labels_now[int(i)]) for i in candidate_indices]
        summary.update(
            _prune_authority_telemetry(
                prune_cfg=phase1_prune_cfg,
                typed_compensator_active=bool(typed_live_prune_active),
            )
        )
        summary["candidate_nomination_sources"] = _prune_nomination_sources(
            prune_cfg=phase1_prune_cfg,
            indices=[int(x) for x in candidate_indices],
            labels_now=list(labels_now),
            typed_compensator_active=bool(typed_live_prune_active),
            lane_membership={
                "recoverability_broad_rank": (
                    set(int(x) for x in candidate_indices)
                    if str(phase1_prune_cfg.policy) == PRUNE_POLICY_RECOVERABILITY_LADDER_V1
                    else set()
                ),
                "schur_surrogate": set(int(x) for x in candidate_indices),
            },
        )
        if not candidate_indices:
            if bool(typed_live_prune_active):
                summary["typed_prune_ladder_status"] = "no_candidates"
            return list(ops_now), theta_runtime_now, float(energy_now), dict(optimizer_memory_now), metadata_live, {str(k): int(v) for k, v in first_seen_steps.items()}, summary

        def _ops_from_labels(labels_cur: Sequence[str]) -> list[AnsatzTerm]:
            buckets: dict[str, list[AnsatzTerm]] = {}
            for op_ref in ops_now:
                buckets.setdefault(str(op_ref.label), []).append(op_ref)
            rebuilt: list[AnsatzTerm] = []
            for lbl in labels_cur:
                bucket = buckets.get(str(lbl), [])
                if bucket:
                    rebuilt.append(bucket.pop(0))
            return rebuilt

        def _refit_given_ops_live(
            ops_refit: list[AnsatzTerm],
            theta0: np.ndarray,
            active_logical_indices: list[int] | None,
            optimizer_memory_in: dict[str, Any],
            prune_warm_start_candidate_index: int | None = None,
            prune_warm_start_stage: str = "prune_refit_live",
        ) -> tuple[np.ndarray, float, dict[str, Any]]:
            if len(ops_refit) == 0:
                return np.zeros(0, dtype=float), float(energy_now), dict(optimizer_memory_in)
            layout_refit = _build_selected_layout(ops_refit)
            executor_refit = _build_compiled_executor(ops_refit) if adapt_state_backend_key == "compiled" else None
            theta_full = np.asarray(theta0, dtype=float).reshape(-1)
            active_logical_refit = (
                list(range(int(layout_refit.logical_parameter_count)))
                if active_logical_indices is None
                else [int(i) for i in active_logical_indices]
            )
            def _obj_prune_live(x: np.ndarray) -> float:
                return _evaluate_selected_energy_objective(
                    ops_now=ops_refit,
                    theta_now=np.asarray(x, dtype=float),
                    executor_now=executor_refit,
                    parameter_layout_now=layout_refit,
                    objective_stage="prune_refit_live",
                    depth_marker=int(selector_step),
            )
            if not active_logical_refit:
                energy_refit = float(_obj_prune_live(theta_full))
                summary["nfev_phase1_prune_delete_refit"] = int(
                    summary.get("nfev_phase1_prune_delete_refit", 0)
                ) + 1
                return (
                    np.asarray(theta_full, dtype=float),
                    energy_refit,
                    dict(optimizer_memory_in),
                )
            if bool(phase1_prune_affine_trust_route_active):
                (
                    prune_optimizer_chart,
                    _accepted_prune_indices,
                    prune_refit_invocation,
                ) = _make_accepted_refit_optimizer_chart(
                    ops_now=list(ops_refit),
                    theta_now=theta_full,
                    layout_now=layout_refit,
                    executor_now=executor_refit,
                    selector_active_logical_indices=active_logical_refit,
                    objective=_obj_prune_live,
                    objective_stage="affine_deletion_full_survivor_refit",
                )
                summary["phase1_prune_delete_refit_chart"] = dict(
                    prune_refit_invocation
                )
            else:
                prune_optimizer_chart = _make_selected_optimizer_chart(
                    theta_now=theta_full,
                    layout_now=layout_refit,
                    active_logical_indices=active_logical_refit,
                    objective=_obj_prune_live,
                )
            _obj_reduced = prune_optimizer_chart.objective
            opt_x0 = prune_optimizer_chart.x0
            active_runtime_indices = list(
                prune_optimizer_chart.active_runtime_indices
            )
            if bool(schur_warm_start_policy.prune_enabled) and prune_warm_start_candidate_index is not None:
                active_post_for_warm = (
                    [int(x) for x in active_logical_indices]
                    if active_logical_indices is not None
                    else list(range(int(len(ops_refit))))
                )
                opt_x0, prune_ws_payload, _prune_ws_nfev = _guarded_prune_schur_warm_start(
                    objective=_obj_reduced,
                    incumbent_x0=np.asarray(opt_x0, dtype=float),
                    surrogate_scores=prune_schur_scores,
                    candidate_index=int(prune_warm_start_candidate_index),
                    active_post_logical_indices=active_post_for_warm,
                    stage=str(prune_warm_start_stage),
                    parameterization_mode=str(
                        prune_optimizer_chart.coordinate_mode
                    ),
                )
                summary["nfev_schur_prune_warm_start_guard"] = int(
                    summary.get("nfev_schur_prune_warm_start_guard", 0)
                ) + int(_prune_ws_nfev)
                summary.setdefault("schur_prune_warm_start_trials", []).append(dict(prune_ws_payload))
            
            if adapt_inner_optimizer_key in _STOCHASTIC_ADAPT_INNER_OPTIMIZERS:
                refit_memory = None
                if phase2_enabled and adapt_inner_optimizer_key == "SPSA":
                    refit_memory = phase2_memory_adapter.select_active(
                        optimizer_memory_in,
                        active_indices=list(active_runtime_indices),
                        source="adapt.live_prune_refit.active_subset",
                    )
                fidelity_reduced = None
                if adapt_inner_optimizer_key == "QNSPSA":
                    fidelity_reduced = _state_fidelity_for_reduced_params(
                        ops_now=ops_refit,
                        theta_full=theta_full,
                        active_runtime_indices=active_runtime_indices,
                        executor_now=executor_refit,
                        parameter_layout_now=layout_refit,
                    )
                res = adapt_optimizer_dispatch.run_stochastic(
                    fun=_obj_reduced,
                    x0=opt_x0,
                    fidelity=fidelity_reduced,
                    maxiter_value=int(max(25, min(int(maxiter), 120))),
                    seed_value=int(seed) + 800000 + int(len(ops_refit)),
                    memory=(dict(refit_memory) if isinstance(refit_memory, Mapping) else None),
                    precondition_mode=("diag_rms_grad" if phase2_enabled else "none"),
                )
                summary["nfev_phase1_prune_delete_refit"] = int(
                    summary.get("nfev_phase1_prune_delete_refit", 0)
                ) + int(getattr(res, "nfev", 0) or 0)
                theta_out = np.asarray(
                    prune_optimizer_chart.lift_to_runtime(res.x), dtype=float
                )
                optimizer_out = dict(optimizer_memory_in)
                if phase2_enabled:
                    if adapt_inner_optimizer_key == "SPSA":
                        optimizer_out = phase2_memory_adapter.merge_active(
                            optimizer_memory_in,
                            active_indices=list(active_runtime_indices),
                            active_state=phase2_memory_adapter.from_result(
                                res,
                                method=str(adapt_inner_optimizer_key),
                                parameter_count=int(len(active_runtime_indices)),
                                source="adapt.live_prune_refit.result",
                            ),
                            source="adapt.live_prune_refit.merge",
                        )
                    else:
                        optimizer_out = phase2_memory_adapter.unavailable(
                            method=str(adapt_inner_optimizer_key),
                            parameter_count=int(theta_out.size),
                            reason="qnspsa_memory_reuse_disabled_in_slice",
                        )
                return theta_out, float(res.fun), optimizer_out
            rotosolve_executor_refit = executor_refit if executor_refit is not None else _build_compiled_executor(ops_refit)
            rotosolve_period, rotosolve_shift = _rotosolve_stencil_for_executor(
                rotosolve_executor_refit,
                active_indices=active_runtime_indices,
            )
            res = adapt_optimizer_dispatch.run_deterministic(
                method_key=str(adapt_inner_optimizer_key),
                objective=_obj_reduced,
                x0=opt_x0,
                maxiter_value=int(max(25, min(int(maxiter), 120))),
                context_label="live prune refit",
                rotosolve_period=rotosolve_period,
                rotosolve_shift=rotosolve_shift,
            )
            summary["nfev_phase1_prune_delete_refit"] = int(
                summary.get("nfev_phase1_prune_delete_refit", 0)
            ) + int(getattr(res, "nfev", 0) or 0)
            theta_out = np.asarray(
                prune_optimizer_chart.lift_to_runtime(res.x), dtype=float
            )
            return theta_out, float(res.fun), dict(optimizer_memory_in)

        def _frozen_ablation_energy_live(idx_remove: int) -> tuple[float, np.ndarray]:
            runtime_remove_indices = runtime_indices_for_logical_indices(layout_now, [int(idx_remove)])
            ops_trial = list(ops_now)
            del ops_trial[int(idx_remove)]
            theta_trial0 = np.delete(theta_runtime_now, runtime_remove_indices)
            executor_trial = _build_compiled_executor(ops_trial) if adapt_state_backend_key == "compiled" and ops_trial else None
            energy_trial = _evaluate_selected_energy_objective(
                ops_now=ops_trial,
                theta_now=np.asarray(theta_trial0, dtype=float),
                executor_now=executor_trial,
                parameter_layout_now=_build_selected_layout(ops_trial),
                objective_stage="prune_frozen_live",
                depth_marker=int(selector_step),
            )
            summary["nfev_phase1_prune_frozen_energy_probes"] = int(
                summary.get(
                    "nfev_phase1_prune_frozen_energy_probes", 0
                )
            ) + 1
            return float(energy_trial), np.asarray(theta_trial0, dtype=float)

        if bool(phase1_prune_affine_trust_route_active):
            if affine_trust_state is None:
                raise RuntimeError(
                    "SR-SNAKE v4 reached live pruning without branch-local "
                    "affine-deletion trust state."
                )
            if int(len(candidate_indices)) != 1:
                raise RuntimeError(
                    "SR-SNAKE v4 requires exactly one model-nominated deletion "
                    "before the measured delete/refit trial."
                )
            selected_index = int(candidate_indices[0])
            selected_label = str(labels_now[selected_index])
            selected_model_row = prune_schur_scores.get(selected_index)
            if not isinstance(selected_model_row, Mapping):
                raise RuntimeError(
                    "SR-SNAKE v4 deletion nomination lacks its full-logical "
                    "affine-deletion response receipt."
                )
            selected_model = selected_model_row.get("affine_deletion_model")
            if not isinstance(selected_model, Mapping):
                raise RuntimeError(
                    "SR-SNAKE v4 deletion nomination lost the solver payload."
                )
            summary["phase1_prune_affine_deletion_model"] = dict(
                selected_model
            )
            summary["frozen_scores"] = []
            summary["frozen_probe_policy"] = (
                "disabled_model_nomination_single_exact_trial_v1"
            )
            summary["selected_index"] = int(selected_index)
            summary["selected_label"] = str(selected_label)
            trial_id = (
                f"sr-v4-prune:round={int(selector_step)}:"
                f"index={int(selected_index)}:label={selected_label}"
            )
            estimator_trial_branch_id = _sr_v4_prune_trial_branch_id(
                selector_step=int(selector_step),
                candidate_index=int(selected_index),
                candidate_label=str(selected_label),
                parent_branch_id=getattr(
                    estimator_call_context,
                    "branch_id",
                    None,
                ),
            )

            def _eval_affine_deletion_live(
                idx_remove: int,
                theta_cur: np.ndarray,
                labels_cur: list[str],
                active_logical_indices: list[int] | None = None,
                rung_kind: str = "full_survivor_refit",
            ) -> tuple[float, np.ndarray]:
                ops_current = _ops_from_labels(labels_cur)
                layout_current = _build_selected_layout(ops_current)
                runtime_remove_indices = runtime_indices_for_logical_indices(
                    layout_current,
                    [int(idx_remove)],
                )
                ops_trial = list(ops_current)
                del ops_trial[int(idx_remove)]
                theta_trial0 = np.delete(
                    np.asarray(theta_cur, dtype=float),
                    runtime_remove_indices,
                )
                full_survivor_indices = list(range(int(len(ops_trial))))
                previous_branch_present = hasattr(
                    estimator_call_context,
                    "branch_id",
                )
                previous_branch_id = getattr(
                    estimator_call_context,
                    "branch_id",
                    None,
                )
                estimator_call_context.branch_id = str(
                    estimator_trial_branch_id
                )
                try:
                    theta_trial_opt, energy_trial, _optimizer_unused = (
                        _refit_given_ops_live(
                            ops_trial,
                            theta_trial0,
                            full_survivor_indices,
                            copy.deepcopy(optimizer_memory_now),
                            prune_warm_start_candidate_index=int(idx_remove),
                            prune_warm_start_stage=f"live_{str(rung_kind)}",
                        )
                    )
                finally:
                    if previous_branch_present:
                        estimator_call_context.branch_id = previous_branch_id
                    else:
                        delattr(estimator_call_context, "branch_id")
                return float(energy_trial), np.asarray(
                    theta_trial_opt,
                    dtype=float,
                )

            retained_reference_energy = float(
                energy_now + max(0.0, admitted_gain)
            )
            keep_branch_theta_snapshot = np.asarray(
                theta_runtime_now, dtype=float
            ).copy()
            keep_branch_labels_snapshot = tuple(str(value) for value in labels_now)
            keep_branch_energy_snapshot = float(energy_now)
            survivor_indices = list(range(max(0, int(len(labels_now)) - 1)))
            (
                theta_pruned,
                labels_pruned,
                prune_decisions,
                energy_after_prune,
                ladder_rows,
            ) = recoverability_prune_ladder(
                theta=np.asarray(theta_runtime_now, dtype=float),
                labels=list(labels_now),
                candidate_indices=[int(selected_index)],
                rung_windows_by_index={
                    int(selected_index): [
                        ("full_survivor_refit", survivor_indices)
                    ]
                },
                eval_with_removal_window=_eval_affine_deletion_live,
                energy_before=float(energy_now),
                max_regression=float(max_regression_effective),
                retained_reference_energy=float(retained_reference_energy),
                admitted_gain=float(max(0.0, admitted_gain)),
                retained_gain_ratio=float(phase1_prune_cfg.retained_gain_ratio),
                retained_gain_activation=float(
                    max(
                        float(phase1_prune_cfg.max_regression),
                        float(gain_floor),
                        1.0e-12,
                    )
                ),
                curvature_guard_mode="off",
                curvature_guard_context={
                    "compression_mode": False,
                    "terminal_full": False,
                },
                max_trial_evaluations=1,
            )
            if len(prune_decisions) != 1:
                raise RuntimeError(
                    "SR-SNAKE v4 did not produce exactly one measured "
                    "delete/refit decision."
                )
            keep_branch_intact = bool(
                tuple(str(value) for value in labels_now)
                == keep_branch_labels_snapshot
                and np.array_equal(
                    np.asarray(theta_runtime_now, dtype=float),
                    keep_branch_theta_snapshot,
                    equal_nan=True,
                )
                and float(energy_now) == keep_branch_energy_snapshot
            )
            if not keep_branch_intact:
                raise RuntimeError(
                    "Keep-versus-prune verification mutated the surviving "
                    "branch before its measured sibling was classified."
                )
            decision = prune_decisions[0]
            accepted_count = int(bool(decision.accepted))
            delete_refit_nfev = int(
                summary.get("nfev_phase1_prune_delete_refit", 0) or 0
            )
            prune_guard_nfev = int(
                summary.get("nfev_schur_prune_warm_start_guard", 0) or 0
            )
            trial_unique_summary = (
                estimator_call_ledger.summary(
                    branch_ids=[str(estimator_trial_branch_id)],
                    include_unbranched=False,
                )
                if estimator_call_ledger is not None
                else None
            )
            trial_occurrence_summary = (
                estimator_call_ledger.occurrence_summary(
                    branch_ids=[str(estimator_trial_branch_id)],
                    include_unbranched=False,
                )
                if estimator_call_ledger is not None
                else None
            )
            trial_h_occurrences = (
                None
                if trial_occurrence_summary is None
                else int(trial_occurrence_summary.get("N_H_refit", 0) or 0)
            )
            expected_trial_h_occurrences = int(
                delete_refit_nfev + prune_guard_nfev
            )
            if (
                trial_h_occurrences is not None
                and int(trial_h_occurrences)
                != int(expected_trial_h_occurrences)
            ):
                raise RuntimeError(
                    "SR-SNAKE v4 exact prune Hamiltonian occurrences do not "
                    "reconcile with delete/refit and guard nfev: "
                    f"occurrences={int(trial_h_occurrences)}, "
                    f"expected={int(expected_trial_h_occurrences)}."
                )
            summary["phase1_prune_exact_refit_work_accounting"] = {
                "schema": "sr_v4_prune_exact_refit_work_accounting_v1",
                "classification": (
                    "committed_prune"
                    if bool(decision.accepted)
                    else "discarded_prune"
                ),
                "nfev": int(delete_refit_nfev),
                "committed_prune_nfev": (
                    int(delete_refit_nfev) if bool(decision.accepted) else 0
                ),
                "discarded_prune_nfev": (
                    0 if bool(decision.accepted) else int(delete_refit_nfev)
                ),
                "included_in_total_nfev": True,
                "included_in_total_estimator_ledger": True,
                "estimator_trial_branch_id": str(
                    estimator_trial_branch_id
                ),
                "included_in_winning_lineage": bool(decision.accepted),
                "included_in_discarded_prune_accounting": bool(
                    not decision.accepted
                ),
                "separate_estimator_discarded_prune_bucket_available": bool(
                    estimator_call_ledger is not None
                ),
                "trial_unique_primitive_summary": (
                    None
                    if trial_unique_summary is None
                    else dict(trial_unique_summary)
                ),
                "trial_occurrence_summary": (
                    None
                    if trial_occurrence_summary is None
                    else dict(trial_occurrence_summary)
                ),
                "hamiltonian_occurrence_reconciliation": {
                    "delete_refit_nfev": int(delete_refit_nfev),
                    "guard_nfev": int(prune_guard_nfev),
                    "expected_N_H_refit_occurrences": int(
                        expected_trial_h_occurrences
                    ),
                    "recorded_N_H_refit_occurrences": trial_h_occurrences,
                    "closed": (
                        None
                        if trial_h_occurrences is None
                        else bool(
                            int(trial_h_occurrences)
                            == int(expected_trial_h_occurrences)
                        )
                    ),
                },
                "limitation": None,
            }
            summary["minimal_keep_prune_verification_beam"] = {
                "schema": "minimal_keep_prune_verification_beam_v1",
                "execution_semantics": (
                    "logical_parallel_immutable_keep_and_one_measured_"
                    "delete_refit_sibling_v1"
                ),
                "historical_admission_beam_used": False,
                "keep_branch": {
                    "measurement_work": 0,
                    "classical_snapshot_only": True,
                    "ordered_labels": list(keep_branch_labels_snapshot),
                    "theta_fingerprint": _candidate_record_array_fingerprint(
                        keep_branch_theta_snapshot
                    ),
                    "energy": float(keep_branch_energy_snapshot),
                    "intact_before_decision": True,
                    "destructively_mutated_then_restored": False,
                },
                "prune_sibling": {
                    "estimator_trial_branch_id": str(
                        estimator_trial_branch_id
                    ),
                    "removed_index": int(selected_index),
                    "removed_label": str(selected_label),
                    "delete_and_refit_measured": True,
                    "measurement_work_is_real": True,
                },
                "winner": (
                    "prune_sibling" if bool(decision.accepted) else "keep_branch"
                ),
                "rejected_sibling_discarded_without_survivor_restore": True,
                "rollback_classical_query_charge": 0,
            }
            trial_receipt = {
                "schema": AFFINE_DELETION_FS_TRUST_TRIAL_RECEIPT_V1,
                "trial_id": str(trial_id),
                "prediction_trial_id": str(trial_id),
                "realization_trial_id": str(trial_id),
                "prediction_complete": True,
                "realization_complete": True,
                "energy_receipt_complete": True,
                "predicted_energy_change": float(
                    selected_model_row["predicted_energy_change"]
                ),
                "realized_energy_change": float(
                    decision.energy_after - decision.energy_before
                ),
                "energy_comparison_width": float(
                    max(0.0, max_regression_effective)
                ),
                "measured_delete_refit_is_acceptance_authority": True,
                "endpoint_overlap_measured": False,
                "added_endpoint_overlap_query_count": 0,
                "estimator_trial_branch_id": str(
                    estimator_trial_branch_id
                ),
                "estimator_trial_classification": (
                    "committed_prune"
                    if bool(decision.accepted)
                    else "discarded_prune"
                ),
            }
            state_after, trust_update = update_affine_deletion_fs_trust_state(
                affine_trust_state,
                contract_radius=bool(
                    phase1_prune_trust_update_policy_key
                    == "modeled_local_fs_conservative_v1"
                    and not bool(decision.accepted)
                ),
                trial_receipt=(
                    trial_receipt
                    if phase1_prune_metric_mu_update_policy_key
                    == "same_trial_underprediction_monotone_v1"
                    else None
                ),
            )
            summary["phase1_prune_trial_receipt"] = dict(trial_receipt)
            summary["phase1_prune_trust_update"] = dict(trust_update)
            summary["phase1_prune_trust_state_after"] = (
                _affine_prune_state_payload(
                    state_after,
                    source="same_round_measured_delete_refit_update",
                )
            )
            summary["recoverability_ladder_active"] = False
            summary["recoverability_rung_policy"] = (
                "single_full_survivor_measured_delete_refit_v1"
            )
            summary["recoverability_ladder_rows"] = [
                dict(row) for row in ladder_rows
            ]
            summary["executed"] = True
            summary["accepted_count"] = int(accepted_count)
            summary["energy_after_prune"] = float(energy_after_prune)
            summary["energy_after_post_refit"] = float(energy_after_prune)
            summary["decisions"] = [dict(decision.__dict__)]
            summary["trial"] = dict(
                MaturePruneTrial(
                    selector_step=int(selector_step),
                    gate_open=bool(summary.get("permission_open", False)),
                    probe_indices=[int(selected_index)],
                    selected_index=int(selected_index),
                    selected_label=str(selected_label),
                    frozen_regression=None,
                    refit_energy=float(decision.energy_after),
                    retained_gain=(
                        None
                        if decision.retained_gain is None
                        else float(decision.retained_gain)
                    ),
                    accepted=bool(decision.accepted),
                    rollback_reason=(
                        None if bool(decision.accepted) else str(decision.reason)
                    ),
                ).__dict__
            )
            summary["rollback_snapshot_restored"] = False
            summary["rollback_mutation_scope"] = (
                "committed_prune" if bool(decision.accepted) else "none"
            )
            summary["optimizer_state_restored"] = False
            summary["candidate_cooldown_applied"] = False

            metadata_out = [
                ScaffoldCoordinateMetadata(**dict(item.__dict__))
                for item in metadata_live
            ]
            first_seen_out = {
                str(key): int(value) for key, value in first_seen_steps.items()
            }
            optimizer_out = dict(optimizer_memory_now)
            if bool(decision.accepted):
                accepted_remove_indices = [int(decision.index)]
                accepted_runtime_remove_indices = (
                    runtime_indices_for_logical_indices(
                        layout_now,
                        accepted_remove_indices,
                    )
                )
                if phase2_enabled:
                    optimizer_out = phase2_memory_adapter.remap_remove(
                        optimizer_out,
                        indices=list(accepted_runtime_remove_indices),
                    )
                label_to_ops: dict[str, list[AnsatzTerm]] = {}
                for op in ops_now:
                    label_to_ops.setdefault(str(op.label), []).append(op)
                rebuilt_ops: list[AnsatzTerm] = []
                for label in labels_pruned:
                    bucket = label_to_ops.get(str(label), [])
                    if bucket:
                        rebuilt_ops.append(bucket.pop(0))
                metadata_out = [
                    item
                    for item_index, item in enumerate(metadata_out)
                    if int(item_index) not in set(accepted_remove_indices)
                ]
                return (
                    rebuilt_ops,
                    np.asarray(theta_pruned, dtype=float),
                    float(energy_after_prune),
                    optimizer_out,
                    metadata_out,
                    first_seen_out,
                    summary,
                )
            return (
                list(ops_now),
                np.asarray(theta_runtime_now, dtype=float),
                float(energy_now),
                optimizer_out,
                metadata_out,
                first_seen_out,
                summary,
            )

        best_candidate_index = None
        best_candidate_label = None
        best_trial_window_logical: list[int] = []
        best_frozen_score = float("inf")
        best_frozen_regression = float("inf")
        frozen_rows: list[dict[str, Any]] = []
        for idx_probe in candidate_indices:
            frozen_energy, _theta_frozen = _frozen_ablation_energy_live(int(idx_probe))
            frozen_regression = float(frozen_energy - float(energy_now))
            selector_burden = float(metadata_live[int(idx_probe)].selector_burden) if int(idx_probe) < len(metadata_live) else 0.0
            cheap_score_prune = cheap_prune_score(
                frozen_regression=float(frozen_regression),
                selector_burden=float(selector_burden),
            )
            metadata_after = [meta for meta_idx, meta in enumerate(metadata_live) if int(meta_idx) != int(idx_probe)]
            prune_window_logical = _prune_refit_window_indices_live(
                removal_index=int(idx_probe),
                metadata_rows=metadata_after,
                n_plus=int(len(ops_now)),
            )
            frozen_rows.append({
                "index": int(idx_probe),
                "label": str(labels_now[int(idx_probe)]),
                "frozen_energy": float(frozen_energy),
                "frozen_regression": float(frozen_regression),
                "selector_burden": float(selector_burden),
                "cheap_prune_score": float(cheap_score_prune),
                "refit_window_indices": [int(x) for x in prune_window_logical],
            })
            candidate_key = (float(cheap_score_prune), float(frozen_regression), int(idx_probe), str(labels_now[int(idx_probe)]))
            incumbent_key = (float(best_frozen_score), float(best_frozen_regression), int(best_candidate_index if best_candidate_index is not None else 10**9), str(best_candidate_label or ""))
            if best_candidate_index is None or candidate_key < incumbent_key:
                best_candidate_index = int(idx_probe)
                best_candidate_label = str(labels_now[int(idx_probe)])
                best_trial_window_logical = [int(x) for x in prune_window_logical]
                best_frozen_score = float(cheap_score_prune)
                best_frozen_regression = float(frozen_regression)
        summary["frozen_scores"] = [dict(x) for x in frozen_rows]
        summary["selected_index"] = int(best_candidate_index) if best_candidate_index is not None else None
        summary["selected_label"] = str(best_candidate_label) if best_candidate_label is not None else None
        retained_reference_energy = float(energy_now + max(0.0, admitted_gain))
        recoverability_prune_policy = bool(
            str(phase1_prune_cfg.policy) == PRUNE_POLICY_RECOVERABILITY_LADDER_V1
        )
        summary["recoverability_ladder_active"] = bool(recoverability_prune_policy)
        summary["recoverability_rung_policy"] = (
            _TYPED_ALGEBRAIC_LIVE_PRUNE_RUNG_POLICY
            if bool(typed_live_prune_active) and bool(recoverability_prune_policy)
            else (
                (
                    "full_survivor_refit_v1"
                    if int(phase1_prune_cfg.local_window_size) <= 0
                    else "local_then_full_refit_v1"
                )
                if recoverability_prune_policy
                else "legacy_best_frozen_single_refit_v1"
            )
        )
        max_regression_effective, _prune_tolerance = _attach_prune_tolerance(
            summary,
            sigma_e=(float(sigma_phase3) if math.isfinite(float(sigma_phase3)) and float(sigma_phase3) > 0.0 else None),
            delta_scr=float(max(float(gain_floor), float(phase1_prune_cfg.max_regression))),
            current_energy=float(energy_now),
        )

        def _eval_with_removal_live(
            idx_remove: int,
            theta_cur: np.ndarray,
            labels_cur: list[str],
            active_logical_indices: list[int] | None = None,
            rung_kind: str = "local_refit",
        ) -> tuple[float, np.ndarray]:
            ops_current = _ops_from_labels(labels_cur)
            layout_current = _build_selected_layout(ops_current)
            runtime_remove_indices = runtime_indices_for_logical_indices(layout_current, [int(idx_remove)])
            ops_trial = list(ops_current)
            del ops_trial[int(idx_remove)]
            theta_trial0 = np.delete(np.asarray(theta_cur, dtype=float), runtime_remove_indices)
            theta_trial_opt, energy_trial, _optimizer_unused = _refit_given_ops_live(
                ops_trial,
                theta_trial0,
                (
                    [int(x) for x in active_logical_indices]
                    if active_logical_indices is not None
                    else [int(x) for x in best_trial_window_logical]
                ),
                copy.deepcopy(optimizer_memory_now),
                prune_warm_start_candidate_index=int(idx_remove),
                prune_warm_start_stage=f"live_{str(rung_kind)}",
            )
            return float(energy_trial), np.asarray(theta_trial_opt, dtype=float)

        if recoverability_prune_policy:
            trial_rows_by_index = {int(row["index"]): dict(row) for row in frozen_rows}
            rung_windows_by_index: dict[int, list[tuple[str, list[int]]]] = {}
            typed_plan_by_index: dict[int, Any] = {}
            typed_plan_payload_by_index: dict[int, dict[str, Any]] = {}
            if bool(typed_live_prune_active):
                for idx_probe in candidate_indices:
                    metadata_after = [
                        meta
                        for meta_idx, meta in enumerate(metadata_live)
                        if int(meta_idx) != int(idx_probe)
                    ]
                    typed_plan, typed_payload = _build_typed_live_prune_plan(
                        candidate_index=int(idx_probe),
                        labels_now=list(labels_now),
                        ops_now=list(ops_now),
                        metadata_after=metadata_after,
                    )
                    typed_plan_by_index[int(idx_probe)] = typed_plan
                    typed_plan_payload_by_index[int(idx_probe)] = dict(typed_payload)
                    rung_windows_by_index[int(idx_probe)] = [
                        (str(kind), [int(x) for x in active_indices])
                        for kind, active_indices in rung_windows_for_recoverability(typed_plan)
                    ]
                summary["typed_prune_ladder_status"] = "planned"
                summary["typed_prune_ladder_plans"] = [
                    dict(typed_plan_payload_by_index[int(idx_probe)])
                    for idx_probe in candidate_indices
                    if int(idx_probe) in typed_plan_payload_by_index
                ]
                summary["candidate_nomination_sources"] = _prune_nomination_sources(
                    prune_cfg=phase1_prune_cfg,
                    indices=[int(x) for x in candidate_indices],
                    labels_now=list(labels_now),
                    typed_compensator_active=True,
                    lane_membership={
                        "recoverability_broad_rank": set(int(x) for x in candidate_indices),
                        "schur_surrogate": set(int(x) for x in candidate_indices),
                    },
                )
            else:
                for idx_probe in candidate_indices:
                    local_window = [int(x) for x in trial_rows_by_index.get(int(idx_probe), {}).get("refit_window_indices", [])]
                    survivor_window = [int(i) for i in range(max(0, len(ops_now) - 1))]
                    rung_specs: list[tuple[str, list[int]]] = [("local_refit", list(local_window))]
                    if set(survivor_window) != set(local_window):
                        rung_specs.append(("full_refit", list(survivor_window)))
                    rung_windows_by_index[int(idx_probe)] = rung_specs
            theta_pruned, labels_pruned, prune_decisions, energy_after_prune, ladder_rows = recoverability_prune_ladder(
                theta=np.asarray(theta_runtime_now, dtype=float),
                labels=list(labels_now),
                candidate_indices=[int(x) for x in candidate_indices],
                rung_windows_by_index=dict(rung_windows_by_index),
                eval_with_removal_window=_eval_with_removal_live,
                energy_before=float(energy_now),
                max_regression=float(max_regression_effective),
                retained_reference_energy=float(retained_reference_energy),
                admitted_gain=float(max(0.0, admitted_gain)),
                retained_gain_ratio=float(phase1_prune_cfg.retained_gain_ratio),
                retained_gain_activation=float(max(float(phase1_prune_cfg.max_regression), float(gain_floor), 1e-12)),
                curvature_guard_mode=(
                    "conservative_v1" if bool(typed_live_prune_active) else "off"
                ),
                curvature_guard_context={
                    "compression_mode": bool(checkpoint_due),
                    "terminal_full": False,
                    "gamma_curv": 0.25,
                    "retained_gain_activation": float(
                        max(float(phase1_prune_cfg.max_regression), float(gain_floor), 1e-12)
                    ),
                },
                max_trial_evaluations=(
                    int(phase1_prune_cfg.surrogate_exact_trial_cap)
                    if schur_gate_threshold is not None
                    else None
                ),
            )
            if bool(typed_live_prune_active):
                enriched_ladder_rows: list[dict[str, Any]] = []
                for row in ladder_rows:
                    row_out = dict(row)
                    idx_plan = int(row_out.get("candidate_index", -1))
                    plan = typed_plan_by_index.get(int(idx_plan))
                    rung_index = int(row_out.get("rung_index", 0))
                    if plan is not None and 0 <= rung_index < len(plan.rungs):
                        rung = plan.rungs[int(rung_index)]
                        row_out.update(
                            {
                                "recoverability_rung_policy": _TYPED_ALGEBRAIC_LIVE_PRUNE_RUNG_POLICY,
                                "typed_prune_ladder_active": True,
                                "typed_rung_kind": str(rung.rung_kind),
                                "opened_pool_kinds": [str(x) for x in rung.opened_pool_kinds],
                                "recovery_class_if_accepted": (
                                    None
                                    if rung.recovery_class_if_accepted is None
                                    else str(rung.recovery_class_if_accepted)
                                ),
                            }
                        )
                    enriched_ladder_rows.append(row_out)
                ladder_rows = enriched_ladder_rows
                recovery_classification = classify_recoverability_from_ladder_rows(ladder_rows)
                recovery_class = str(recovery_classification.get("recovery_class", "failed"))
                for row_out in ladder_rows:
                    if bool(row_out.get("accepted", False)):
                        row_out["recovery_class"] = str(recovery_class)
                summary["recovery_classification"] = dict(recovery_classification)
                summary["recovery_class"] = str(recovery_class)
                summary["typed_prune_ladder_status"] = (
                    "accepted" if bool(recovery_classification.get("accepted", False)) else "failed"
                )
            summary["recoverability_ladder_rows"] = [dict(x) for x in ladder_rows]
            accepted_decision = next((d for d in prune_decisions if bool(d.accepted)), None)
            if accepted_decision is not None:
                best_candidate_index = int(accepted_decision.index)
                best_candidate_label = str(accepted_decision.label)
                trial_row = trial_rows_by_index.get(int(best_candidate_index), {})
                best_trial_window_logical = [int(x) for x in trial_row.get("refit_window_indices", [])]
                if trial_row:
                    best_frozen_score = float(trial_row.get("cheap_prune_score", best_frozen_score))
                    best_frozen_regression = float(trial_row.get("frozen_regression", best_frozen_regression))
            elif candidate_indices:
                last_idx = int(candidate_indices[-1])
                best_candidate_index = int(last_idx)
                best_candidate_label = str(labels_now[int(last_idx)])
        accepted_count = int(sum(1 for d in prune_decisions if bool(d.accepted)))
        accepted_prune_indices = {
            int(decision.index)
            for decision in prune_decisions
            if bool(decision.accepted)
        }
        summary["executed"] = bool(best_candidate_index is not None)
        summary["accepted_count"] = int(accepted_count)
        summary["energy_after_prune"] = float(energy_after_prune)
        summary["energy_after_post_refit"] = float(energy_after_prune)
        summary["decisions"] = [dict(d.__dict__) for d in prune_decisions]
        selected_decision = next((d for d in prune_decisions if bool(d.accepted)), None)
        if selected_decision is None and prune_decisions:
            selected_decision = prune_decisions[-1]
        if selected_decision is not None:
            best_candidate_index = int(selected_decision.index)
            best_candidate_label = str(selected_decision.label)
            summary["selected_index"] = int(best_candidate_index)
            summary["selected_label"] = str(best_candidate_label)
        summary["trial"] = dict(MaturePruneTrial(
            selector_step=int(selector_step),
            gate_open=bool(summary.get("permission_open", False)),
            probe_indices=[int(x) for x in candidate_indices],
            selected_index=(int(best_candidate_index) if best_candidate_index is not None else None),
            selected_label=(str(best_candidate_label) if best_candidate_label is not None else None),
            frozen_regression=(float(best_frozen_regression) if best_candidate_index is not None and math.isfinite(best_frozen_regression) else None),
            refit_energy=(float(energy_after_prune) if best_candidate_index is not None else None),
            retained_gain=(float(retained_reference_energy - float(energy_after_prune)) if best_candidate_index is not None else None),
            accepted=bool(accepted_count > 0),
            rollback_reason=(
                None
                if accepted_count > 0
                else (str(selected_decision.reason) if selected_decision is not None else None)
            ),
        ).__dict__)
        summary["rollback_snapshot_restored"] = bool(prune_decisions and accepted_count == 0)
        summary["rollback_mutation_scope"] = (
            "committed_prune"
            if accepted_count > 0
            else (
                "branch_state_restored_candidate_cooldown_applied"
                if bool(prune_decisions and best_candidate_index is not None)
                else "none"
            )
        )
        summary["optimizer_state_restored"] = bool(prune_decisions and accepted_count == 0)
        summary["candidate_cooldown_applied"] = bool(
            accepted_count == 0 and best_candidate_index is not None
        )

        metadata_out = [ScaffoldCoordinateMetadata(**dict(x.__dict__)) for x in metadata_live]
        first_seen_out = {str(k): int(v) for k, v in first_seen_steps.items()}
        optimizer_out = dict(optimizer_memory_now)
        if accepted_count > 0:
            accepted_remove_indices = [int(d.index) for d in prune_decisions if bool(d.accepted)]
            accepted_runtime_remove_indices = runtime_indices_for_logical_indices(layout_now, accepted_remove_indices)
            if phase2_enabled:
                optimizer_out = phase2_memory_adapter.remap_remove(
                    optimizer_out,
                    indices=list(accepted_runtime_remove_indices),
                )
            label_to_ops: dict[str, list[AnsatzTerm]] = {}
            for op in ops_now:
                label_to_ops.setdefault(str(op.label), []).append(op)
            rebuilt_ops: list[AnsatzTerm] = []
            for lbl in labels_pruned:
                bucket = label_to_ops.get(str(lbl), [])
                if bucket:
                    rebuilt_ops.append(bucket.pop(0))
            metadata_out = [
                meta for meta_idx, meta in enumerate(metadata_out)
                if int(meta_idx) not in set(accepted_remove_indices)
            ]
            return rebuilt_ops, np.asarray(theta_pruned, dtype=float), float(energy_after_prune), optimizer_out, metadata_out, first_seen_out, summary

        if best_candidate_index is not None and int(best_candidate_index) < len(metadata_out):
            cooled = dict(metadata_out[int(best_candidate_index)].__dict__)
            cooled["cooldown_remaining"] = int(phase1_prune_cfg.cooldown_steps)
            metadata_out[int(best_candidate_index)] = ScaffoldCoordinateMetadata(**cooled)
            summary["metadata"] = [dict(x.__dict__) for x in metadata_out]
        return list(ops_now), np.asarray(theta_runtime_now, dtype=float), float(energy_now), optimizer_out, metadata_out, first_seen_out, summary

    def _history_generator_metadata_from_term(term: AnsatzTerm) -> dict[str, Any] | None:
        try:
            raw_terms = list(term.polynomial.return_polynomial())
        except Exception:
            return None
        runtime_terms: list[dict[str, Any]] = []
        for raw_term in raw_terms:
            try:
                label = str(raw_term.pw2strng()).strip().lower()
                coeff = complex(raw_term.p_coeff)
                nq_term = int(raw_term.nqubit())
            except Exception:
                continue
            if not label or set(label) == {"e"}:
                continue
            runtime_terms.append(
                {
                    "pauli_exyz": label,
                    "coeff_re": float(coeff.real),
                    "coeff_im": float(coeff.imag),
                    "nq": int(nq_term),
                }
            )
        if not runtime_terms:
            return None
        return {
            "generator_id": str(term.label),
            "template_id": None,
            "is_macro_generator": False,
            "parent_generator_id": None,
            "compile_metadata": {
                "serialized_terms_exyz": [dict(x) for x in runtime_terms],
                "runtime_terms_exyz": [dict(x) for x in runtime_terms],
            },
        }

    def _history_generator_metadata_for_feature_row(row: Mapping[str, Any]) -> dict[str, Any] | None:
        label = row.get("candidate_label")
        metadata = (
            history_pool_generator_registry.get(str(label))
            if label is not None
            else None
        )
        if not isinstance(metadata, Mapping):
            candidate_pool_index = None
            raw_candidate_pool_index = row.get("candidate_pool_index")
            if raw_candidate_pool_index is not None:
                try:
                    candidate_pool_index = int(raw_candidate_pool_index)
                except (TypeError, ValueError):
                    candidate_pool_index = None
            if candidate_pool_index is not None and 0 <= int(candidate_pool_index) < len(pool):
                metadata = history_pool_generator_registry.get(str(pool[int(candidate_pool_index)].label))
                if not isinstance(metadata, Mapping):
                    metadata = _history_generator_metadata_from_term(pool[int(candidate_pool_index)])
        return dict(metadata) if isinstance(metadata, Mapping) else None

    def _assert_required_runtime_split_admission_guard(
        *,
        feature_row: Mapping[str, Any],
        candidate_label: str,
    ) -> None:
        """Fail before ansatz mutation if a required child guard was skipped."""

        if str(phase3_runtime_split_child_set_symmetry_policy_key) != "hard_guard":
            return
        if str(phase3_runtime_split_selection_mode_key) != "archival_child_set_forward_v1":
            return
        if str(feature_row.get("runtime_split_mode", "off")) == "off":
            return
        metadata = feature_row.get("generator_metadata")
        if not isinstance(metadata, Mapping):
            raise RuntimeError(
                "Required runtime-split hard guard has no generator metadata "
                f"for admission {candidate_label!r}."
            )
        compile_metadata = metadata.get("compile_metadata")
        compile_metadata = (
            compile_metadata if isinstance(compile_metadata, Mapping) else {}
        )
        runtime_split_metadata = compile_metadata.get("runtime_split")
        runtime_split_metadata = (
            runtime_split_metadata
            if isinstance(runtime_split_metadata, Mapping)
            else {}
        )
        symmetry_gate = runtime_split_metadata.get("symmetry_gate")
        if not isinstance(symmetry_gate, Mapping):
            symmetry_gate = compile_metadata.get("symmetry_gate")
        if not isinstance(symmetry_gate, Mapping):
            raise RuntimeError(
                "Required runtime-split hard guard has no executed gate payload "
                f"for admission {candidate_label!r}."
            )
        contract_ok = _runtime_split_admission_guard_contract_satisfied(
            symmetry_gate=symmetry_gate,
            expected_fixed_num_particles=_runtime_split_fixed_num_particles(
                problem_key=problem_key,
                num_particles=num_particles,
            ),
        )
        if not contract_ok:
            raise RuntimeError(
                "Required runtime-split fixed-sector guard was not satisfied "
                f"before admission {candidate_label!r}: {dict(symmetry_gate)!r}."
            )

    def _fixed_spin_sector_probability(state: np.ndarray) -> float | None:
        if problem_key not in {"hh", "hubbard"}:
            return None
        psi = np.asarray(state, dtype=complex).reshape(-1)
        up_qubits = [
            int(
                mode_index(
                    site,
                    SPIN_UP,
                    indexing=str(ordering),
                    n_sites=int(num_sites),
                )
            )
            for site in range(int(num_sites))
        ]
        dn_qubits = [
            int(
                mode_index(
                    site,
                    SPIN_DN,
                    indexing=str(ordering),
                    n_sites=int(num_sites),
                )
            )
            for site in range(int(num_sites))
        ]
        probability = 0.0
        for basis_index, amplitude in enumerate(psi):
            n_up_now = sum(
                (int(basis_index) >> qubit) & 1 for qubit in up_qubits
            )
            n_dn_now = sum(
                (int(basis_index) >> qubit) & 1 for qubit in dn_qubits
            )
            if (int(n_up_now), int(n_dn_now)) == (
                int(num_particles[0]),
                int(num_particles[1]),
            ):
                probability += float(abs(amplitude) ** 2)
        return float(min(max(probability, 0.0), 1.0))

    estimator_prefix_checkpoint_cursor: dict[str, Any] = {
        "checkpoint_sequence": 0,
        "raw_occurrence_count": 0,
        "unique_primitive_count": 0,
        "unique_components": {
            component: 0
            for component in ("N_H_outer", "N_H_refit", "N_grad", "N_metric")
        },
        "occurrence_components": {
            component: 0
            for component in ("N_H_outer", "N_H_refit", "N_grad", "N_metric")
        },
    }
    estimator_active_prefix_ledger_receipts_all: list[dict[str, Any]] = []
    if resume_checkpoint_estimator_ledger_provenance is not None:
        if estimator_call_ledger is None or adapt_resume_source is None:
            raise RuntimeError(
                "Authenticated estimator-ledger resume lost its ledger or "
                "source payload before prefix-receipt restoration."
            )
        source_adapt_payload = adapt_resume_source.payload.get("adapt_vqe", {})
        if not isinstance(source_adapt_payload, Mapping):
            raise ValueError(
                "Authenticated estimator-ledger resume lacks its ADAPT payload."
            )
        source_continuation = source_adapt_payload.get("continuation", {})
        if source_continuation is None:
            source_continuation = {}
        if not isinstance(source_continuation, Mapping):
            raise ValueError(
                "Authenticated estimator-ledger resume continuation is malformed."
            )
        prior_receipts_raw = source_continuation.get(
            "all_active_prefix_estimator_ledger_receipts"
        )
        if prior_receipts_raw is not None and not isinstance(
            prior_receipts_raw, (list, tuple)
        ):
            raise ValueError(
                "Authenticated estimator-ledger resume prefix receipts must "
                "be a sequence."
            )
        (
            estimator_prefix_checkpoint_cursor,
            estimator_active_prefix_ledger_receipts_all,
        ) = _restored_estimator_prefix_checkpoint_state(
            estimator_call_ledger,
            prior_receipts=(
                None
                if prior_receipts_raw is None
                else list(prior_receipts_raw)
            ),
            source_outer_iteration=int(resume_source_controller_round),
        )

    def _active_prefix_estimator_ledger_receipt() -> dict[str, Any]:
        """Snapshot exact cumulative and since-checkpoint estimator work."""

        if estimator_call_ledger is None:
            return {
                "schema": "paper_i_active_prefix_estimator_ledger_receipt_v2",
                "enabled": False,
                "status": "disabled_missing_required_estimator_ledger",
            }
        prefix_summary = (
            estimator_call_ledger.closed_occurrence_prefix_summary()
        )
        components = ("N_H_outer", "N_H_refit", "N_grad", "N_metric")
        cumulative_unique = dict(
            prefix_summary.get("cumulative_unique_primitives", {})
        )
        cumulative_raw = dict(
            prefix_summary.get("cumulative_raw_occurrences", {})
        )
        cumulative_unique_components = dict(
            cumulative_unique.get("components", {})
        )
        cumulative_raw_components = dict(
            cumulative_raw.get("components", {})
        )
        current_unique = {
            component: int(cumulative_unique_components.get(component, 0))
            for component in components
        }
        current_occurrences = {
            component: int(cumulative_raw_components.get(component, 0))
            for component in components
        }
        current_raw_total = int(cumulative_raw.get("total", 0))
        current_unique_total = int(cumulative_unique.get("S_unique", 0))
        previous_raw_total = int(
            estimator_prefix_checkpoint_cursor["raw_occurrence_count"]
        )
        previous_unique_total = int(
            estimator_prefix_checkpoint_cursor["unique_primitive_count"]
        )
        raw_component_delta = {
            component: int(current_occurrences[component])
            - int(
                estimator_prefix_checkpoint_cursor["occurrence_components"][
                    component
                ]
            )
            for component in components
        }
        unique_component_delta = {
            component: int(current_unique[component])
            - int(
                estimator_prefix_checkpoint_cursor["unique_components"][
                    component
                ]
            )
            for component in components
        }
        raw_total_delta = int(current_raw_total - previous_raw_total)
        unique_total_delta = int(current_unique_total - previous_unique_total)
        if (
            raw_total_delta < 0
            or unique_total_delta < 0
            or any(value < 0 for value in raw_component_delta.values())
            or any(value < 0 for value in unique_component_delta.values())
        ):
            raise RuntimeError(
                "Estimator ledger counters regressed while constructing an "
                "active-prefix receipt."
            )
        estimator_prefix_checkpoint_cursor["checkpoint_sequence"] = int(
            estimator_prefix_checkpoint_cursor["checkpoint_sequence"]
        ) + 1
        estimator_prefix_checkpoint_cursor["raw_occurrence_count"] = int(
            current_raw_total
        )
        estimator_prefix_checkpoint_cursor["unique_primitive_count"] = int(
            current_unique_total
        )
        estimator_prefix_checkpoint_cursor["unique_components"] = dict(
            current_unique
        )
        estimator_prefix_checkpoint_cursor["occurrence_components"] = dict(
            current_occurrences
        )
        occurrence_sequence_end = int(
            prefix_summary.get("occurrence_sequence_end_inclusive", 0)
        )
        return {
            "schema": "paper_i_active_prefix_estimator_ledger_receipt_v2",
            "enabled": True,
            "status": "complete",
            "checkpoint_sequence": int(
                estimator_prefix_checkpoint_cursor["checkpoint_sequence"]
            ),
            "occurrence_sequence_start_exclusive": int(previous_raw_total),
            "occurrence_sequence_end_inclusive": (
                int(occurrence_sequence_end)
            ),
            "raw_occurrence_delta": {
                "components": dict(raw_component_delta),
                "total": int(raw_total_delta),
            },
            "executed_query_delta": {
                "components": dict(raw_component_delta),
                "S_alg": int(raw_total_delta),
            },
            "unique_primitive_delta": {
                "components": dict(unique_component_delta),
                "S_unique": int(unique_total_delta),
            },
            "cumulative_raw_occurrences": {
                "components": dict(current_occurrences),
                "total": int(current_raw_total),
            },
            "cumulative_executed_queries": {
                "components": dict(current_occurrences),
                "S_alg": int(current_raw_total),
                "unit": "executed_logical_scalar_estimator_invocation",
            },
            "cumulative_unique_primitives": {
                "components": dict(current_unique),
                "S_unique": int(current_unique_total),
            },
            "runtime_estimator_occurrence_contract": (
                "all_instrumented_logical_scalar_estimator_calls_v1"
            ),
            "physical_identity_collapse_is_diagnostic_only": True,
            "raw_occurrences_preserved": True,
        }

    def _active_prefix_checkpoint_payload(
        *,
        outer_iteration: int,
        selected_ops_now: Sequence[AnsatzTerm],
        theta_runtime_now: np.ndarray,
        history_row: Mapping[str, Any] | None,
        checkpoint_kind: str = "post_admission_prune",
        checkpoint_ready_event: (
            _CheckpointReadyAcceptedStateEvent | None
        ) = None,
    ) -> dict[str, Any]:
        ops_list = list(selected_ops_now)
        layout_now = _build_selected_layout(ops_list)
        theta_runtime_array = np.asarray(
            theta_runtime_now, dtype=float
        ).reshape(-1)
        theta_runtime_array = _canonicalize_runtime_theta_for_selected_layout(
            theta_runtime_array, layout_now
        )
        active_generator_sector_audit = _active_generator_sector_contract(
            ops_list,
            source="active_prefix_checkpoint",
        )
        theta_logical_array = np.asarray(
            _logical_theta_alias(theta_runtime_array, layout_now), dtype=float
        ).reshape(-1)
        state_now = _prepare_selected_state(
            ops_now=ops_list,
            theta_now=theta_runtime_array,
            executor_now=None,
            parameter_layout_now=layout_now,
        )
        state_sector_audit = fixed_count_state_auditor.assert_valid(
            state_now,
            source="active_prefix_checkpoint",
        )
        strict_replay_audit = _strict_replay_selected_state(
            ops_now=ops_list,
            theta_now=theta_runtime_array,
            expected_state=state_now,
            parameter_layout_now=layout_now,
            source="active_prefix_checkpoint",
        )
        operator_rows: list[dict[str, Any]] = []
        for active_position, operator in enumerate(ops_list):
            metadata = pool_generator_registry.get(str(operator.label))
            if not isinstance(metadata, Mapping):
                metadata = _history_generator_metadata_from_term(operator)
            metadata = dict(metadata) if isinstance(metadata, Mapping) else {}
            compile_metadata = metadata.get("compile_metadata")
            compile_metadata = (
                compile_metadata
                if isinstance(compile_metadata, Mapping)
                else {}
            )
            serialized_terms = compile_metadata.get("runtime_terms_exyz")
            if not isinstance(serialized_terms, Sequence):
                serialized_terms = compile_metadata.get(
                    "serialized_terms_exyz"
                )
            if not isinstance(serialized_terms, Sequence):
                fallback_metadata = _history_generator_metadata_from_term(
                    operator
                )
                fallback_compile = (
                    fallback_metadata.get("compile_metadata", {})
                    if isinstance(fallback_metadata, Mapping)
                    else {}
                )
                serialized_terms = fallback_compile.get(
                    "runtime_terms_exyz", []
                )
            operator_rows.append(
                {
                    "active_position": int(active_position),
                    "label": str(operator.label),
                    "generator_id": metadata.get("generator_id"),
                    "parent_generator_id": metadata.get(
                        "parent_generator_id"
                    ),
                    "execution_mode": str(
                        getattr(
                            operator, "execution_mode", "termwise_product"
                        )
                        or "termwise_product"
                    ),
                    "serialized_terms_exyz_in_execution_order": [
                        dict(term)
                        for term in serialized_terms
                        if isinstance(term, Mapping)
                    ],
                    "runtime_split": (
                        dict(compile_metadata.get("runtime_split", {}))
                        if isinstance(
                            compile_metadata.get("runtime_split"), Mapping
                        )
                        else None
                    ),
                    "symmetry_gate": (
                        copy.deepcopy(
                            compile_metadata.get("symmetry_gate")
                        )
                        if isinstance(
                            compile_metadata.get("symmetry_gate"),
                            Mapping,
                        )
                        else None
                    ),
                    "ra_retained_parent_owner": (
                        copy.deepcopy(
                            metadata.get(
                                "ra_retained_parent_owner"
                            )
                        )
                        if isinstance(
                            metadata.get(
                                "ra_retained_parent_owner"
                            ),
                            Mapping,
                        )
                        else None
                    ),
                    "route_a_child_padding_lineage": (
                        copy.deepcopy(
                            compile_metadata.get(
                                "route_a_child_padding_lineage"
                            )
                        )
                        if isinstance(
                            compile_metadata.get(
                                "route_a_child_padding_lineage"
                            ),
                            Mapping,
                        )
                        else None
                    ),
                }
            )
        legal_probability = None
        legal_layout = None
        if problem_key in _BOSON_SUBSPACE_DIAGNOSTIC_PROBLEMS:
            legal_probability, legal_layout = (
                _state_boson_codeword_legal_probability(
                    np.asarray(state_now, dtype=complex),
                    problem_key=str(problem_key),
                    num_sites=int(num_sites),
                    n_ph_max=int(n_ph_max),
                    boson_encoding=str(boson_encoding),
                )
            )
        sector_probability = _fixed_spin_sector_probability(state_now)
        source_history = dict(history_row) if isinstance(history_row, Mapping) else {}
        if checkpoint_ready_event is not None:
            event_expected = (
                int(outer_iteration),
                projective_state_fingerprint(state_now),
                tuple(
                    str(
                        (
                            pool_generator_registry.get(
                                str(operator.label), {}
                            )
                            or {}
                        ).get("generator_id", operator.label)
                    )
                    for operator in ops_list
                ),
                tuple(range(len(ops_list))),
                tuple(
                    f"logical:{index}"
                    for index in range(int(theta_logical_array.size))
                ),
                tuple(float(value) for value in theta_logical_array),
                tuple(
                    f"runtime:{index}"
                    for index in range(int(theta_runtime_array.size))
                ),
                tuple(float(value) for value in theta_runtime_array),
            )
            event_observed = (
                checkpoint_ready_event.controller_round,
                checkpoint_ready_event.accepted_state_fingerprint,
                checkpoint_ready_event.accepted_operator_ids,
                checkpoint_ready_event.accepted_insertion_positions,
                checkpoint_ready_event.logical_parameter_ids,
                checkpoint_ready_event.logical_parameter_values,
                checkpoint_ready_event.runtime_parameter_ids,
                checkpoint_ready_event.runtime_parameter_values,
            )
            if event_observed != event_expected:
                raise RuntimeError(
                    "checkpoint-ready accepted-state event disagrees with "
                    "the checkpoint projection."
                )
        estimator_ledger_receipt = (
            _active_prefix_estimator_ledger_receipt()
            if checkpoint_ready_event is None
            else checkpoint_ready_event.ledger_closure.active_prefix_receipt()
        )
        estimator_ledger_receipt.update(
            {
                "outer_iteration": int(outer_iteration),
                "checkpoint_kind": str(checkpoint_kind),
                "branch_id": (
                    None
                    if source_history.get("branch_id") is None
                    else str(source_history.get("branch_id"))
                ),
                "parent_branch_id": (
                    None
                    if source_history.get("parent_branch_id") is None
                    else str(source_history.get("parent_branch_id"))
                ),
            }
        )
        estimator_active_prefix_ledger_receipts_all.append(
            copy.deepcopy(estimator_ledger_receipt)
        )
        checkpoint = {
            "schema": "paper_i_signed_active_prefix_checkpoint_v1",
            "checkpoint_kind": str(checkpoint_kind),
            "outer_iteration": int(outer_iteration),
            "active_ansatz_depth": int(len(ops_list)),
            "ordered_active_operator_labels": [
                str(operator.label) for operator in ops_list
            ],
            "ordered_active_operators": operator_rows,
            "signed_unwrapped_runtime_parameters": [
                float(value) for value in theta_runtime_array.tolist()
            ],
            "signed_unwrapped_logical_parameters": [
                float(value) for value in theta_logical_array.tolist()
            ],
            "parameterization_mode": str(selected_parameterization_mode),
            "parameterization_execution_mode": str(
                selected_parameterization_mode
            ),
            "parameterization_execution_mode_source": str(
                selected_parameterization_mode_source
            ),
            "optimizer_coordinate_chart": _optimizer_coordinate_chart_payload(
                layout=layout_now,
                parameterization_execution_mode=selected_parameterization_mode,
                optimizer_key=adapt_inner_optimizer_key,
                powell_coordinate_chart_policy=(
                    optimizer_powell_coordinate_chart_policy_key
                ),
            ),
            "sr_route_profile": str(sr_route_profile_key),
            "sr_route_profile_contract_sha256": (
                None
                if sr_route_profile_contract_resolved is None
                else str(sr_route_profile_contract_sha256)
            ),
            "phase1_score_mode": str(phase1_score_mode_key),
            "phase1_energy_model": str(phase1_energy_model_key),
            "phase2_curvature_policy": str(phase2_curvature_policy_key),
            "phase2_cheap_curvature_proxy_policy": str(
                phase2_cheap_curvature_proxy_policy_key
            ),
            "parameterization": serialize_layout(layout_now),
            "generator_sector_contract": dict(generator_sector_contract_audit),
            "generator_pool_sector_contract": dict(
                generator_sector_contract_audit
            ),
            "active_generator_sector_contract": dict(
                active_generator_sector_audit
            ),
            "state_sector_contract": dict(state_sector_audit),
            "strict_replay": dict(strict_replay_audit),
            "projective_state_fingerprint": (
                estimator_projective_state_fingerprint(
                    np.asarray(state_now, dtype=complex)
                )
            ),
            "estimator_ledger_receipt": dict(estimator_ledger_receipt),
            "fixed_spin_sector_probability": sector_probability,
            "fixed_spin_sector_illegal_probability": (
                None
                if sector_probability is None
                else float(max(0.0, 1.0 - sector_probability))
            ),
            "boson_legal_codeword_probability": legal_probability,
            "boson_illegal_codeword_probability": (
                None
                if legal_probability is None
                else float(max(0.0, 1.0 - legal_probability))
            ),
            "boson_legal_subspace": legal_layout,
            "admission_at_outer_iteration": {
                "selected_batch_labels": [
                    str(value)
                    for value in source_history.get(
                        "selected_batch_labels",
                        source_history.get("selected_ops", []),
                    )
                ],
                "selected_batch_positions": [
                    int(value)
                    for value in source_history.get(
                        "selected_batch_positions",
                        source_history.get("selected_positions", []),
                    )
                ],
                "selected_batch_effective_positions": [
                    int(value)
                    for value in source_history.get(
                        "selected_batch_effective_positions",
                        source_history.get(
                            "selected_effective_positions",
                            source_history.get("selected_positions", []),
                        ),
                    )
                ],
            },
            "post_admission_prune": copy.deepcopy(
                source_history.get("post_admission_prune")
            ),
        }
        checkpoint["checkpoint_sha256"] = hashlib.sha256(
            json.dumps(
                _current_jsonable(checkpoint),
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            ).encode("utf-8")
        ).hexdigest()
        return checkpoint

    def _candidate_feature_rows(records: Sequence[Mapping[str, Any]] | None) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        if not isinstance(records, Sequence):
            return out
        for rec in records:
            if not isinstance(rec, Mapping):
                continue
            feat_obj = rec.get("feature")
            if isinstance(feat_obj, CandidateFeatures):
                row = dict(feat_obj.__dict__)
                for key in (
                    "insertion_position_equivalence_members",
                    "insertion_position_commutation_reduced",
                ):
                    if rec.get(key) is not None:
                        row[key] = copy.deepcopy(rec.get(key))
            elif rec.get("candidate_label") is not None:
                row = dict(rec)
            else:
                continue
            if not isinstance(row.get("generator_metadata"), Mapping):
                generator_metadata = _history_generator_metadata_for_feature_row(row)
                if generator_metadata is not None:
                    row["generator_metadata"] = generator_metadata
                    for key in (
                        "generator_id",
                        "template_id",
                        "is_macro_generator",
                        "parent_generator_id",
                    ):
                        if row.get(key) is None and generator_metadata.get(key) is not None:
                            row[key] = generator_metadata.get(key)
            out.append(row)
        return out

