        return _get_phase3_oracle_plan_cached(
            layout_now=layout_now,
            build_parameterized_ansatz_plan_fn=build_parameterized_ansatz_plan_fn,
            phase3_oracle_num_qubits=int(phase3_oracle_num_qubits),
            reference_state=psi_ref,
            plan_cache=phase3_oracle_plan_cache,
        )

