        phase3_oracle_runtime_context = _setup_phase3_oracle_runtime_context(
            config=phase3_oracle_gradient_config,
            h_poly=h_poly,
            num_qubits=int(phase3_oracle_num_qubits),
            runtime_bindings_factory=_phase3_oracle_runtime_bindings,
            inner_value_noise_exact_structure_enabled=bool(
                phase3_oracle_inner_value_noise_exact_structure_enabled
            ),
            log_fn=_ai_log,
        )
        phase3_runtime_bindings_cache = dict(phase3_oracle_runtime_context.bindings)
        build_parameterized_ansatz_plan_fn = (
            phase3_oracle_runtime_context.build_parameterized_ansatz_plan_fn
        )
        build_runtime_layout_circuit_fn = (
            phase3_oracle_runtime_context.build_runtime_layout_circuit_fn
        )
        phase3_oracle = phase3_oracle_runtime_context.oracle_obj
        phase3_oracle_cleanup = phase3_oracle_runtime_context.cleanup_guard
        phase3_oracle_h_qop = phase3_oracle_runtime_context.h_qop
