@dataclass(slots=True)
class _DefaultNoPruneNumericalCursor:
    """Mutable accepted-state and continuation data for the exact route."""

    controller_round: int
    selected_ops: list[AnsatzTerm]
    selected_operator_metadata: list[dict[str, Any]]
    theta: np.ndarray
    selected_layout: AnsatzParameterLayout
    selected_executor: CompiledAnsatzExecutor | None
    accepted_energy: float
    available_indices: set[int]
    selection_counts: np.ndarray
    history: list[dict[str, Any]]
    nfev_total: int
    phase1_stage: StageController
    phase1_measure_cache: MeasurementCacheAudit
    controller_measurement_work: ControllerMeasurementWorkAccumulator
    phase2_optimizer_memory: dict[str, Any]
    route_a_trust_region_state: RouteATrustRegionState | None
    estimator_call_ledger: EstimatorCallLedger | None
    estimator_prefix_checkpoint_cursor: dict[str, Any]
    estimator_active_prefix_ledger_receipts_all: list[dict[str, Any]]
    pool_generator_registry: dict[str, dict[str, Any]]
    phase3_last_candidate_gradient_scout: list[dict[str, Any]]
    phase3_last_max_gradient_stderr: float | None
    phase3_oracle_gradient_calls_total: int
    phase3_runtime_split_summary: dict[str, Any]
    pauli_action_cache: dict[str, CompiledPauliAction]
    phase12_energy_model_telemetry: dict[str, Any]
    phase12_energy_model_telemetry_lock: Lock
    initial_outer_measurement_cache: Any | None
    prune_trust_state: AffineDeletionFSTrustState | None
    operator_admission_rounds: list[int]
    controller_energy: float | None = None
    beam_winning_branch_ids: tuple[str, ...] = ()
    beam_search_diagnostics: dict[str, Any] = field(default_factory=dict)
    beam_resume_fork_local_lineage_s_alg: int = 0
    beam_fork_excluded_pool_indices: frozenset[int] = frozenset()
    resume_source_rounds: int = 0
    resume_provenance: dict[str, Any] = field(default_factory=dict)
    pending_selection: _DefaultNoPrunePendingSelection | None = None

    def selection_available_indices(self) -> set[int]:
        """Return the pool indices this round's selection may choose from.

        ``available_indices`` is the branch's persistent pool availability and
        is the value that is snapshotted, checkpointed, and rehydrated on
        resume.  A fork-local beam child additionally carries a *round-scoped*
        exclusion so that siblings of one parent explore distinct admissions;
        that exclusion constrains one selection decision only and must never
        enter persistent availability.
        """

        if not self.beam_fork_excluded_pool_indices:
            return set(self.available_indices)
        return {
            int(index)
            for index in self.available_indices
            if int(index) not in self.beam_fork_excluded_pool_indices
        }


@dataclass(slots=True)
class _DefaultNoPruneNumericalSession:
    """Controller-driven exact-route session with explicit resource ownership."""

    context: _DefaultNoPruneKernelContext
    cursor: _DefaultNoPruneNumericalCursor
    estimator_service: _DefaultNoPruneEstimatorService
    candidate_sector_auditor: _DefaultNoPruneCandidateSectorAuditor
    initial_accepted_state: _AcceptedStateSnapshot
    pending_transition_runtime: (
        _DefaultSingletonTransitionRuntime | None
    ) = None
    pending_transition_decision: (
        _SingletonAdmissionDecision
        | _GreedyBatchAdmissionDecision
        | _CombinatorialBatchAdmissionDecision
        | None
    ) = None
    _closed: bool = False

    def fork_beam_branch(
        self,
        state: _AcceptedStateSnapshot,
        *,
        branch_id: str,
        parent_branch_id: str | None,
        excluded_pool_indices: Sequence[int] = (),
    ) -> tuple[
        "_DefaultNoPruneNumericalSession",
        _AcceptedStateSnapshot,
    ]:
        """Fork one isolated accepted-state continuation over the live ledger.

        Numerical branch state is copied.  The estimator ledger, its monotone
        active-prefix cursor, and the prefix-receipt stream are deliberately
        shared so discarded branch work remains part of canonical ``S_alg``.
        """

        if self._closed:
            raise RuntimeError("Cannot fork a closed numerical session.")
        if (
            self.cursor.pending_selection is not None
            or self.pending_transition_runtime is not None
            or self.pending_transition_decision is not None
        ):
            raise RuntimeError(
                "Beam forks require a fully accepted, transaction-free state."
            )
        ledger = self.cursor.estimator_call_ledger
        if ledger is None:
            raise RuntimeError("Beam execution requires the estimator ledger.")
        excluded = frozenset(
            int(value) for value in excluded_pool_indices
        )
        # ``available_indices`` stays at full parent availability: it is the
        # branch's persistent pool state and is what gets snapshotted and
        # rehydrated.  ``selectable_indices`` is this fork's round-scoped
        # sibling-diversity view and constrains only the admission the child is
        # about to make.
        available_indices = set(self.cursor.available_indices)
        selectable_indices = available_indices.difference(excluded)
        if not selectable_indices:
            raise RuntimeError(
                "Beam child exclusions exhausted the admissible pool."
            )
        occurrence_rows = _default_no_prune_ledger_occurrences(ledger)
        prefix_cursor = self.cursor.estimator_prefix_checkpoint_cursor
        prefix_count = int(prefix_cursor["raw_occurrence_count"])
        if prefix_count < 0 or prefix_count > len(occurrence_rows):
            raise RuntimeError(
                "Beam fork estimator-prefix cursor lies outside the ledger."
            )

        available_generator_ids, selection_counts = (
            _default_no_prune_portable_pool_state(
                pool=self.context.pool,
                available_indices=available_indices,
                selection_counts=self.cursor.selection_counts,
                pool_generator_registry=(
                    self.cursor.pool_generator_registry
                ),
            )
        )
        synchronized_state = replace(
            state,
            available_generator_ids=available_generator_ids,
            selection_counts=selection_counts,
            estimator_prefix_identity=(
                _default_no_prune_estimator_prefix_identity(
                    occurrence_rows[:prefix_count]
                )
            ),
        )
        initial_outer_cache = self.cursor.initial_outer_measurement_cache
        cloned_initial_outer_cache = (
            None
            if initial_outer_cache is None
            else (
                np.asarray(initial_outer_cache[0], dtype=complex).copy(),
                float(initial_outer_cache[1]),
                np.asarray(initial_outer_cache[2], dtype=complex).copy(),
            )
        )
        cloned_cursor = _DefaultNoPruneNumericalCursor(
            controller_round=int(self.cursor.controller_round),
            selected_ops=list(self.cursor.selected_ops),
            selected_operator_metadata=copy.deepcopy(
                self.cursor.selected_operator_metadata
            ),
            theta=np.asarray(self.cursor.theta, dtype=float).copy(),
            selected_layout=copy.deepcopy(self.cursor.selected_layout),
            selected_executor=self.cursor.selected_executor,
            accepted_energy=float(self.cursor.accepted_energy),
            available_indices=available_indices,
            selection_counts=np.asarray(
                self.cursor.selection_counts,
                dtype=np.int64,
            ).copy(),
            history=copy.deepcopy(self.cursor.history),
            nfev_total=int(self.cursor.nfev_total),
            phase1_stage=self.cursor.phase1_stage.clone(),
            phase1_measure_cache=(
                self.cursor.phase1_measure_cache.clone()
            ),
            controller_measurement_work=(
                self.cursor.controller_measurement_work.clone()
            ),
            phase2_optimizer_memory=copy.deepcopy(
                self.cursor.phase2_optimizer_memory
            ),
            route_a_trust_region_state=copy.deepcopy(
                self.cursor.route_a_trust_region_state
            ),
            estimator_call_ledger=ledger,
            estimator_prefix_checkpoint_cursor=prefix_cursor,
            estimator_active_prefix_ledger_receipts_all=(
                self.cursor.estimator_active_prefix_ledger_receipts_all
            ),
            pool_generator_registry=copy.deepcopy(
                self.cursor.pool_generator_registry
            ),
            phase3_last_candidate_gradient_scout=copy.deepcopy(
                self.cursor.phase3_last_candidate_gradient_scout
            ),
            phase3_last_max_gradient_stderr=(
                None
                if self.cursor.phase3_last_max_gradient_stderr is None
                else float(
                    self.cursor.phase3_last_max_gradient_stderr
                )
            ),
            phase3_oracle_gradient_calls_total=int(
                self.cursor.phase3_oracle_gradient_calls_total
            ),
            phase3_runtime_split_summary=copy.deepcopy(
                self.cursor.phase3_runtime_split_summary
            ),
            pauli_action_cache=self.cursor.pauli_action_cache,
            phase12_energy_model_telemetry=copy.deepcopy(
                self.cursor.phase12_energy_model_telemetry
            ),
            phase12_energy_model_telemetry_lock=Lock(),
            initial_outer_measurement_cache=cloned_initial_outer_cache,
            prune_trust_state=copy.deepcopy(
                self.cursor.prune_trust_state
            ),
            operator_admission_rounds=list(
                self.cursor.operator_admission_rounds
            ),
            controller_energy=(
                None
                if self.cursor.controller_energy is None
                else float(self.cursor.controller_energy)
            ),
            beam_winning_branch_ids=tuple(
                self.cursor.beam_winning_branch_ids
            ),
            beam_search_diagnostics=copy.deepcopy(
                self.cursor.beam_search_diagnostics
            ),
            beam_resume_fork_local_lineage_s_alg=int(
                self.cursor.beam_resume_fork_local_lineage_s_alg
            ),
            beam_fork_excluded_pool_indices=excluded,
            resume_source_rounds=int(self.cursor.resume_source_rounds),
            resume_provenance=copy.deepcopy(
                self.cursor.resume_provenance
            ),
        )
        cloned_context = replace(
            self.context,
            checkpoint_path=None,
            oracle_cleanup=None,
        )
        child = _DefaultNoPruneNumericalSession(
            context=cloned_context,
            cursor=cloned_cursor,
            estimator_service=self.estimator_service,
            candidate_sector_auditor=self.candidate_sector_auditor,
            initial_accepted_state=synchronized_state,
        )
        child.estimator_service.call_context.branch_id = str(branch_id)
        child.estimator_service.call_context.parent_branch_id = (
            None
            if parent_branch_id is None
            else str(parent_branch_id)
        )
        return child, synchronized_state

    def clear_beam_branch_context(self) -> None:
        """Clear thread-local branch provenance after one child transaction."""

        for name in ("branch_id", "parent_branch_id"):
            if hasattr(self.estimator_service.call_context, name):
                delattr(self.estimator_service.call_context, name)
        # The sibling-diversity exclusion is scoped to the single admission
        # this child just executed.  A promoted child becomes the next round's
        # parent, so leaving the exclusion live would delete the operator from
        # the surviving lineage's pool permanently.
        self.cursor.beam_fork_excluded_pool_indices = frozenset()

    def beam_executed_s_alg(self) -> int:
        """Return all globally executed estimator occurrences so far."""

        ledger = self.cursor.estimator_call_ledger
        if ledger is None:
            raise RuntimeError("Beam execution requires the estimator ledger.")
        return int(
            ledger.occurrence_summary()["total_call_occurrences"]
        )

    def beam_executed_s_alg_components(
        self,
    ) -> tuple[tuple[str, int], ...]:
        """Return the cumulative all-branch component closure."""

        ledger = self.cursor.estimator_call_ledger
        if ledger is None:
            raise RuntimeError("Beam execution requires the estimator ledger.")
        summary = ledger.occurrence_summary()
        raw_components = summary.get("component_occurrence_counts")
        if not isinstance(raw_components, Mapping):
            raise RuntimeError(
                "Beam estimator ledger omitted cumulative components."
            )
        components = tuple(
            (
                component,
                int(raw_components.get(component, 0)),
            )
            for component in _DEFAULT_NO_PRUNE_ESTIMATOR_COMPONENTS
        )
        if sum(value for _, value in components) != int(
            summary["total_call_occurrences"]
        ):
            raise RuntimeError(
                "Beam estimator components do not close to cumulative S_alg."
            )
        return components

    def beam_resume_seed(self) -> tuple[tuple[str, ...], int]:
        """Return the authenticated winner lineage already present on resume."""

        branch_ids = tuple(
            str(value) for value in self.cursor.beam_winning_branch_ids
        )
        if not branch_ids:
            return (), 0
        lineage_s_alg = int(
            self.cursor.beam_resume_fork_local_lineage_s_alg
        )
        if lineage_s_alg <= 0:
            raise RuntimeError(
                "Resumed beam execution requires an authenticated positive "
                "fork-local winner-lineage S_alg baseline."
            )
        return branch_ids, lineage_s_alg

    def configure_beam_winner(
        self,
        *,
        winning_branch_ids: Sequence[str],
        diagnostics: Mapping[str, Any],
        observation_owner: "_DefaultNoPruneNumericalSession",
    ) -> None:
        """Bind final winning-lineage accounting and terminal observation I/O."""

        full_branch_ids = tuple(
            str(value) for value in winning_branch_ids
        )
        authenticated_prefix = tuple(
            str(value)
            for value in self.cursor.beam_winning_branch_ids
        )
        new_branch_ids = full_branch_ids[
            len(authenticated_prefix) :
        ]
        if (
            not new_branch_ids
            or full_branch_ids[: len(authenticated_prefix)]
            != authenticated_prefix
            or len(set(full_branch_ids)) != len(full_branch_ids)
        ):
            raise ValueError(
                "Beam winning lineage must extend the authenticated prefix "
                "with unique new branch identities."
            )
        prior_diagnostics = copy.deepcopy(
            self.cursor.beam_search_diagnostics
        )
        normalized_diagnostics = copy.deepcopy(dict(diagnostics))
        prior_rounds = (
            list(prior_diagnostics.get("rounds", ()))
            if authenticated_prefix
            else []
        )
        new_rounds = list(normalized_diagnostics.get("rounds", ()))
        if len(prior_rounds) != len(authenticated_prefix):
            raise RuntimeError(
                "Authenticated beam diagnostics do not cover their winner "
                "prefix."
            )
        if len(new_rounds) != len(new_branch_ids):
            raise RuntimeError(
                "New beam diagnostics do not cover their winner suffix."
            )
        normalized_diagnostics["winning_branch_ids"] = list(
            full_branch_ids
        )
        normalized_diagnostics["rounds"] = [
            *prior_rounds,
            *new_rounds,
        ]
        if authenticated_prefix:
            normalized_diagnostics["initial_unbranched_s_alg"] = int(
                prior_diagnostics["initial_unbranched_s_alg"]
            )
            normalized_diagnostics["resume_segment"] = {
                "schema": "paper_i_canonical_beam_resume_segment_v1",
                "authenticated_prefix_branch_ids": list(
                    authenticated_prefix
                ),
                "new_branch_ids": list(new_branch_ids),
                "source_round_count": len(prior_rounds),
                "new_round_count": len(new_rounds),
            }
        self.cursor.beam_winning_branch_ids = full_branch_ids
        self.cursor.beam_search_diagnostics = normalized_diagnostics
        self.context = replace(
            self.context,
            checkpoint_path=observation_owner.context.checkpoint_path,
            checkpoint_cadence=(
                observation_owner.context.checkpoint_cadence
            ),
            checkpoint_history_tail=(
                observation_owner.context.checkpoint_history_tail
            ),
            oracle_cleanup=None,
        )

