def _default_no_prune_full_score_config(
    kwargs: Mapping[str, Any],
    *,
    phase2_shortlist_size: int,
    phase2_shortlist_fraction: float,
    batch: BatchExtension | None,
) -> FullScoreConfig:
    """Normalize the exact active Phase-II/III score configuration."""

    z_alpha = (
        kwargs["phase1_score_z_alpha"]
        if kwargs.get("phase2_score_z_alpha") is None
        else kwargs["phase2_score_z_alpha"]
    )
    batch_cap = 1 if batch is None else int(batch.maximum_size)
    remaining_proxy = str(
        kwargs["phase2_remaining_evaluations_proxy_mode"]
    ).strip().lower()
    if remaining_proxy == "auto":
        remaining_proxy = "remaining_depth"
    score_cfg = FullScoreConfig(
        z_alpha=float(z_alpha),
        lambda_H=float(max(1.0e-12, kwargs["phase2_lambda_H"])),
        rho=float(kwargs["phase2_rho"]),
        depth_ref=float(kwargs["phase2_depth_ref"]),
        group_ref=float(kwargs["phase2_group_ref"]),
        shot_ref=float(kwargs["phase2_shot_ref"]),
        optdim_ref=float(kwargs["phase2_optdim_ref"]),
        reuse_ref=float(kwargs["phase2_reuse_ref"]),
        family_ref=float(kwargs["phase2_family_ref"]),
        deferred_gram_fallback_enabled=bool(
            str(kwargs["phase2_gram_novelty_policy"]).strip().lower()
            == GRAM_NOVELTY_POLICY_FALLBACK_ONLY_V1
            and str(kwargs["phase3_gram_novelty_policy"]).strip().lower()
            == GRAM_NOVELTY_POLICY_FALLBACK_ONLY_V1
        ),
        deferred_gram_fallback_ridge=float(
            kwargs["deferred_gram_fallback_ridge"]
        ),
        phase2_curvature_policy=str(
            normalize_phase2_curvature_policy(
                kwargs["phase2_curvature_policy"]
            )
        ),
        phase2_cheap_curvature_proxy_policy=str(
            normalize_phase2_cheap_curvature_proxy_policy(
                kwargs["phase2_cheap_curvature_proxy_policy"]
            )
        ),
        phase2_selector_gain_mode=str(
            normalize_phase2_selector_gain_mode(
                kwargs["phase2_selector_gain_mode"]
            )
        ),
        hardware_resolution_mode=str(
            kwargs["hardware_resolution_mode"]
        ),
        hardware_cost_normalization_mode=str(
            kwargs["phase3_hardware_cost_normalization_mode"]
        ),
        phase3_signed_factor_consumer_semantic_version=(
            None
            if kwargs.get("ra_semantic_implementation_version") is None
            else PHASE3_ZERO_CENTERED_SIGNED_FACTOR_CONSUMER_SEMANTIC_VERSION
        ),
        manual_b_g_hw=float(kwargs["gradient_hw_floor"]),
        manual_b_g_drift=float(kwargs["gradient_drift_floor"]),
        cheap_score_eps=float(kwargs["phase2_cheap_score_eps"]),
        leakage_cap=float(kwargs["phase2_leakage_cap"]),
        metric_floor=float(kwargs["phase2_metric_floor"]),
        reduced_metric_collapse_rel_tol=float(
            kwargs["phase2_reduced_metric_collapse_rel_tol"]
        ),
        ridge_growth_factor=float(
            kwargs["phase2_ridge_growth_factor"]
        ),
        ridge_max_steps=int(kwargs["phase2_ridge_max_steps"]),
        phase3_selector_geometry_mode=str(
            kwargs["phase3_selector_geometry_mode"]
        ).strip().lower(),
        phase3_window_relaxation_mode=str(
            kwargs["phase3_window_relaxation_mode"]
        ).strip().lower(),
        lambda_2q=kwargs["phase2_lambda_2q"],
        lambda_d=kwargs["phase2_lambda_d"],
        lambda_1q=kwargs["phase2_lambda_1q"],
        lambda_theta=kwargs["phase2_lambda_theta"],
        lambda_shot=kwargs["phase2_lambda_shot"],
        wD=float(max(0.0, kwargs["phase2_w_depth"])),
        wG=float(max(0.0, kwargs["phase2_w_group"])),
        wC=float(max(0.0, kwargs["phase2_w_shot"])),
        wP=float(max(0.0, kwargs["phase2_w_optdim"])),
        wc=float(max(0.0, kwargs["phase2_w_reuse"])),
        lifetime_weight=float(
            max(0.0, kwargs["phase2_w_lifetime"])
        ),
        eta_L=float(max(0.0, kwargs["phase2_eta_L"])),
        compile_cx_proxy_weight=float(
            kwargs["phase2_compile_cx_proxy_weight"]
        ),
        compile_sq_proxy_weight=float(
            kwargs["phase2_compile_sq_proxy_weight"]
        ),
        compile_rotation_step_weight=float(
            kwargs["phase2_compile_rotation_step_weight"]
        ),
        compile_position_shift_weight=float(
            kwargs["phase2_compile_position_shift_weight"]
        ),
        compile_refit_active_weight=float(
            kwargs["phase2_compile_refit_active_weight"]
        ),
        measure_groups_weight=float(
            kwargs["phase2_measure_groups_weight"]
        ),
        measure_shots_weight=float(
            kwargs["phase2_measure_shots_weight"]
        ),
        measure_reuse_weight=float(
            kwargs["phase2_measure_reuse_weight"]
        ),
        opt_dim_cost_scale=float(kwargs["phase2_opt_dim_cost_scale"]),
        family_repeat_cost_scale=float(
            kwargs["phase2_family_repeat_cost_scale"]
        ),
        motif_bonus_weight=float(
            max(0.0, kwargs["phase2_motif_bonus_weight"])
        ),
        duplicate_penalty_weight=float(
            max(0.0, kwargs["phase2_duplicate_penalty_weight"])
        ),
        shortlist_fraction=float(
            max(0.05, phase2_shortlist_fraction)
        ),
        shortlist_size=int(max(1, phase2_shortlist_size)),
        phase2_frontier_ratio=float(
            max(0.0, min(1.0, kwargs["phase2_frontier_ratio"]))
        ),
        phase3_frontier_ratio=float(
            max(0.0, min(1.0, kwargs["phase3_frontier_ratio"]))
        ),
        batch_target_size=batch_cap,
        batch_size_cap=batch_cap,
        batch_near_degenerate_ratio=0.0,
        auxiliary_score_mode="tie_break_only",
        lifetime_cost_mode=str(kwargs["phase3_lifetime_cost_mode"]),
        remaining_evaluations_proxy_mode=remaining_proxy,
        resource_weighting_scope=str(
            kwargs.get(
                "ra_resource_weighting_scope",
                "all_phase_resource_weighting_v1",
            )
        ),
        active_gradient_policy=str(
            kwargs.get(
                "ra_active_gradient_policy",
                "measured_residual_response_v1",
            )
        ),
        phase3_candidate_gain_policy=str(
            kwargs.get(
                "ra_phase3_candidate_gain_policy",
                PHASE3_CANDIDATE_GAIN_JOINT_TOTAL_V1,
            )
        ),
    )
    require_phase3_signed_factor_consumer_semantic_version(score_cfg)
    return score_cfg


def _default_no_prune_stage_controller(
    kwargs: Mapping[str, Any],
    *,
    lanes: _DefaultNoPruneLaneRuntime,
) -> StageController:
    """Build the exact fresh-start maturity controller."""

    phase1_min = (
        lanes.phase1_shortlist_size
        if kwargs.get("phase1_maturity_cap_min") is None
        else int(kwargs["phase1_maturity_cap_min"])
    )
    phase1_max = (
        lanes.phase1_shortlist_size
        if kwargs.get("phase1_maturity_cap_max") is None
        else int(kwargs["phase1_maturity_cap_max"])
    )
    phase2_min = (
        lanes.phase2_shortlist_size
        if kwargs.get("phase2_maturity_cap_min") is None
        else int(kwargs["phase2_maturity_cap_min"])
    )
    phase2_max = (
        lanes.phase2_shortlist_size
        if kwargs.get("phase2_maturity_cap_max") is None
        else int(kwargs["phase2_maturity_cap_max"])
    )
    phase3_min = (
        lanes.phase3_shortlist_size
        if kwargs.get("phase3_maturity_cap_min") is None
        else int(kwargs["phase3_maturity_cap_min"])
    )
    phase3_max = (
        lanes.phase3_shortlist_size
        if kwargs.get("phase3_maturity_cap_max") is None
        else int(kwargs["phase3_maturity_cap_max"])
    )
    phase1_min, phase1_max = clamp_controller_cap_pair_for_lane_route(
        route=str(kwargs["static_lane_route"]),
        cap_min=phase1_min,
        cap_max=phase1_max,
        effective_cap=lanes.phase1_shortlist_size,
    )
    phase2_min, phase2_max = clamp_controller_cap_pair_for_lane_route(
        route=str(kwargs["static_lane_route"]),
        cap_min=phase2_min,
        cap_max=phase2_max,
        effective_cap=lanes.phase2_shortlist_size,
    )
    phase3_min, phase3_max = clamp_controller_cap_pair_for_lane_route(
        route=str(kwargs["static_lane_route"]),
        cap_min=phase3_min,
        cap_max=phase3_max,
        effective_cap=lanes.phase3_shortlist_size,
    )
    if kwargs.get("adapt_drop_floor") is not None:
        raise ValueError(
            "The characterized default route requires the ordinary epsilon "
            "weak-drop threshold."
        )
    config = StageControllerConfig(
        plateau_patience=int(max(1, kwargs["phase1_plateau_patience"])),
        weak_drop_threshold=float(max(kwargs["eps_energy"], 1.0e-12)),
        probe_margin_ratio=float(
            max(0.0, kwargs["phase1_trough_margin_ratio"])
        ),
        max_probe_positions=int(
            max(1, kwargs["phase1_probe_max_positions"])
        ),
        append_admit_threshold=0.05,
        family_repeat_patience=int(
            max(1, kwargs["phase1_plateau_patience"])
        ),
        cap_phase1_min=int(phase1_min),
        cap_phase1_max=int(phase1_max),
        cap_phase2_min=int(phase2_min),
        cap_phase2_max=int(phase2_max),
        cap_phase3_min=int(phase3_min),
        cap_phase3_max=int(phase3_max),
        shot_min=int(kwargs["phase_maturity_shot_min"]),
        shot_max=int(kwargs["phase_maturity_shot_max"]),
        shot_cap_phase1=int(kwargs["phase1_maturity_shot_cap"]),
        shot_cap_phase2=int(kwargs["phase2_maturity_shot_cap"]),
        shot_cap_phase3=int(kwargs["phase3_maturity_shot_cap"]),
    )
    stage = StageController(config)
    stage.start_with_seed()
    stage.begin_core()
    return stage


def _default_no_prune_backend_compile_oracle(
    *,
    core: _DefaultNoPruneSetupCore,
    kwargs: Mapping[str, Any],
) -> Any | None:
    """Build the active exact backend-cost oracle without global state."""

    config = BackendCompileConfig(
        mode=str(kwargs["phase3_backend_cost_mode"]),
        requested_backend_name=(
            None
            if kwargs.get("phase3_backend_name") in {None, ""}
            else str(kwargs["phase3_backend_name"])
        ),
        requested_backend_shortlist=tuple(
            str(value)
            for value in kwargs["phase3_backend_shortlist"]
        ),
        seed_transpiler=int(kwargs["phase3_backend_transpile_seed"]),
        optimization_level=int(
            kwargs["phase3_backend_optimization_level"]
        ),
        weight_2q=float(kwargs["phase3_backend_w_2q"]),
        weight_depth=float(kwargs["phase3_backend_w_depth"]),
        weight_size=float(kwargs["phase3_backend_w_size"]),
        allow_preferred_fallback=(
            str(kwargs["phase3_backend_cost_mode"])
            != MARRAKESH_GRAPH_SPAN_MODE
        ),
    )
    num_qubits = int(round(np.log2(core.reference_state.size)))
    if str(config.mode) == "proxy":
        return None
    if str(config.mode) == MARRAKESH_GRAPH_SPAN_MODE:
        oracle = MarrakeshGraphSpanCostOracle(
            config=config,
            num_qubits=num_qubits,
            ref_state=core.reference_state,
        )
    else:
        oracle = BackendCompileOracle(
            config=config,
            num_qubits=num_qubits,
            ref_state=core.reference_state,
        )
    if len(getattr(oracle, "targets", ())) == 0:
        raise RuntimeError(
            "The default backend-cost oracle resolved no targets."
        )
    return oracle


def _default_no_prune_staged_qiskit_compile_config(
    *,
    scope: str,
    weight_2q: float,
    weight_depth: float,
    weight_size: float,
) -> BackendCompileConfig:
    """Build the exact FakeMarrakesh config for one staged Qiskit scope."""

    scope_key = str(scope)
    if scope_key not in {
        BACKEND_COMPILE_SCOPE_PHASE123_QISKIT_V1,
        BACKEND_COMPILE_SCOPE_PHASE2_PHASE3_QISKIT_ONLY_V1,
        BACKEND_COMPILE_SCOPE_PHASE3_QISKIT_ONLY_V1,
    }:
        raise ValueError(f"Unknown staged Qiskit compile cost scope: {scope!r}.")
    return BackendCompileConfig(
        mode="transpile_single_v1",
        requested_backend_name="FakeMarrakesh",
        seed_transpiler=7,
        optimization_level=1,
        structure_theta_value=1.0,
        reward_negative_deltas=bool(
            scope_key
            in {
                BACKEND_COMPILE_SCOPE_PHASE123_QISKIT_V1,
                BACKEND_COMPILE_SCOPE_PHASE2_PHASE3_QISKIT_ONLY_V1,
            }
        ),
        allow_preferred_fallback=False,
        one_qubit_coordinate_policy=(
            ONE_QUBIT_COORDINATE_COMPILED_POSITIVE_DELTA_V1
        ),
        weight_2q=float(weight_2q),
        weight_depth=float(weight_depth),
        weight_size=float(weight_size),
    )


def _default_no_prune_phase3_backend_compile_oracle(
    *,
    core: _DefaultNoPruneSetupCore,
    kwargs: Mapping[str, Any],
) -> BackendCompileOracle | None:
    """Build the fail-closed Qiskit oracle for one staged compile scope."""

    scope = str(kwargs["phase3_backend_cost_scope"])
    if scope == BACKEND_COMPILE_SCOPE_SHARED_ALL_PHASES_V1:
        return None
    if scope not in {
        BACKEND_COMPILE_SCOPE_PHASE123_QISKIT_V1,
        BACKEND_COMPILE_SCOPE_PHASE2_PHASE3_QISKIT_ONLY_V1,
        BACKEND_COMPILE_SCOPE_PHASE3_QISKIT_ONLY_V1,
    }:
        raise ValueError(f"Unknown backend compile cost scope: {scope!r}.")
    if (
        str(kwargs["phase3_backend_cost_mode"])
        != MARRAKESH_GRAPH_SPAN_MODE
        or str(kwargs.get("phase3_backend_name")) != "FakeMarrakesh"
        or int(kwargs["phase3_backend_optimization_level"]) != 1
        or int(kwargs["phase3_backend_transpile_seed"]) != 7
        or tuple(kwargs["phase3_backend_shortlist"])
    ):
        raise ValueError(
            "The staged Qiskit selector route requires the Paper-I "
            "Marrakesh graph-span proxy plus exact "
            "FakeMarrakesh transpilation at optimization level 1, seed 7, "
            "with no backend shortlist."
        )
    config = _default_no_prune_staged_qiskit_compile_config(
        scope=scope,
        weight_2q=float(kwargs["phase3_backend_w_2q"]),
        weight_depth=float(kwargs["phase3_backend_w_depth"]),
        weight_size=float(kwargs["phase3_backend_w_size"]),
    )
    oracle = BackendCompileOracle(
        config=config,
        num_qubits=int(round(np.log2(core.reference_state.size))),
        ref_state=core.reference_state,
    )
    targets = tuple(oracle.targets)
    if (
        len(targets) != 1
        or str(targets[0].requested_name) != "FakeMarrakesh"
        or str(targets[0].resolved_name) != "FakeMarrakesh"
        or str(targets[0].resolution_kind) != "fake_exact"
        or not bool(targets[0].using_fake_backend)
    ):
        raise RuntimeError(
            "The staged Qiskit selector oracle could not resolve the "
            "exact local FakeMarrakesh target; fallback is forbidden."
        )
    return oracle


def _default_no_prune_backend_compile_oracle_summary(
    oracle: Any | None,
    *,
    role: str,
) -> dict[str, Any] | None:
    if oracle is None:
        return None
    config = getattr(oracle, "config", None)
    targets = tuple(getattr(oracle, "targets", ()))
    return {
        "schema": "paper_i_selector_backend_compile_oracle_summary_v1",
        "role": str(role),
        "mode": str(getattr(config, "mode", "unknown")),
        "requested_backend_name": getattr(
            config, "requested_backend_name", None
        ),
        "optimization_level": int(
            getattr(config, "optimization_level", 0)
        ),
        "seed_transpiler": int(
            getattr(config, "seed_transpiler", 0)
        ),
        "structure_theta_value": float(
            getattr(config, "structure_theta_value", 1.0)
        ),
        "negative_delta_reward_enabled": bool(
            getattr(config, "reward_negative_deltas", False)
        ),
        "one_qubit_coordinate_policy": str(
            getattr(config, "one_qubit_coordinate_policy", "unknown")
        ),
        "preferred_backend_fallback_allowed": bool(
            getattr(config, "allow_preferred_fallback", False)
        ),
        "targets": [
            {
                "requested_name": str(target.requested_name),
                "resolved_name": str(target.resolved_name),
                "resolution_kind": str(target.resolution_kind),
                "using_fake_backend": bool(target.using_fake_backend),
                "target_snapshot": copy.deepcopy(
                    dict(target.target_snapshot)
                ),
            }
            for target in targets
        ],
        "resolution_audit": [
            copy.deepcopy(dict(row))
            for row in getattr(oracle, "resolution_audit", ())
        ],
        "cache_summary": copy.deepcopy(dict(oracle.cache_summary())),
        "excluded_from_s_alg": True,
    }


def _default_no_prune_selector_compile_cost_accounting(
    *,
    context: Any,
    gradient_phase0_active: bool,
    phase0_cost_source: str | None,
) -> dict[str, Any]:
    """Serialize compile work without adding it to estimator accounting."""

    scope = str(context.backend_compile_scope)
    phase23_qiskit_scope = bool(
        scope == BACKEND_COMPILE_SCOPE_PHASE2_PHASE3_QISKIT_ONLY_V1
    )
    phase123_qiskit_scope = bool(
        scope == BACKEND_COMPILE_SCOPE_PHASE123_QISKIT_V1
    )
    staged_qiskit_scope = bool(
        phase23_qiskit_scope or phase123_qiskit_scope
    )
    if phase123_qiskit_scope:
        qiskit_phases = ["phase_i", "phase_ii", "phase_iii"]
        staged_role = "phase_i_phase_ii_phase_iii"
        phase_i_cost_source = "backend_transpile_v1"
    elif phase23_qiskit_scope:
        qiskit_phases = ["phase_ii", "phase_iii"]
        staged_role = "phase_ii_phase_iii"
        phase_i_cost_source = "structural_proxy_v1"
    elif context.phase3_backend_compile_oracle is not None:
        qiskit_phases = ["phase_iii"]
        staged_role = "phase_iii"
        phase_i_cost_source = None
    else:
        qiskit_phases = []
        staged_role = "phase_iii"
        phase_i_cost_source = None
    return {
        "schema": "paper_i_selector_compile_cost_accounting_v1",
        "scope": scope,
        "phase_i_phase_ii": (
            None
            if staged_qiskit_scope
            else _default_no_prune_backend_compile_oracle_summary(
                context.backend_compile_oracle,
                role="phase_i_phase_ii",
            )
        ),
        "phase_iii": _default_no_prune_backend_compile_oracle_summary(
            context.phase3_backend_compile_oracle,
            role=staged_role,
        ),
        "phase_i_cost_source": phase_i_cost_source,
        "phase0_cost_source": (
            str(phase0_cost_source)
            if gradient_phase0_active and phase0_cost_source is not None
            else None
        ),
        "qiskit_applied_phases": qiskit_phases,
        "phase_iii_reuses_phase_i_phase_ii_oracle": bool(
            context.phase3_backend_compile_oracle is None
        ),
        "excluded_from_s_alg": True,
    }


def _default_no_prune_runtime_split_summary(
    *,
    core: _DefaultNoPruneSetupCore,
    kwargs: Mapping[str, Any],
    child_padding: RouteAChildPaddingConfig,
) -> dict[str, Any]:
    """Return the exact zero-event projected-child runtime summary."""

    subset_sizes = normalize_runtime_split_subset_sizes(
        kwargs["phase3_runtime_split_subset_sizes"]
    )
    padding_active = bool(
        str(child_padding.policy)
        == ROUTE_A_CHILD_PADDING_PROJECTED_GROUPED_V1
    )
    return {
        "mode": str(kwargs["phase3_runtime_split_mode"]),
        "selection_mode": str(
            kwargs["phase3_runtime_split_selection_mode"]
        ),
        "child_set_symmetry_policy": str(
            kwargs[
                "phase3_runtime_split_child_set_symmetry_policy"
            ]
        ),
        "child_padding": child_padding.as_dict(),
        "child_padding_projection_active": padding_active,
        "child_padding_contract": (
            _historical_singleton_child_padding_contract(
                problem_key=str(core.resolved_problem.family_key),
                boson_encoding=str(kwargs["boson_encoding"]),
                n_ph_max=int(kwargs["n_ph_max"]),
                projection_active=padding_active,
            )
        ),
        "requested_subset_sizes": [
            int(size) for size in subset_sizes
        ],
        "subset_size_semantics": (
            "exact_allowed_pauli_word_cardinalities"
        ),
        "subset_sizes_source": "explicit_exact_subset_sizes",
        "requested_max_subset_size": int(max(subset_sizes)),
        "probed_parent_count": 0,
        "evaluated_child_count": 0,
        "rejected_child_count_symmetry": 0,
        "rejected_child_count_padding_zero": 0,
        "deduplicated_child_count_padding": 0,
        "projected_child_count_padding": 0,
        "admissible_child_set_count": 0,
        "probe_parent_win_count": 0,
        "probe_child_set_count": 0,
        "selected_child_set_count": 0,
        "selected_child_count": 0,
        "selected_child_labels": [],
    }


def _default_no_prune_initial_snapshot(
    *,
    core: _DefaultNoPruneSetupCore,
    optimizer_memory: Mapping[str, Any],
    trust_state: RouteATrustRegionState,
) -> _AcceptedStateSnapshot:
    """Project the fresh empty ansatz into the controller's immutable cursor."""

    available_ids: list[str] = []
    selection_counts: list[tuple[str, int]] = []
    for pool_index in sorted(core.available_indices):
        term = core.pool[int(pool_index)]
        metadata = core.pool_generator_registry.get(str(term.label), {})
        generator_id = (
            str(metadata.get("generator_id"))
            if isinstance(metadata, Mapping)
            and metadata.get("generator_id") not in {None, ""}
            else "gen:"
            + _candidate_record_payload_digest(
                {
                    "candidate_label": str(term.label),
                    "pool_index": int(pool_index),
                }
            )[:16]
        )
        controller_generator_id = _default_no_prune_pool_entry_identity(
            generator_id,
            pool_index=int(pool_index),
        )
        available_ids.append(controller_generator_id)
        selection_counts.append(
            (
                controller_generator_id,
                int(core.selection_counts[int(pool_index)]),
            )
        )
    occurrences = _default_no_prune_ledger_occurrences(
        core.estimator_call_ledger
    )
    prefix_count = int(
        core.estimator_prefix_checkpoint_cursor[
            "raw_occurrence_count"
        ]
    )
    return _AcceptedStateSnapshot(
        controller_round=0,
        accepted_operator_ids=(),
        accepted_insertion_positions=(),
        logical_parameter_ids=(),
        logical_parameter_values=(),
        runtime_parameter_ids=(),
        runtime_parameter_values=(),
        accepted_energy=float(core.initial_energy),
        accepted_state_fingerprint=projective_state_fingerprint(
            core.initial_state
        ),
        available_generator_ids=tuple(available_ids),
        selection_counts=tuple(selection_counts),
        trust_state_identity=_candidate_record_payload_digest(
            _candidate_record_cache_jsonable(trust_state)
        ),
        optimizer_memory_identity=_candidate_record_payload_digest(
            _candidate_record_cache_jsonable(optimizer_memory)
        ),
        estimator_prefix_identity=(
            _default_no_prune_estimator_prefix_identity(
                occurrences[:prefix_count]
            )
        ),
    )



def _finish_default_no_prune_numerical_session_initialization(
    *,
    core: _DefaultNoPruneSetupCore,
    validated_exact_kwargs: Mapping[str, Any],
    admission_policy: (
        SingletonAdmission
        | GreedyBatchAdmission
        | CombinatorialBatchAdmission
    ),
) -> _DefaultNoPruneNumericalSession:
    """Finish the exact fresh-start session through ordinary state construction."""

    kwargs = dict(validated_exact_kwargs)
    extensions = kwargs.get("extensions", NO_EXTENSIONS)
    if not isinstance(extensions, Extensions):
        raise TypeError("runtime extensions must be an Extensions value.")
    batch = batch_extension_from_admission(admission_policy)
    if extensions.batch is not None and extensions.batch != batch:
        raise ValueError(
            "Explicit batch extension disagrees with admission policy."
        )
    kwargs["extensions"] = Extensions(
        batch=batch,
        pruning=extensions.pruning,
    )
    _default_no_prune_active_phase_flags(kwargs)
    lanes = _default_no_prune_lane_runtime(
        core=core,
        kwargs=kwargs,
        batch=batch,
    )
    phase1_score = _default_no_prune_simple_score_config(kwargs)
    phase2_score = lanes.phase_shortlist_runtime.phase2_score_cfg
    stage = _default_no_prune_stage_controller(kwargs, lanes=lanes)
    measurement_cache = MeasurementCacheAudit(
        nominal_shots_per_group=1,
        sigma_star=float(
            getattr(phase1_score, "shot_sigma_star", 1.0)
        ),
    )
    measurement_work = (
        ControllerMeasurementWorkAccumulator
        .from_measurement_cache_template(measurement_cache)
    )
    child_padding = _default_no_prune_child_padding_config(kwargs)
    subset_sizes = normalize_runtime_split_subset_sizes(
        kwargs["phase3_runtime_split_subset_sizes"]
    )
    measurement_work_runtime = ControllerMeasurementWorkRecordRuntime(
        pool=tuple(core.pool),
        pool_generator_registry=dict(core.pool_generator_registry),
        phase3_enabled=True,
        pool_symmetry_specs=tuple(core.pool_symmetry_specs),
        problem_key=str(core.resolved_problem.family_key),
        num_sites=int(kwargs["num_sites"]),
        ordering=str(kwargs["ordering"]),
        qpb=int(max(1, core.qpb)),
        phase3_runtime_split_mode_key=str(
            kwargs["phase3_runtime_split_mode"]
        ),
        phase3_runtime_split_selection_mode_key=str(
            kwargs["phase3_runtime_split_selection_mode"]
        ),
        phase3_runtime_split_child_set_symmetry_policy_key=str(
            kwargs[
                "phase3_runtime_split_child_set_symmetry_policy"
            ]
        ),
        phase3_runtime_split_max_subset_size_value=int(
            max(subset_sizes)
        ),
        phase3_runtime_split_subset_sizes_value=tuple(subset_sizes),
        fixed_num_particles=_runtime_split_fixed_num_particles(
            problem_key=str(core.resolved_problem.family_key),
            num_particles=(
                core.resolved_problem.sector.num_particles
                if core.resolved_problem.sector.num_particles is not None
                else core.resolved_problem.default_num_particles
            ),
        ),
        child_padding_config=child_padding,
    )
    memory_adapter = Phase2OptimizerMemoryAdapter()
    optimizer_memory = memory_adapter.unavailable(
        method=str(kwargs["adapt_inner_optimizer"]).strip().upper(),
        parameter_count=0,
        reason="pre_seed_state",
    )
    trust_update = TrustRegionUpdateConfig(
        policy=str(
            kwargs["historical_singleton_trust_region_update_policy"]
        ).strip().lower()
    )
    trust_state = initialize_trust_region_state(
        initial_radius=float(kwargs["phase2_rho"]),
        checkpoint_payload=None,
    )
    parameterization_mode = _resolve_selected_parameterization_mode(
        problem_key_value=str(core.resolved_problem.family_key),
        pool_key_value=str(kwargs["adapt_pool"]),
        candidate_terms=core.pool,
        sector_contract_requires_logical_shared=False,
    )
    if (
        str(core.resolved_problem.family_key) == "hh"
        and str(kwargs["phase3_runtime_split_mode"]) != "off"
    ):
        parameterization_mode = "logical_shared"
    estimator_service = _DefaultNoPruneEstimatorService(
        ledger=core.estimator_call_ledger,
        hamiltonian_fingerprint=(
            core.estimator_hamiltonian_fingerprint
        ),
        backend_fingerprint=core.estimator_backend_fingerprint,
        precision_contract=core.estimator_precision_contract,
        parameterization_mode=parameterization_mode,
        pool=tuple(core.pool),
        pool_family_ids=tuple(core.pool_family_ids),
        phase1_residual_indices=frozenset(
            core.phase1_residual_indices
        ),
    )
    candidate_sector_auditor = _DefaultNoPruneCandidateSectorAuditor(
        resolved_problem=core.resolved_problem,
        parameterization_mode=str(parameterization_mode),
        runtime_split_selection_mode=str(
            kwargs["phase3_runtime_split_selection_mode"]
        ),
        runtime_split_symmetry_policy=str(
            kwargs[
                "phase3_runtime_split_child_set_symmetry_policy"
            ]
        ),
        num_particles=(
            int(core.num_particles[0]),
            int(core.num_particles[1]),
        ),
        global_guarded_singleton_identity_exposure=bool(
            isinstance(
                core.route_contract.get("semantic_invariants"),
                Mapping,
            )
            and core.route_contract["semantic_invariants"].get(
                "phase_i_candidate_supply"
            )
            == "global_guarded_singleton_pool_v1"
            and core.route_contract["semantic_invariants"].get(
                "phase_ii_candidate_exposure"
            )
            == "identity_on_retained_singletons_v1"
        ),
    )
    state_service = _DefaultNoPruneStateService(
        reference_state=core.reference_state.copy(),
        state_backend=str(kwargs["adapt_state_backend"]),
        parameterization_mode=str(parameterization_mode),
        pauli_action_cache=core.pauli_action_cache,
        fixed_count_auditor=FixedCountSectorStateAuditor(
            core.resolved_problem
        ),
    )
    optimizer_config = resolve_adapt_inner_optimizer_config(
        adapt_inner_optimizer=str(kwargs["adapt_inner_optimizer"]),
        adapt_scipy_maxfev=int(kwargs["adapt_scipy_maxfev"]),
        adapt_spsa_a=float(kwargs["adapt_spsa_a"]),
        adapt_spsa_c=float(kwargs["adapt_spsa_c"]),
        adapt_spsa_alpha=float(kwargs["adapt_spsa_alpha"]),
        adapt_spsa_gamma=float(kwargs["adapt_spsa_gamma"]),
        adapt_spsa_A=float(kwargs["adapt_spsa_A"]),
        adapt_spsa_avg_last=int(kwargs["adapt_spsa_avg_last"]),
        adapt_spsa_eval_repeats=int(
            kwargs["adapt_spsa_eval_repeats"]
        ),
        adapt_spsa_eval_agg=str(kwargs["adapt_spsa_eval_agg"]),
        adapt_spsa_callback_every=int(
            kwargs["adapt_spsa_callback_every"]
        ),
        adapt_spsa_progress_every_s=float(
            kwargs["adapt_spsa_progress_every_s"]
        ),
        adapt_spsa_parallel_evaluations=int(
            kwargs["adapt_spsa_parallel_evaluations"]
        ),
    )
    recoverability_prune_config = _default_recoverability_prune_config(
        kwargs
    )
    controller_noise_runtime = _pure_hubbard_controller_noise_runtime(
        core=core
    )
    candidate_record_cache_mode = _candidate_record_cache_mode()
    if (
        controller_noise_runtime is not None
        and candidate_record_cache_mode != "off"
    ):
        controller_noise_runtime.oracle_context.cleanup_guard.close()
        raise ValueError(
            "The named pure-Hubbard sequential-noise route requires "
            "STATIC_ADAPT_CANDIDATE_RECORD_CACHE=off so no cache hit can "
            "skip a value-noise draw."
        )
    transition_services = _DefaultNoPruneTransitionServices(
        state_service=state_service,
        compiled_hamiltonian=core.compiled_hamiltonian,
        accepted_refit_config=AcceptedRefitConfig(
            scope=str(kwargs["adapt_accepted_refit_scope"]),
            coordinate_chart=str(
                kwargs["adapt_accepted_refit_coordinate_chart"]
            ),
            base_chart_policy=str(
                kwargs["adapt_accepted_refit_base_chart_policy"]
            ),
        ),
        estimator_service=estimator_service,
        optimizer_dispatch=AdaptInnerOptimizerDispatch(
            optimizer_config
        ),
        allow_repeats=bool(kwargs["allow_repeats"]),
        eps_energy=float(kwargs["eps_energy"]),
        maximum_iterations=int(kwargs["maxiter"]),
        controller_noise_runtime=controller_noise_runtime,
        joint_response_warm_start=RouteAJointStepWarmStartConfig(
            mode=str(
                kwargs.get(
                    "ra_accepted_refit_initialization_policy",
                    "off",
                )
            )
        ),
    )
    if kwargs.get("phase3_oracle_gradient_config") is not None:
        raise ValueError(
            "The characterized exact default route has no external phase-III "
            "oracle resource."
        )
    backend_compile_oracle = _default_no_prune_backend_compile_oracle(
        core=core,
        kwargs=kwargs,
    )
    phase3_backend_compile_oracle = (
        _default_no_prune_phase3_backend_compile_oracle(
            core=core,
            kwargs=kwargs,
        )
    )
    selector_metadata = SelectorFeatureMetadataContext(
        static_lane_route=str(kwargs["static_lane_route"]),
        static_lane_route_lane_key=str(lanes.lane_spec.lane_key),
        static_lane_route_lanes=tuple(
            str(lane) for lane in lanes.lane_spec.lanes
        ),
        physical_operator_lane_classifier_version=str(
            _physical_operator_classifier_version_for_problem(
                str(kwargs["problem"])
            )
        ),
        phase1_shortlist_size_base=int(
            kwargs["phase1_shortlist_size"]
        ),
        phase1_shortlist_size_effective=(
            lanes.phase1_shortlist_size
        ),
        phase2_shortlist_size_base=int(
            kwargs["phase2_shortlist_size"]
        ),
        phase2_shortlist_size_effective=(
            lanes.phase2_shortlist_size
        ),
        phase2_shortlist_fraction_base=float(
            kwargs["phase2_shortlist_fraction"]
        ),
        phase2_shortlist_fraction_effective=(
            lanes.phase2_shortlist_fraction
        ),
        physical_lane_shortlist_aggressiveness=int(
            kwargs.get("physical_lane_shortlist_aggressiveness", 1)
        ),
        cache_jsonable=_candidate_record_cache_jsonable,
        validate_nested_window=validate_nested_window,
    )
    selector_candidate_metadata = SelectorCandidateMetadataContext(
        static_lane_route=str(kwargs["static_lane_route"]),
        problem_key=str(core.resolved_problem.family_key),
        physical_operator_lane_summary=(
            lanes.physical_operator_lane_summary
        ),
        physical_operator_lane_classifier_version=str(
            _physical_operator_classifier_version_for_problem(
                str(kwargs["problem"])
            )
        ),
        phase3_selector_policy=str(kwargs["phase3_selector_policy"]),
        phase3_geometry_window_size=int(
            kwargs["phase3_geometry_window_size"]
        ),
        phase3_response_coordinate_scope=str(
            kwargs["phase3_response_coordinate_scope"]
        ),
    )
    adapter_candidate_records_by_label = {
        str(getattr(candidate, "label", "")): candidate
        for candidate in core.adapter_candidate_records
    }
    if len(adapter_candidate_records_by_label) != len(
        core.adapter_candidate_records
    ):
        raise RuntimeError(
            "The RA-ADAPT candidate adapter executable pool contains "
            "duplicate labels."
        )
    context = _DefaultNoPruneKernelContext(
        hamiltonian=kwargs["h_poly"],
        compiled_hamiltonian=core.compiled_hamiltonian,
        compiled_pool=tuple(core.compiled_pool),
        pool=tuple(core.pool),
        pool_family_ids=tuple(core.pool_family_ids),
        pool_symmetry_specs=tuple(core.pool_symmetry_specs),
        phase1_residual_indices=frozenset(
            core.phase1_residual_indices
        ),
        reference_state=core.reference_state.copy(),
        state_service=state_service,
        transition_services=transition_services,
        admission_policy=admission_policy,
        resolved_problem=core.resolved_problem,
        candidate_adapter=core.candidate_adapter,
        adapter_candidate_records_by_label=(
            adapter_candidate_records_by_label
        ),
        problem_key=str(core.resolved_problem.family_key),
        route_profile=str(kwargs["sr_route_profile_resolved"]),
        route_contract=dict(core.route_contract),
        route_contract_sha256=str(
            kwargs["sr_route_profile_contract_sha256"]
        ),
        parameterization_mode=str(parameterization_mode),
        parameterization_mode_source="generator_sector_contract",
        optimizer_powell_coordinate_chart_policy=str(
            kwargs["sr_powell_coordinate_chart_policy"]
        ),
        generator_sector_contract=dict(
            core.generator_sector_contract
        ),
        no_prune_summary_template=(
            _default_no_prune_prune_summary_template(
                kwargs=kwargs,
                parameterization_mode=str(parameterization_mode),
            )
        ),
        state_backend=str(kwargs["adapt_state_backend"]),
        optimizer_name=str(kwargs["adapt_inner_optimizer"]),
        optimizer_maximum_iterations=int(kwargs["maxiter"]),
        controller_measurement_work_runtime=measurement_work_runtime,
        historical_singleton_coordinate_solve_policy=str(
            kwargs["historical_singleton_coordinate_solve_policy"]
        ).strip().lower(),
        historical_singleton_phase3_coordinate_scope=(
            "historical_singleton_supported_projection"
        ),
        historical_singleton_trust_update_config=trust_update,
        escape_mode=SREscapeMode(
            str(kwargs["sr_escape_mode"]).strip().lower()
        ),
        phase_shortlist_runtime=lanes.phase_shortlist_runtime,
        phase123_shortlist_policy=(
            str(
                dict(
                    core.route_contract.get(
                        "execution_settings",
                        {},
                    )
                ).get("ra_phase123_shortlist_policy", "")
            )
            or None
        ),
        phase1_score_config=phase1_score,
        phase3_shortlist_size=lanes.phase3_shortlist_size,
        active_gradient_recorder=(
            estimator_service._record_active_gradient_primitives
        ),
        phase1_score_mode=str(
            normalize_phase1_score_mode(kwargs["phase1_score_mode"])
        ),
        phase1_shortlist_size=int(lanes.phase1_shortlist_size),
        phase3_symmetry_mitigation_mode=str(
            kwargs["phase3_symmetry_mitigation_mode"]
        ),
        phase3_geometry_window_size=int(
            kwargs["phase3_geometry_window_size"]
        ),
        phase3_response_coordinate_scope=str(
            kwargs["phase3_response_coordinate_scope"]
        ),
        phase3_lifetime_cost_mode=str(
            kwargs["phase3_lifetime_cost_mode"]
        ),
        reoptimization_policy=str(kwargs["adapt_reopt_policy"]),
        reoptimization_window_size=int(kwargs["adapt_window_size"]),
        reoptimization_window_topk=int(kwargs["adapt_window_topk"]),
        phase3_runtime_split_mode=str(
            kwargs["phase3_runtime_split_mode"]
        ),
        phase3_runtime_split_selection_mode=str(
            kwargs["phase3_runtime_split_selection_mode"]
        ),
        phase3_runtime_split_child_set_symmetry_policy=str(
            kwargs[
                "phase3_runtime_split_child_set_symmetry_policy"
            ]
        ),
        phase3_runtime_split_subset_sizes=tuple(subset_sizes),
        num_sites=int(kwargs["num_sites"]),
        n_ph_max=int(kwargs["n_ph_max"]),
        boson_encoding=str(kwargs["boson_encoding"]),
        ordering=str(kwargs["ordering"]),
        qpb=int(core.qpb),
        num_particles=(
            int(core.num_particles[0]),
            int(core.num_particles[1]),
        ),
        route_a_child_padding_config=child_padding,
        parallel_gradient_workers=max(
            1, int(kwargs["adapt_parallel_gradient_workers"])
        ),
        candidate_record_cache_mode=(
            candidate_record_cache_mode
        ),
        candidate_record_cache_dir=_candidate_record_cache_dir(),
        candidate_record_cache_static_key=(
            _candidate_record_payload_digest(
                {
                    "schema": _CANDIDATE_RECORD_CACHE_SCHEMA,
                    "code_version": _CANDIDATE_RECORD_CACHE_CODE_VERSION,
                    "problem": str(kwargs["problem"]),
                    "pool": str(kwargs["adapt_pool"]),
                    "route_profile": str(
                        kwargs["sr_route_profile_resolved"]
                    ),
                    "route_contract_sha256": str(
                        kwargs["sr_route_profile_contract_sha256"]
                    ),
                    "hamiltonian": _polynomial_signature_digest(
                        kwargs["h_poly"]
                    ),
                    "reference_state": (
                        _candidate_record_array_fingerprint(
                            core.reference_state
                        )
                    ),
                    "phase1_score_cfg": (
                        _candidate_record_cache_jsonable(phase1_score)
                    ),
                    "phase2_score_cfg": (
                        _candidate_record_cache_jsonable(phase2_score)
                    ),
                }
            )
        ),
        max_depth=int(kwargs["max_depth"]),
        phase3_enabled=True,
        historical_paper_i_route_compat=bool(
            lanes.shortlist_budget_contract[
                "historical_paper_i_contract_active"
            ]
        ),
        phase1_compile_oracle=Phase1CompileCostOracle(),
        backend_compile_scope=str(kwargs["phase3_backend_cost_scope"]),
        backend_compile_oracle=backend_compile_oracle,
        phase3_backend_compile_oracle=phase3_backend_compile_oracle,
        selector_feature_metadata=selector_metadata,
        selector_candidate_metadata=selector_candidate_metadata,
        phase2_compiled_term_cache={},
        phase2_novelty_oracle=OrderedInsertionGeometryOracle(),
        phase2_curvature_oracle=Phase2CurvatureOracle(),
        phase2_memory_adapter=memory_adapter,
        phase3_input_motif_library=None,
        phase3_proxy_selector_geometry_enabled=False,
        phase3_shadow_legacy_geometry_enabled=False,
        phase3_shadow_legacy_geometry_mode_key="off",
        phase3_shadow_legacy_max_depth_val=0,
        route_a_funnel_cfg=None,
        phase2_curvature_policy=str(
            normalize_phase2_curvature_policy(
                kwargs["phase2_curvature_policy"]
            )
        ),
        checkpoint_path=(
            None
            if kwargs["adapt_current_json"] is None
            else Path(kwargs["adapt_current_json"])
        ),
        checkpoint_cadence=max(
            1, int(kwargs["adapt_current_json_every_depth"])
        ),
        checkpoint_history_tail=max(
            0, int(kwargs["adapt_current_json_keep_history_tail"])
        ),
        estimator_service=estimator_service,
        oracle_cleanup=(
            None
            if controller_noise_runtime is None
            else controller_noise_runtime.oracle_context.cleanup_guard
        ),
        recoverability_prune_config=recoverability_prune_config,
    )
    cursor = _DefaultNoPruneNumericalCursor(
        controller_round=0,
        selected_ops=[],
        selected_operator_metadata=[],
        theta=np.zeros(0, dtype=float),
        selected_layout=core.initial_layout,
        selected_executor=None,
        accepted_energy=float(core.initial_energy),
        available_indices=set(core.available_indices),
        selection_counts=np.asarray(
            core.selection_counts, dtype=np.int64
        ).copy(),
        history=[],
        nfev_total=1,
        phase1_stage=stage,
        phase1_measure_cache=measurement_cache,
        controller_measurement_work=measurement_work,
        phase2_optimizer_memory=dict(optimizer_memory),
        route_a_trust_region_state=trust_state,
        estimator_call_ledger=core.estimator_call_ledger,
        estimator_prefix_checkpoint_cursor=copy.deepcopy(
            dict(core.estimator_prefix_checkpoint_cursor)
        ),
        estimator_active_prefix_ledger_receipts_all=[
            copy.deepcopy(dict(receipt))
            for receipt in core.estimator_active_prefix_ledger_receipts_all
        ],
        pool_generator_registry={
            str(label): dict(metadata)
            for label, metadata in core.pool_generator_registry.items()
        },
        phase3_last_candidate_gradient_scout=[],
        phase3_last_max_gradient_stderr=0.0,
        phase3_oracle_gradient_calls_total=0,
        phase3_runtime_split_summary=(
            _default_no_prune_runtime_split_summary(
                core=core,
                kwargs=kwargs,
                child_padding=child_padding,
            )
        ),
        pauli_action_cache=core.pauli_action_cache,
        phase12_energy_model_telemetry={
            "schema": "sr_snake_phase12_energy_model_runtime_v1",
            "phase1_score_mode": str(
                normalize_phase1_score_mode(
                    kwargs["phase1_score_mode"]
                )
            ),
            "phase1_energy_model": str(
                normalize_phase1_energy_model(
                    kwargs["phase1_energy_model"]
                )
            ),
            "phase2_curvature_policy": str(
                normalize_phase2_curvature_policy(
                    kwargs["phase2_curvature_policy"]
                )
            ),
            "phase2_cheap_curvature_proxy_policy": str(
                normalize_phase2_cheap_curvature_proxy_policy(
                    kwargs["phase2_cheap_curvature_proxy_policy"]
                )
            ),
            "phase2_full_candidate_occurrences": 0,
            "validated_phase2_curvature_receipt_occurrences": 0,
            "candidate_cache_hit_validated_receipt_occurrences": 0,
        },
        phase12_energy_model_telemetry_lock=Lock(),
        initial_outer_measurement_cache=(
            core.initial_state.copy(),
            float(core.initial_energy),
            core.initial_hamiltonian_state.copy(),
        ),
        prune_trust_state=(
            initialize_affine_deletion_fs_trust_state(
                radius=float(
                    recoverability_prune_config.initial_radius
                )
            )
            if recoverability_prune_config is not None
            else None
        ),
        operator_admission_rounds=[],
        # The named noisy route establishes its incumbent only after the
        # selected zero-angle generator has been inserted, so it is measured
        # on the same circuit optimized by Powell.  Keeping this empty also
        # lets resume hydration restore RNG state before any new draw.
        controller_energy=None,
    )
    initial_snapshot = _default_no_prune_initial_snapshot(
        core=core,
        optimizer_memory=optimizer_memory,
        trust_state=trust_state,
    )
    return _DefaultNoPruneNumericalSession(
        context=context,
        cursor=cursor,
        estimator_service=estimator_service,
        candidate_sector_auditor=candidate_sector_auditor,
        initial_accepted_state=initial_snapshot,
    )


def _initialize_default_no_prune_numerical_session(
    validated_exact_kwargs: Mapping[str, Any],
    *,
    admission_policy: (
        SingletonAdmission
        | GreedyBatchAdmission
        | CombinatorialBatchAdmission
    ),
    candidate_adapter: Any | None = None,
) -> _DefaultNoPruneNumericalSession:
    """Build an unprepared exact-route session from ordinary typed state."""

    core = _build_default_no_prune_setup_core(
        validated_exact_kwargs,
        admission_policy=admission_policy,
        candidate_adapter=candidate_adapter,
    )
    return _finish_default_no_prune_numerical_session_initialization(
        core=core,
        validated_exact_kwargs=validated_exact_kwargs,
        admission_policy=admission_policy,
    )


def _default_no_prune_resume_mutable_json(value: Any) -> Any:
    """Thaw one recursively frozen JSON value from the resume adapter."""

    if isinstance(value, Mapping):
        return {
            str(key): _default_no_prune_resume_mutable_json(item)
            for key, item in value.items()
        }
    if isinstance(value, Sequence) and not isinstance(
        value,
        (str, bytes),
    ):
        return [
            _default_no_prune_resume_mutable_json(item)
            for item in value
        ]
    return value


def _hydrate_default_no_prune_numerical_session(
    session: _DefaultNoPruneNumericalSession,
    hydration: Any,
) -> _DefaultNoPruneNumericalSession:
    """Restore one authenticated accepted prefix into the direct session."""

    from pipelines.static_adapt.sr_snake._resume import (
        CanonicalAcceptedStateHydration,
    )

    if not isinstance(hydration, CanonicalAcceptedStateHydration):
        raise TypeError(
            "resume_hydration must be CanonicalAcceptedStateHydration."
        )
    if (
        hydration.route_profile != session.context.route_profile
        or hydration.route_contract_sha256
        != session.context.route_contract_sha256
    ):
        raise ValueError(
            "Authenticated resume route differs from the direct session."
        )
    total_qubits = int(
        session.context.resolved_problem.layout.total_qubits
    )
    operators: list[AnsatzTerm] = []
    operator_metadata: list[dict[str, Any]] = []
    generator_registry = copy.deepcopy(
        session.cursor.pool_generator_registry
    )
    terminal_checkpoint = (
        hydration.mutable_terminal_signed_checkpoint()
    )
    controller_noise_runtime = (
        session.context.transition_services.controller_noise_runtime
    )
    restored_controller_energy: float | None = None
    if controller_noise_runtime is not None:
        controller_noise_checkpoint = terminal_checkpoint.get(
            "controller_noise"
        )
        if not isinstance(controller_noise_checkpoint, Mapping):
            raise RuntimeError(
                "Authenticated pure-Hubbard resume lacks controller-noise "
                "state."
            )
        controller_noise_runtime.restore_checkpoint_receipt(
            controller_noise_checkpoint
        )
        restored_controller_energy = float(
            controller_noise_checkpoint["controller_energy"]
        )
        restored_exact_diagnostic_energy = float(
            controller_noise_checkpoint["exact_diagnostic_energy"]
        )
        if (
            not math.isfinite(restored_controller_energy)
            or not math.isfinite(restored_exact_diagnostic_energy)
            or not math.isclose(
                restored_exact_diagnostic_energy,
                float(hydration.accepted_energy),
                rel_tol=0.0,
                abs_tol=1.0e-9,
            )
        ):
            raise RuntimeError(
                "Authenticated controller-noise checkpoint does not close "
                "over its noisy incumbent and exact accepted-state energy."
            )
    serialized_operator_rows = terminal_checkpoint.get(
        "ordered_active_operators",
        (),
    )
    if (
        not isinstance(serialized_operator_rows, Sequence)
        or isinstance(serialized_operator_rows, (str, bytes))
        or len(serialized_operator_rows) != len(hydration.operators)
    ):
        raise RuntimeError(
            "Authenticated resume operator metadata is incomplete."
        )
    for hydrated_operator, serialized_operator_row_raw in zip(
        hydration.operators,
        serialized_operator_rows,
        strict=True,
    ):
        if not isinstance(serialized_operator_row_raw, Mapping):
            raise RuntimeError(
                "Authenticated resume operator metadata is not a mapping."
            )
        serialized_operator_row = copy.deepcopy(
            dict(serialized_operator_row_raw)
        )
        terms = [
            PauliTerm(
                int(term.qubit_count),
                ps=str(term.pauli_exyz),
                pc=complex(
                    float(term.coefficient_real),
                    float(term.coefficient_imaginary),
                ),
            )
            for term in hydrated_operator.runtime_terms
        ]
        if (
            not terms
            or any(int(term.nqubit()) != total_qubits for term in terms)
        ):
            raise RuntimeError(
                "Authenticated resume operator has an invalid qubit width."
            )
        operator = AnsatzTerm(
            label=str(hydrated_operator.label),
            polynomial=PauliPolynomial("JW", terms),
            execution_mode=str(hydrated_operator.execution_mode),
        )
        operators.append(operator)
        metadata = (
            _default_no_prune_generator_metadata_from_term(operator)
            or {}
        )
        metadata = copy.deepcopy(dict(metadata))
        metadata["generator_id"] = str(
            hydrated_operator.generator_id
        )
        metadata["parent_generator_id"] = (
            None
            if hydrated_operator.parent_generator_id is None
                else str(hydrated_operator.parent_generator_id)
            )
        retained_parent_owner = serialized_operator_row.get(
            "ra_retained_parent_owner"
        )
        if isinstance(retained_parent_owner, Mapping):
            metadata["ra_retained_parent_owner"] = (
                copy.deepcopy(dict(retained_parent_owner))
            )
        compile_metadata = metadata.get("compile_metadata")
        compile_metadata = (
            copy.deepcopy(dict(compile_metadata))
            if isinstance(compile_metadata, Mapping)
            else {}
        )
        serialized_terms = copy.deepcopy(
            serialized_operator_row[
                "serialized_terms_exyz_in_execution_order"
            ]
        )
        compile_metadata["serialized_terms_exyz"] = serialized_terms
        compile_metadata["runtime_terms_exyz"] = copy.deepcopy(
            serialized_terms
        )
        for key in (
            "runtime_split",
            "symmetry_gate",
            "route_a_child_padding_lineage",
        ):
            value = serialized_operator_row.get(key)
            if isinstance(value, Mapping):
                compile_metadata[key] = copy.deepcopy(dict(value))
        metadata["compile_metadata"] = compile_metadata
        operator_metadata.append(copy.deepcopy(metadata))
        generator_registry[str(operator.label)] = metadata

    layout = session.context.transition_services.build_selected_layout(
        operators
    )
    observed_parameterization = serialize_layout(layout)
    expected_parameterization = hydration.mutable_parameterization()
    if observed_parameterization != expected_parameterization:
        raise RuntimeError(
            "Authenticated resume parameterization cannot be reconstructed "
            "by the active direct session."
        )
    runtime_theta = np.asarray(
        hydration.runtime_parameters,
        dtype=float,
    )
    if runtime_theta.size != int(layout.runtime_parameter_count):
        raise RuntimeError(
            "Authenticated resume runtime coordinates have the wrong size."
        )
    logical_theta = np.asarray(
        _logical_theta_alias(runtime_theta, layout),
        dtype=float,
    )
    if tuple(float(value) for value in logical_theta) != tuple(
        hydration.logical_parameters
    ):
        raise RuntimeError(
            "Authenticated resume logical coordinates changed during "
            "reconstruction."
        )
    executor = (
        session.context.state_service.build_executor(operators)
        if session.context.state_backend == "compiled" and operators
        else None
    )
    state = session.context.state_service.prepare(
        operators=operators,
        theta=runtime_theta,
        executor=executor,
        layout=layout,
    )
    serialized_state_fingerprint = (
        estimator_projective_state_fingerprint(state)
    )
    if (
        serialized_state_fingerprint
        != hydration.accepted_state_fingerprint
    ):
        raise RuntimeError(
            "Authenticated resume strict numerical replay fingerprint "
            "changed."
        )
    state_fingerprint = projective_state_fingerprint(state)
    replay_energy, _ = energy_via_one_apply(
        state,
        session.context.compiled_hamiltonian,
    )
    if not math.isclose(
        float(replay_energy),
        float(hydration.accepted_energy),
        rel_tol=0.0,
        abs_tol=1.0e-9,
    ):
        raise RuntimeError(
            "Authenticated resume numerical replay energy changed."
        )
    session.context.state_service.fixed_count_auditor.assert_valid(
        state,
        source="canonical_accepted_state_resume",
    )
    session.candidate_sector_auditor.active_contract(
        operators,
        generator_registry=generator_registry,
        source="canonical_accepted_state_resume",
    )

    restored_ledger = EstimatorCallLedger.from_payload(
        hydration.mutable_estimator_call_ledger_payload()
    )
    occurrences = _default_no_prune_ledger_occurrences(restored_ledger)
    prefix_cursor = _default_no_prune_resume_mutable_json(
        hydration.estimator_prefix_checkpoint_cursor
    )
    if int(prefix_cursor["raw_occurrence_count"]) != len(occurrences):
        raise RuntimeError(
            "Authenticated resume estimator cursor does not close to its "
            "ledger."
        )
    if int(hydration.s_alg) != len(occurrences):
        raise RuntimeError(
            "Authenticated resume S_alg does not equal its occurrence stream."
        )
    session.estimator_service.ledger = restored_ledger
    session.cursor.estimator_call_ledger = restored_ledger
    session.cursor.estimator_prefix_checkpoint_cursor = prefix_cursor
    session.cursor.estimator_active_prefix_ledger_receipts_all = [
        _default_no_prune_resume_mutable_json(receipt)
        for receipt in hydration.active_prefix_estimator_receipts
    ]

    trust_payload = _default_no_prune_resume_mutable_json(
        hydration.route_a_trust_region_state
    )
    trust_state = RouteATrustRegionState(
        radius=float(trust_payload["radius"]),
        reference_radius=float(trust_payload["reference_radius"]),
        update_count=int(trust_payload["update_count"]),
        last_update=(
            copy.deepcopy(dict(trust_payload["last_update"]))
            if isinstance(trust_payload.get("last_update"), Mapping)
            else None
        ),
        initialization_reason=str(
            trust_payload["initialization_reason"]
        ),
    )
    optimizer_memory = (
        session.context.phase2_memory_adapter.unavailable(
            method="POWELL",
            parameter_count=int(runtime_theta.size),
            reason="non_spsa_depth_opt",
        )
    )
    stage = session.cursor.phase1_stage
    stage.begin_core()
    history = hydration.mutable_history()
    for row in history:
        stage_energy_before = float(row["energy_before_opt"])
        stage_energy_after = float(row["energy_after_opt"])
        if controller_noise_runtime is not None:
            controller_transition = row.get("controller_noise")
            if not isinstance(controller_transition, Mapping):
                raise RuntimeError(
                    "Authenticated pure-Hubbard resume history lacks its "
                    "controller-noise transition."
                )
            stage_energy_before = float(
                controller_transition["controller_energy_before"]
            )
            stage_energy_after = float(
                controller_transition["controller_energy_after"]
            )
        stage.record_admission(
            selector_step=int(row["depth"]),
            energy_before=stage_energy_before,
            energy_after_refit=stage_energy_after,
        )
    maturity_snapshot = PhaseControllerSnapshot(
        **_default_no_prune_resume_mutable_json(
            hydration.maturity_controller_snapshot
        )
    )
    stage_snapshot = stage.snapshot()
    stage_snapshot.update(
        {
            "stage": "core",
            "last_snapshot": maturity_snapshot,
        }
    )
    stage = StageController.from_snapshot(stage_snapshot)
    measurement_cache = session.cursor.phase1_measure_cache
    for operator in operators:
        measurement_cache.commit(
            measurement_group_specs_for_term(operator)
        )

    prune_state = hydration.prune_trust_state
    if session.context.recoverability_prune_config is not None:
        if prune_state is None:
            raise RuntimeError(
                "Pruning-enabled resume lacks its authenticated prune state."
            )
        restored_prune_state: AffineDeletionFSTrustState | None = (
            AffineDeletionFSTrustState(
                radius=float(prune_state.radius),
                metric_damping=float(prune_state.metric_damping),
                update_count=int(prune_state.update_count),
            )
        )
    else:
        restored_prune_state = None

    selection_counts = np.asarray(
        hydration.selection_counts_by_pool_index,
        dtype=np.int64,
    )
    if selection_counts.shape != session.cursor.selection_counts.shape:
        raise RuntimeError(
            "Authenticated resume selection counts do not match the active "
            "candidate pool."
        )
    available_indices = {
        int(value) for value in hydration.available_pool_indices
    }
    expected_available_ids: list[str] = []
    selected_count_rows: list[tuple[str, int]] = []
    for pool_index, pool_operator in enumerate(session.context.pool):
        generator_id = _default_no_prune_operator_identity(
            pool_operator,
            pool_generator_registry=generator_registry,
        )
        controller_id = _default_no_prune_pool_entry_identity(
            generator_id,
            pool_index=int(pool_index),
        )
        if pool_index in available_indices:
            expected_available_ids.append(controller_id)
        selected_count_rows.append(
            (controller_id, int(selection_counts[pool_index]))
        )
    estimator_prefix_identity = (
        _default_no_prune_estimator_prefix_identity(occurrences)
    )
    accepted_snapshot = _AcceptedStateSnapshot(
        controller_round=int(hydration.controller_round),
        accepted_operator_ids=tuple(
            str(operator.generator_id)
            for operator in hydration.operators
        ),
        accepted_insertion_positions=tuple(range(len(operators))),
        logical_parameter_ids=tuple(
            f"logical:{index}"
            for index in range(int(logical_theta.size))
        ),
        logical_parameter_values=tuple(
            float(value) for value in logical_theta
        ),
        runtime_parameter_ids=tuple(
            f"runtime:{index}"
            for index in range(int(runtime_theta.size))
        ),
        runtime_parameter_values=tuple(
            float(value) for value in runtime_theta
        ),
        accepted_energy=float(hydration.accepted_energy),
        accepted_state_fingerprint=state_fingerprint,
        available_generator_ids=tuple(expected_available_ids),
        selection_counts=tuple(selected_count_rows),
        trust_state_identity=_candidate_record_payload_digest(
            _candidate_record_cache_jsonable(trust_state)
        ),
        optimizer_memory_identity=_candidate_record_payload_digest(
            _candidate_record_cache_jsonable(optimizer_memory)
        ),
        estimator_prefix_identity=estimator_prefix_identity,
    )

    session.cursor.controller_round = int(hydration.controller_round)
    session.cursor.selected_ops = operators
    session.cursor.selected_operator_metadata = operator_metadata
    session.cursor.theta = runtime_theta.copy()
    session.cursor.selected_layout = layout
    session.cursor.selected_executor = executor
    session.cursor.accepted_energy = float(hydration.accepted_energy)
    session.cursor.controller_energy = restored_controller_energy
    session.cursor.available_indices = available_indices
    session.cursor.selection_counts = selection_counts
    session.cursor.history = history
    session.cursor.nfev_total = int(hydration.nfev_total)
    session.cursor.phase1_stage = stage
    session.cursor.phase2_optimizer_memory = optimizer_memory
    session.cursor.route_a_trust_region_state = trust_state
    session.cursor.pool_generator_registry = generator_registry
    session.cursor.initial_outer_measurement_cache = None
    session.cursor.prune_trust_state = restored_prune_state
    session.cursor.operator_admission_rounds = [
        int(operator.admission_round)
        for operator in hydration.operators
    ]
    session.cursor.beam_winning_branch_ids = tuple(
        str(value)
        for value in hydration.winning_beam_branch_ids
    )
    session.cursor.beam_search_diagnostics = (
        hydration.mutable_beam_search_diagnostics()
    )
    session.cursor.beam_resume_fork_local_lineage_s_alg = int(
        hydration.beam_fork_local_lineage_s_alg
    )
    session.cursor.resume_source_rounds = int(
        hydration.controller_round
    )
    session.cursor.resume_provenance = {
        "schema": "paper_i_canonical_accepted_state_resume_v1",
        "source_path": str(hydration.source_path),
        "source_sha256": str(hydration.source_sha256),
        "source_controller_round": int(hydration.controller_round),
        "source_s_alg": int(hydration.s_alg),
        "source_s_unique": int(hydration.s_unique),
        "strict_numerical_replay_passed": True,
        "route_and_problem_binding_passed": True,
    }
    session.initial_accepted_state = accepted_snapshot
    return session


def _freeze_canonical_sr_snake_infrastructure(value: Any) -> Any:
    """Recursively freeze the direct-session closure held at module scope."""

    if isinstance(value, Mapping):
        return MappingProxyType(
            {
                str(key): _freeze_canonical_sr_snake_infrastructure(item)
                for key, item in value.items()
            }
        )
    if isinstance(value, (list, tuple)):
        return tuple(
            _freeze_canonical_sr_snake_infrastructure(item)
            for item in value
        )
    if isinstance(value, (set, frozenset)):
        return frozenset(
            _freeze_canonical_sr_snake_infrastructure(item)
            for item in value
        )
    return copy.deepcopy(value)


def _thaw_canonical_sr_snake_infrastructure(value: Any) -> Any:
    """Return one mutable runtime copy from the frozen direct closure."""

    if isinstance(value, Mapping):
        return {
            str(key): _thaw_canonical_sr_snake_infrastructure(item)
            for key, item in value.items()
        }
    if isinstance(value, tuple):
        return [
            _thaw_canonical_sr_snake_infrastructure(item)
            for item in value
        ]
    if isinstance(value, frozenset):
        return {
            _thaw_canonical_sr_snake_infrastructure(item)
            for item in value
        }
    return copy.deepcopy(value)


