def _build_canonical_sr_snake_runtime_kwargs(
    *,
    resolved_problem_context: ResolvedProblemContext,
    maximum_controller_rounds: int,
    exact_energy: float,
    exact_target_absolute_tolerance: float | None,
    exact_target_energy: float | None,
    checkpoint_path: Path | None,
    checkpoint_every_controller_rounds: int | None,
    checkpoint_keep_history_tail: int | None,
    route_profile_request: str,
    route_profile: str,
    route_contract: Mapping[str, Any],
    route_contract_sha256: str,
    gradient_tolerance: float | None = None,
) -> dict[str, Any]:
    """Compose the exact controller inputs from typed facade dependencies.

    This is deliberately not a second CLI surface: scientific settings enter
    only through the already-authenticated route contract, while the resolved
    problem and observation values retain their typed identities.
    """

    if not isinstance(resolved_problem_context, ResolvedProblemContext):
        raise TypeError("resolved_problem_context must be ResolvedProblemContext.")
    execution_settings_raw = route_contract.get("execution_settings")
    if not isinstance(execution_settings_raw, Mapping):
        raise ValueError("The canonical SR-SNAKE route lacks execution settings.")
    execution_settings = dict(execution_settings_raw)
    physical = resolved_problem_context.request
    child_padding_policy = str(
        execution_settings["phase3_runtime_split_child_padding_policy"]
    )
    if child_padding_policy == ROUTE_A_CHILD_PADDING_UNCHECKED_DIAGNOSTIC_V1:
        child_padding = RouteAChildPaddingConfig(policy=child_padding_policy)
    else:
        child_padding = RouteAChildPaddingConfig(
            policy=child_padding_policy,
            problem_key=str(resolved_problem_context.family_key),
            num_sites=int(physical.num_sites),
            n_ph_max=int(physical.n_ph_max),
            boson_encoding=str(physical.boson_encoding),
            total_register_width=int(
                resolved_problem_context.layout.total_qubits
            ),
        )

    kwargs = _thaw_canonical_sr_snake_infrastructure(
        _CANONICAL_SR_SNAKE_RUNTIME_INFRASTRUCTURE
    )
    if not isinstance(kwargs, dict):
        raise AssertionError("Canonical SR-SNAKE infrastructure must thaw to dict.")
    resolved_extensions = extensions_from_route_contract(route_contract)
    kwargs.update(without_extension_runtime_keys(execution_settings))
    kwargs.update(
        {
            "h_poly": resolved_problem_context.hamiltonian,
            "resolved_problem_context": resolved_problem_context,
            "num_sites": int(physical.num_sites),
            "ordering": str(physical.ordering),
            "problem": str(resolved_problem_context.family_key),
            "molecular_problem_json": physical.molecular_problem_json,
            "molecular_vibronic_h2_fixture_json": (
                physical.molecular_vibronic_h2_fixture_json
            ),
            "molecular_vibronic_h2o_fixture_json": (
                physical.molecular_vibronic_h2o_fixture_json
            ),
            "molecular_vibronic_h2o_linear_fd_fixture_json": (
                physical.molecular_vibronic_h2o_linear_fd_fixture_json
            ),
            "t": float(physical.t),
            "u": float(physical.u),
            "dv": float(physical.dv),
            "v_nn": float(physical.v_nn),
            "t_prime": float(physical.t_prime),
            "n_fermions": (
                None
                if physical.n_fermions is None
                else int(physical.n_fermions)
            ),
            "boundary": str(physical.boundary),
            "omega0": float(physical.omega0),
            "g_ep": float(physical.g_ep),
            "n_ph_max": int(physical.n_ph_max),
            "boson_encoding": str(physical.boson_encoding),
            "include_zero_point": bool(physical.include_zero_point),
            "max_depth": int(maximum_controller_rounds),
            "benchmark_target_abs_delta_e": exact_target_absolute_tolerance,
            "benchmark_target_reference_energy": exact_target_energy,
            "adapt_current_json": checkpoint_path,
            "adapt_current_json_every_depth": (
                1
                if checkpoint_every_controller_rounds is None
                else int(checkpoint_every_controller_rounds)
            ),
            "adapt_current_json_keep_history_tail": (
                100
                if checkpoint_keep_history_tail is None
                else int(checkpoint_keep_history_tail)
            ),
            "adapt_estimator_call_ledger_enabled": True,
            "maxiter": int(execution_settings["adapt_maxiter"]),
            "seed": int(execution_settings["adapt_seed"]),
            "allow_repeats": bool(execution_settings["adapt_allow_repeats"]),
            "disable_hh_seed": bool(
                execution_settings["adapt_disable_hh_seed"]
            ),
            "finite_angle": float(execution_settings["adapt_finite_angle"]),
            "finite_angle_fallback": bool(
                execution_settings["adapt_finite_angle_fallback"]
            ),
            "finite_angle_min_improvement": float(
                execution_settings["adapt_finite_angle_min_improvement"]
            ),
            "adapt_final_full_refit": (
                str(execution_settings["adapt_final_full_refit"])
                .strip()
                .lower()
                == "true"
            ),
            "adapt_formal_manifold_config": None,
            "route_a_child_padding_config": child_padding,
            "exact_gs_override": float(exact_energy),
            "psi_ref_override": None,
            "psi_ref_source": str(
                resolved_problem_context.reference_state.source_label
            ),
            "psi_ref_handoff_state_kind": str(
                resolved_problem_context.reference_state.state_kind
            ),
            "sr_route_profile_request": str(route_profile_request),
            "sr_route_profile_resolved": str(route_profile),
            "sr_route_profile_contract": dict(route_contract),
            "sr_route_profile_contract_sha256": str(route_contract_sha256),
            "extensions": resolved_extensions,
        }
    )
    if gradient_tolerance is not None:
        threshold = float(gradient_tolerance)
        if not math.isfinite(threshold) or threshold <= 0.0:
            raise ValueError("gradient_tolerance must be positive and finite.")
        kwargs["eps_grad"] = threshold
    return kwargs


_CANONICAL_SR_SNAKE_LEGACY_EXECUTOR_PARAMETER_NAMES = frozenset(
    inspect.signature(_run_hardcoded_adapt_vqe).parameters
)


def _canonical_sr_snake_legacy_executor_kwargs(
    runtime_kwargs: Mapping[str, Any],
) -> dict[str, Any]:
    """Project direct runtime state onto the explicit legacy callable only."""

    return {
        str(key): value
        for key, value in runtime_kwargs.items()
        if str(key) in _CANONICAL_SR_SNAKE_LEGACY_EXECUTOR_PARAMETER_NAMES
    }


def _build_default_sr_controller_numerical_runtime(
    *,
    stop_policy: SRStopPolicy,
    executor_kwargs: Mapping[str, Any],
    admission_policy: (
        SingletonAdmission
        | GreedyBatchAdmission
        | CombinatorialBatchAdmission
    ) = SingletonAdmission(),
    resume_hydration: Any | None = None,
    candidate_adapter: Any | None = None,
) -> _DefaultNoPruneNumericalSession:
    """Build the exact-gated numerical session used by the RA controller."""

    if not isinstance(stop_policy, SRStopPolicy):
        raise TypeError("stop_policy must be an SRStopPolicy.")
    if not isinstance(
        admission_policy,
        (
            SingletonAdmission,
            GreedyBatchAdmission,
            CombinatorialBatchAdmission,
        ),
    ):
        raise TypeError(
            "admission_policy must be singleton, greedy batch, or "
            "combinatorial batch admission."
        )
    kwargs = dict(executor_kwargs)
    if int(kwargs.get("max_depth", -1)) != int(
        stop_policy.maximum_controller_rounds
    ):
        raise ValueError(
            "Default controller maximum rounds disagree with the resolved "
            "numerical runtime."
        )
    active_segment_controls = tuple(
        key
        for key in (
            "adapt_segment_target_depth",
            "adapt_segment_max_new_admissions",
            "adapt_segment_wallclock_cap_s",
        )
        if kwargs.get(key) is not None
    )
    if active_segment_controls:
        raise ValueError(
            "The default controller runtime cannot delegate stopping to "
            "legacy segment controls: "
            + ", ".join(active_segment_controls)
        )
    if bool(kwargs.get("adapt_final_full_refit", False)):
        raise ValueError(
            "The default controller runtime cannot mutate the accepted state "
            "with a legacy terminal full refit."
        )
    beam_enabled = bool(
        int(kwargs.get("adapt_beam_live_branches", 1) or 1) > 1
        or int(kwargs.get("adapt_beam_children_per_parent", 1) or 1) > 1
    )
    singleton_profile_digests = {
        (
            SR_ROUTE_PROFILE_NO_PRUNE_SYMMETRIC_COST_PROJECTED_PHASE3_NO_OVERLAP_TRUST_V1,
            _canonical_default_sr_controller_contract_sha256(),
        ),
        (
            SR_ROUTE_PROFILE_INSERTION_COMMUTATION_PLATEAU_V1,
            _canonical_insertion_v1_sr_controller_contract_sha256(),
        ),
        (
            SR_ROUTE_PROFILE_INSERTION_COMMUTATION_PLATEAU_V2,
            _canonical_insertion_sr_controller_contract_sha256(),
        ),
        (
            SR_ROUTE_PROFILE_NO_PRUNE_SYMMETRIC_COST_PROJECTED_PHASE3_NO_OVERLAP_TRUST_COMMUTATION_REDUCED_INSERTION_V1,
            _canonical_commutation_reduced_insertion_sr_controller_contract_sha256(),
        ),
        (
            SR_ROUTE_PROFILE_SYMMETRIC_COST_PROJECTED_PHASE3_NO_OVERLAP_TRUST_FULL_GEOMETRY_FS_PRUNE_VERIFY_V1,
            _canonical_prune_sr_controller_contract_sha256(),
        ),
    }
    observed_profile_digest = (
        str(kwargs.get("sr_route_profile_resolved", "")),
        str(kwargs.get("sr_route_profile_contract_sha256", "")),
    )
    default_singleton_selection_active = (
        _uses_default_singleton_selection(
            route_profile=str(
                kwargs.get("sr_route_profile_resolved", "")
            ),
            route_profile_sha256=str(
                kwargs.get(
                    "sr_route_profile_contract_sha256",
                    "",
                )
            ),
            beam_enabled=beam_enabled,
        )
    )
    ra_adapt_contract = _validated_ra_adapt_route_contract(
        kwargs,
        candidate_adapter=candidate_adapter,
    )
    composed_contract = _validated_canonical_composed_route_contract(kwargs)
    if ra_adapt_contract is not None:
        route_gate_open = True
    elif composed_contract is not None:
        route_gate_open = True
    elif isinstance(admission_policy, GreedyBatchAdmission):
        expected_profile_digest = (
            SR_ROUTE_PROFILE_GREEDY_BATCH_PROJECTED_PHASE3_NO_OVERLAP_TRUST_V1,
            canonical_sr_snake_greedy_batch_projected_phase3_no_overlap_trust_v1_contract_sha256(
                maximum_size=admission_policy.maximum_size,
                search_window_size=admission_policy.search_window_size,
            ),
        )
        route_gate_open = observed_profile_digest == expected_profile_digest
    elif isinstance(admission_policy, CombinatorialBatchAdmission):
        expected_profile_digest = (
            SR_ROUTE_PROFILE_COMBINATORIAL_BATCH_PROJECTED_PHASE3_NO_OVERLAP_TRUST_V1,
            canonical_sr_snake_combinatorial_batch_projected_phase3_no_overlap_trust_v1_contract_sha256(
                maximum_size=admission_policy.maximum_size,
                search_window_size=(
                    admission_policy.resolved_search_window_size
                ),
            ),
        )
        route_gate_open = observed_profile_digest == expected_profile_digest
    else:
        route_gate_open = bool(
            observed_profile_digest in singleton_profile_digests
            and default_singleton_selection_active
        )
    if not route_gate_open:
        raise ValueError(
            "The default controller runtime factory requires the exact "
            "profile and digest gate."
        )
    session = _initialize_default_no_prune_numerical_session(
        kwargs,
        admission_policy=admission_policy,
        candidate_adapter=candidate_adapter,
    )
    if resume_hydration is not None:
        session = _hydrate_default_no_prune_numerical_session(
            session,
            resume_hydration,
        )
    return session


_BOSON_SUBSPACE_DIAGNOSTIC_PROBLEMS = frozenset(
    {"bose_hubbard", "harmonic_kerr_chain", "hh", "spin_boson"}
)


def _state_boson_codeword_legal_probability(
    statevector: np.ndarray,
    *,
    problem_key: str,
    num_sites: int,
    n_ph_max: int,
    boson_encoding: str,
) -> tuple[float, dict[str, Any]]:
    """Return prepared-state probability in the problem's legal boson codeword subspace."""

    psi = np.asarray(statevector, dtype=complex).reshape(-1)
    dim = int(psi.shape[0])
    if dim <= 0 or dim & (dim - 1):
        raise ValueError(f"statevector dimension must be a power of two, got {dim}")
    total_register_width = int(dim.bit_length() - 1)
    layout = legal_subspace_basis_for_problem(
        problem_key=str(problem_key),
        num_sites=int(num_sites),
        n_ph_max=int(n_ph_max),
        boson_encoding=str(boson_encoding),
        total_register_width=int(total_register_width),
    )
    legal_indices = np.asarray(layout["legal_indices"], dtype=np.int64)
    legal_probability = float(np.sum(np.abs(psi[legal_indices]) ** 2).real)
    legal_probability = float(min(max(legal_probability, 0.0), 1.0))
    layout_metadata = {str(k): v for k, v in layout.items() if str(k) != "legal_indices"}
    layout_metadata["statevector_dim"] = int(dim)
    return legal_probability, layout_metadata


def _attach_boson_chain_subspace_diagnostics(
    adapt_payload: dict[str, Any],
    *,
    problem_key: str,
    psi_adapt: np.ndarray,
    psi_reference: np.ndarray,
    num_sites: int,
    n_ph_max: int,
    boson_encoding: str,
) -> None:
    """Attach prepared-state legal-codeword diagnostics for bosonic static families."""

    problem = str(problem_key).strip().lower()
    if problem not in _BOSON_SUBSPACE_DIAGNOSTIC_PROBLEMS:
        return
    try:
        final_legal, layout_metadata = _state_boson_codeword_legal_probability(
            np.asarray(psi_adapt, dtype=complex).reshape(-1),
            problem_key=problem,
            num_sites=int(num_sites),
            n_ph_max=int(n_ph_max),
            boson_encoding=str(boson_encoding),
        )
        reference_legal, reference_layout_metadata = _state_boson_codeword_legal_probability(
            np.asarray(psi_reference, dtype=complex).reshape(-1),
            problem_key=problem,
            num_sites=int(num_sites),
            n_ph_max=int(n_ph_max),
            boson_encoding=str(boson_encoding),
        )
        if dict(reference_layout_metadata) != dict(layout_metadata):
            layout_metadata = dict(layout_metadata)
            layout_metadata["reference_layout_metadata"] = dict(reference_layout_metadata)
        final_illegal = float(max(0.0, 1.0 - float(final_legal)))
        reference_illegal = float(max(0.0, 1.0 - float(reference_legal)))
    except Exception as exc:
        adapt_payload["boson_subspace_diagnostics"] = {
            "diagnostic_version": "boson_codeword_legal_subspace_v2",
            "available": False,
            "error": str(exc),
        }
        return
    adapt_payload["boson_subspace_diagnostics"] = {
        "diagnostic_version": "boson_codeword_legal_subspace_v2",
        "available": True,
        "problem": problem,
        "num_sites": int(num_sites),
        "n_ph_max": int(n_ph_max),
        "boson_encoding": str(boson_encoding),
        **dict(layout_metadata),
        "reference_legal_probability": float(reference_legal),
        "reference_illegal_probability": float(reference_illegal),
        "final_legal_probability": float(final_legal),
        "final_illegal_probability": float(final_illegal),
        "boson_legal_probability_min": float(min(reference_legal, final_legal)),
        "boson_illegal_probability_max": float(max(reference_illegal, final_illegal)),
    }


